 DECLARE @mode char(1)
 DECLARE @errmsg varchar(255)
 DECLARE @vPTyp varchar(8)
 DECLARE @wHCd VARCHAR(8)
 DECLARE @wSelfCoCd VARCHAR(3)
 DECLARE @ReplAgt BIT  
	
 IF @@ROWCOUNT=0   RETURN

 If Exists(Select 'x' From TrgDisa Where TdTblNm = 'vParam' )
  RETURN

 select @mode=case (select count('x') from inserted) when 0 then 'D'
       else
   case (select count('x') from deleted) when 0 then 'A' else 'C' end
       end

	set @wHCd = 'ZSELF'	
	set @wSelfCoCd= 'ZZZ'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ vPCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ vPCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

 	/******** Records Of Only One vPTyp Can Be Inserted At A Time ********/ 
	select @Row= Count(distinct(vPTyp)) from inserted 
	If @Row > 1
	Begin 
		Select @ErrMsg='Parameter Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/******** Records Of Only One vPTyp Can Be Deleted At A Time ********/ 
	select @Row= Count(distinct(vPTyp)) from deleted 
	If @Row > 1 
	Begin 
		Select @ErrMsg='Parameter Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/*** Storing PTyp In The Variable @PTyp ***/
	select @vPTyp= case  when @mode in ('C', 'A') then (Select max(vPTyp) from inserted)  else (Select max(vPTyp) from deleted) end  

	/******** If The Parameter Is A System Parameter Then No Add, Change Or Delete Allowed For The Param Entry *********/
	select @Row=Count('x') from vParam vPm where (@vPTyp= 'PTYP') or 
		(vPm.vPTyp= 'PTYP' and vPm.vPMCd= @vPTyp and vPm.vPValue= 'M')
	If @Row > 0
	begin 
		Select @ErrMsg='Cannot Add/Change/Delete Microway Parameter - '+ @vPTyp
		GoTo ErrHndlr
	end		

 	/******** Key Cannot Be Changed  (i.e.vPCoCd, vPTyp, vPMCd and vPSCd cannot be changed) ********/ 
 	If @mode = 'C'
 	Begin
  		select @Row=Count('x') from deleted del where
    		not exists (Select 'x' from inserted ins where ins.vPCoCd= del.vPCoCd and 
			ins.vPTyp= del.vPTyp and ins.vPMCd= del.vPmCd and ins.vPSCd= del.vPSCd)
  		If @Row > 0
	  	begin 
			Select @ErrMsg='Cannot Change Variable Param Key'
			GoTo ErrHndlr
		end
	End

	if @mode in ('A','C')
	BEGIN
		/*** Only a valid vPTyp can be entered (i.e. a valid vPMCd from Param where vPTyp= 'vPTYP') ***/
		select @row= count('x') from inserted ins where ins.vPTyp<> 'PTYP' and 
		not exists (select 'x' from vParam Prm where Prm.vPCoCd= @wSelfCoCd and 
					Prm.vPTyp= 'PTYP' and Prm.vPMCd= ins.vPTyp)
		if @row> 0 
		begin
			select @errmsg= 'Variable Parameter Type Not Defined'
			goto ErrHndlr
		end

		/****** vPCoCd= valid HCoCd ******/
		select @row= count('x') from inserted ins where not exists
			 (select 'x' from Head where HCoCd= vPCoCd and HCd= @wHCd)
		if @row>0 
		begin
			select @errmsg= 'Company Code Not Defined'
			goto ErrHndlr
		end

		/*** Only a valid vPTyp can be entered (i.e. a valid vPMCd from Param where vPTyp= 'vPTYP') ***/
		select @row= count('x') from inserted ins where ins.vPTyp= 'PTYP' and 
			ins.vPCoCd<> @wSelfCoCd 
		if @row> 0 
		begin
			select @errmsg= 'For PTyp= ''PTYP'', the Company Code should Be '+@wSelfCoCd
			goto ErrHndlr
		end

		/*** vPMCd cannot be Blank ***/
		select @row=count('x') from inserted where vPMCd= ''
		if @row>0 
		begin
	   		select @errmsg='Main Code Cannot Be Blank'
   			goto ErrHndlr
  		end
		/*** vPDesc cannot be blank ***/
		/* ******* Geeta CRM 2.12 ******** */
		select @row=count('x') from inserted where vPDesc= '' and vPTyp<>'CRMWIW'
		if @row>0 
		begin
			select @errmsg='Description Cannot Be Blank'
			goto ErrHndlr
  		end

		if @vPTyp= 'CHR' 
		Begin 
			/****** vPMCd= valid Tc ******/
			select @row= count('x') from inserted ins where 
				not exists (select 'x' from Param Prm where Prm.PTyp= 'TC' 
			      			and Prm.PMCd= ins.vPMCd)
			if @row> 0 
			begin
				select @errmsg= 'Tc Not Defined'
				goto ErrHndlr
			end
			/****** vPSCd= Not Blank ******/
			select @row= count('x') from inserted where vPSCd= ''
			if @row>0 
			begin
				select @errmsg= 'Character Code Cannot Be Blank'
				goto ErrHndlr
			end
			/****************Geeta**Crm*2.12************************************/
			select @row= count('x') from inserted ins where vPSCd='WEB' and 
				(Not Exists(Select 'x' From SysDb where SysId='CRM') Or 
				Not Exists (Select 'x' From Param 
					where PTyp='TC' and PMCd=vPMCd  and PValue in ('SO','QT','QS','MF')))
			if @row>0 
			begin
				select @errmsg= 'WEB Chr can be Used Only for ''SO'',''QS'',''QT'',''MF'' in CRM Database  '
				goto ErrHndlr
			end
			/****Geeta*****Crm**************/  
			select @row= count('x') from inserted ins where vPCoCd='WEB' and  vPSCd<>'WEB'	
			if @row>0   
			begin  
				select @errmsg= 'Character Other than ''WEB'' cannot be defined for CoCd=''WEB''  '  
				goto ErrHndlr  
			end  
			/****** vPValue= Valid Raw Material Loc ******/
			select @row= count('x') from inserted where vPValue<>'' and 
				not exists (select 'x' from Loc where LocCoCd = vPCoCd 
					and LocTyp<> 'P' and LocCd= vPValue)
			if @row>0 
			begin
				select @errmsg= 'Default From Raw Material Location Not Defined'
				goto ErrHndlr
			end
			/****** vPNum= 0 ******/
			select @row= count('x') from inserted where vPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum Should Be Zero'
				goto ErrHndlr
			end
			/****** vPDesc225= Valid Raw Material Loc ******/
			select @row= count('x') from inserted where vPDesc225<> '' and 
				not exists (select 'x' from Loc where LocCoCd= vPCoCd 
						and LocTyp<> 'P' and LocCd= vPDesc225)
			if @row>0 
			begin
				select @errmsg= 'Default To Raw Material Location Not Defined'
				goto ErrHndlr
			end
			/****** vPValue1= Valid Bag Loc ******/
			select @row= count('x') from inserted where vPValue1<> '' and 
				not exists (select 'x' from Loc where LocCoCd= vPCoCd 
						and LocTyp= 'P' and LocCd= vPValue1)
			if @row>0 
			begin
				select @errmsg= 'Default Bag Location Not Defined'
				goto ErrHndlr
			end
			/****** vPNum1= 0 ******/
			select @row= count('x') from inserted where vPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** vPValue2= 'D' or 'C' (Raw Material Debit Or Credit) ******/
			select @row= count('x') from inserted ins where ins.vPValue2<> '' and 
					not exists (select 'x' from Param Prm where Prm.PTyp= 'DC' 
        						and Prm.PMCd= ins.vPValue2)
			if @row>0 
			begin
				select @errmsg= 'Default Raw Material Debit / Credit Not Defined'
				goto ErrHndlr
			end

			/****** vPValue3 = Y/N ******/
			select @row=count('x') from inserted ins where 
				not exists (select 'x' from Param Prm where Prm.PTyp= 'YN' 
					    and Prm.PMCd= ins.vPValue3)

			if @row>0 
			begin
				select @errmsg= 'TrialChr Should Be Y/N'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where vPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'vPValidYN Should Be Blank'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */
		End


		if @vPTyp= 'DEFCHR' 
		Begin 
			/****** vPMCd= valid Tc ******/
			select @row= count('x') from inserted ins where 
				not exists (select 'x' from Param Prm where Prm.PTyp= 'TC' 
			      			and Prm.PMCd= ins.vPMCd)
			if @row>0 
			begin
				select @errmsg= 'Tc Not Defined'
				goto ErrHndlr
			end
			/****** vPSCd = Blank ******/
			select @row=count('x') from inserted where vPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end

			/****** vPValue= Valid vPSCd ('CHR') ******/
			select @row= count('x') from inserted ins where vPValue<> '' and 
				not exists (select 'x' from vParam Prm where 
						Prm.vPCoCd= ins.vPCoCd and Prm.vPTyp= 'CHR' 
						and Prm.vPMCd= ins.vPMCd 
						and Prm.vPSCd= ins.vPValue)
			if @row> 0 
			begin
				select @errmsg= 'Default Character Not Defined'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where vPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'vPValidYN Should Be Blank'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */
			/*********Geeta*******Emr207************/
			/****** vPValalue4 = Blank ******/
			select @row= count('x') from inserted where vPValue4<> ''
			if @row>0
			begin
				select @errmsg= 'vPValue4 Should Be Blank'
				goto ErrHndlr
			end
			/*********Geeta*******Emr207************/

		End

/****************** urmi FgSubLoc 10/8/03 *************************************************/
		if @vPTyp = 'FGSUBLOC' 
		Begin 
			/****** vPSCd = Blank ******/
			select @row= count('x') from inserted where vPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue = Blank ******/
			select @row= count('x') from inserted ins where vPValue<> '' 
			if @row> 0 
			begin
				select @errmsg= 'vPValue Should Be Blank'
				goto ErrHndlr
			end
			/****** vPNum = 0 ******/
			select @row=count('x') from inserted where vPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum Should Be Zero'
				goto ErrHndlr
			end
			/****** vPDesc225 = Blank ******/
			select @row=count('x') from inserted where vPDesc225<> ''
			if @row>0 
			begin
				select @errmsg= 'vPDesc225 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue1 = Blank ******/
			select @row=count('x') from inserted where vPValue1<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue1 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPNum1 = 0 ******/
			select @row=count('x') from inserted where vPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** vPValue2 = Blank ******/
			select @row=count('x') from inserted where vPValue2<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue2 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue3 = Blank ******/
			select @row=count('x') from inserted where vPValue3<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue3 Should Be Blank'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where vPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'vPValidYN Should Be Blank'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */
			/*********Geeta*******Emr207************/
			/****** vPValalue4 = Blank ******/
		/*	select @row= count('x') from inserted where vPValue4<> ''
			if @row>0
			begin
				select @errmsg= 'vPValue4 Should Be Blank'
				goto ErrHndlr
			end */
			/*********Geeta*******Emr207************/

		End
/***************************************************************************************/

		if @vPTyp= 'LINE' 
		Begin 
			/****** First insert 'ZZZ' line for a Company ******/ 
			select @row= count('x') from inserted ins where vPMCd<> @wSelfCoCd and 
				not exists (Select 'x' from vParam vPrm 
					    where vPrm.vPCoCd= ins.vPCoCd 
						  and vPrm.vPTyp= ins.vPTyp 
						  and vPrm.vPMCd= @wSelfCoCd) 
			if @row> 0 
			begin
				select @errmsg= 'First Insert ''ZZZ'' For This Company' 
				goto ErrHndlr
			end

			/****** vPSCd = Blank ******/
			select @row= count('x') from inserted where vPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue = Blank ******/
			select @row= count('x') from inserted ins where vPValue<> '' 
			if @row> 0 
			begin
				select @errmsg= 'vPValue Should Be Blank'
				goto ErrHndlr
			end
			/****** vPNum = 0 ******/
			select @row=count('x') from inserted where vPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum Should Be Zero'
				goto ErrHndlr
			end
			/****** vPDesc225 = Blank ******/
			select @row=count('x') from inserted where vPDesc225<> ''
			if @row>0 
			begin
				select @errmsg= 'vPDesc225 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue1 = Blank ******/
			select @row=count('x') from inserted where vPValue1<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue1 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPNum1 = 0 ******/
			select @row=count('x') from inserted where vPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** vPValue2 = Blank ******/
			select @row=count('x') from inserted where vPValue2<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue2 Should Be Blank'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where vPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'vPValidYN Should Be Blank'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */
			/*********Geeta*******Emr207************/
			/****** vPValalue4 = Blank ******/
			select @row= count('x') from inserted where vPValue4<> ''
			if @row>0
			begin
				select @errmsg= 'vPValue4 Should Be Blank'
				goto ErrHndlr
			end
			/*********Geeta*******Emr207************/

		End

		if @vPTyp= 'PRDSEQ' 
		Begin 
			/****** vPSCd = Blank ******/
			select @row=count('x') from inserted where vPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue = Blank or a Valid Plan Sequence ******/
			select @row=count('x') from inserted ins where ins.vPValue<> '' and 
				not exists (select 'x' from Param Prm where Prm.PTyp= 'PLNSEQ' and Prm.PMCd= ins.vPValue)
			if @row>0 
			begin
				select @errmsg= 'Plan Sequence Not Defined'
				goto ErrHndlr
			end
			/****** vPnum = 0 ******/
			select @row=count('x') from inserted where vPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum Should Be Zero'
				goto ErrHndlr
			end
/*** ###
			select @row=count('x') from inserted where PDesc225<> '' and 
			if @row>0 
			begin
				select @errmsg= 'Location In Sequence Not Defined '
				goto ErrHndlr
			end
***/

			/****** vPValue1 = Blank ******/
			select @row=count('x') from inserted where vPValue1<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue1 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPNum1 = 0 ******/
			select @row=count('x') from inserted where vPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** vPValue2 = Blank ******/
			select @row=count('x') from inserted where vPValue2<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue2 Should Be Blank'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where vPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'vPValidYN Should Be Blank'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */
			/*********Geeta*******Emr207************/
			/****** vPValalue4 = Blank ******/
			select @row= count('x') from inserted where vPValue4<> ''
			if @row>0
			Begin
				select @errmsg= 'vPValue4 Should Be Blank'
				goto ErrHndlr
			End
			/*********Geeta*******Emr207************/

		End

		if @vPTyp= 'PTYP' 
		Begin 
			/****** vPSCd = Blank ******/
			select @row= count('x') from inserted where vPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue = 'Y' or 'N' ******/
			select @row=count('x') from inserted ins where 
				not exists (select 'x' from Param Prm where Prm.PTyp= 'SYSDFN' and Prm.PMCd= ins.vPValue)
			if @row>0 
			begin
				select @errmsg= 'Enter Type Of Parameter (Y/N/M)'
				goto ErrHndlr
			end
			/****** vPNum = 0 ******/
			select @row=count('x') from inserted where vPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum Should Be Zero'
				goto ErrHndlr
			end
			/****** vPDesc225 = Blank ******/
			select @row=count('x') from inserted where vPDesc225<> ''
			if @row>0 
			begin
				select @errmsg= 'vPDesc225 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue1 = Blank ******/
			select @row=count('x') from inserted where vPValue1<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue1 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPNum1 = 0 ******/
			select @row=count('x') from inserted where vPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** vPValue2 = Blank ******/
			select @row=count('x') from inserted where vPValue2<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue2 Should Be Blank'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where vPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'vPValidYN Should Be Blank'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */
			/*********Geeta*******Emr207************/
			/****** vPValalue4 = Blank ******/
			select @row= count('x') from inserted where vPValue4<> ''
			if @row>0
			begin
				select @errmsg= 'vPValue4 Should Be Blank'
				goto ErrHndlr
			end
			/*********Geeta*******Emr207************/

		End

		if @vPTyp in ('WIWSEQ', 'WIWLONG') 
		Begin 
			/****** vPSCd = Blank ******/
			select @row=count('x') from inserted where vPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue = Blank ******/
			select @row=count('x') from inserted where vPValue<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue Shold Be Blank'
				goto ErrHndlr
			end
			/****** vPNum = 0 ******/
			select @row=count('x') from inserted where vPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum Should Be Zero'
				goto ErrHndlr
			end
			/*** ### 
			select @row=count('x') from inserted where PDesc225<> '' and 
			if @row>0 
			begin
				select @errmsg= 'Location In Sequence Not Defined '
				goto ErrHndlr
			end
			***/
			/****** vPValue1 = Blank ******/
			select @row= count('x') from inserted where vPValue1<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue1 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPNum1 = 0 ******/
			select @row=count('x') from inserted where vPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** vPValue2 = Blank ******/
			select @row=count('x') from inserted where vPValue2<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue2 Should Be Blank'
				goto ErrHndlr
			end
			/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = Blank ******/
			select @row= count('x') from inserted where vPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'vPValidYN Should Be Blank'
				goto ErrHndlr
			end
			/*  #########################################  Manoj  #########################################  */
			/*********Geeta*******Emr207************/
			/****** vPValalue4 = Blank ******/
			Select @row= count('x') from inserted where vPValue4<> ''
			If @row>0
			Begin
				select @errmsg= 'vPValue4 Should Be Blank'
				goto ErrHndlr
			End
			/*********Geeta*******Emr207************/

			/****** Sachin 2.14.0 - 07-11-06 [Multi-Company] ****** */
			/****** Invalid PValue3 [Parent Code] ******/
			Select @row= count('x') From Inserted Ins Where Ins.vPValue3 = '' Or 
				Not Exists(Select 'x' From Param Where PTyp='YN' And PMCd=Ins.vPValue3)					
			If @row>0
			Begin
				select @errmsg= 'Invalid Parent Code - YN'
				goto ErrHndlr
			End

			If @mode = 'A'
 			Begin
				/* ****** WIWSEQ/WIWLONG if Not Present In the ZZZ Company will be Added to It ****** */
				Select @Row=Count('x') From Inserted Ins Where Ins.vPCoCd<>@wSelfCoCd And Ins.vPTyp In ('WIWSEQ','WIWLONG') And Ins.vPValue3='N' 
					And Not Exists (Select 'x' From vParam ZWIW Where ZWIW.vPCoCd=@wSelfCoCd And Ins.vPTyp=ZWIW.vPTyp And Ins.vPMCd=ZWIW.vPMCd 
					And Ins.vPValue3=ZWIW.vPValue3)  			
				If @Row > 0
				Begin
					Insert Into vParam (vPCoCd, vPTyp, vPMCd, vPSCd, vPDesc, vPDesc225, vPValue, vPNum, vPValue1, vPNum1, vPValue2,
							vPValue3, ModUsr, ModDt, ModTime, vPValidYN, vPValue4)  
						Select @wSelfCoCd, vPTyp, vPMCd, vPSCd, vPDesc, vPDesc225, vPValue, vPNum, vPValue1, vPNum1, 
							vPValue2, vPValue3, ModUsr, ModDt, ModTime, vPValidYN, vPValue4 From Inserted 				
				End
				/* *** JAY 3.2.0 [AutoTree] */ 
				if @vPTyp= 'TRDEF' 
				Begin 
					select @row=count('x') from Inserted Ins 
					if @row>0 
					Begin
					select @errmsg='Cannot Insert Record'
						goto ErrHndlr
					end
				end
				/* *** JAY 3.2.0 [AutoTree] */ 
			End
	

			/****** WIWSEQ,WIWLONG Sequence Has to be Subset of 'ZZZ'   ******/
			/*
			Select @row= count('x') From Inserted Ins Where Ins.vPCoCd<>@wSelfCoCd And Ins.vPTyp In ('WIWSEQ','WIWLONG')
			If @row>0
			Begin
				select @errmsg= '''WIWSEQ'' And ''WIWLONG'' Can Be Added/Edited Only Through the ''ZZZ'' Company Code'
				goto ErrHndlr
			End			
			*/
			/****** Sachin 2.14.0 - 07-11-06 [Multi-Company] ****** */
			
		End

		If @vPTyp= 'WORK' 
		Begin 
			/****** vPSCd = Blank ******/ 
			select @row= count('x') from inserted where vPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue = Blank or valid Process Loc ******/
			select @row= count('x') from inserted where vPValue<> '' and 
				not exists (select 'x' from Loc where LocCoCd= vPCoCd and LocTyp= 'P' and LocCd= vPValue)
			if @row>0 
			begin
				select @errmsg= 'Process Location Not Defined'
				goto ErrHndlr
			end
			/****** vPDesc225 = Blank ******/
			select @Row=count('x') from inserted where vPDesc225<> '' 
			if @row>0 
			begin
				select @errmsg= 'vPDesc225 Should Be Blank'
				goto ErrHndlr
			end
			/****Geeta***Emr208****/
			/****** vPValue1 = Valid Loc(vPCoCd,'L') ******/
			select @row=count('x') from inserted where vPValue1<> ''
			  and Not Exists (Select 'x' From Loc where LocCoCd=vPCoCd and 
					  LocTyp='L' and LocCd=vPvalue1)
			if @row>0 
			begin
				select @errmsg= 'Loss Location Not defined'
				goto ErrHndlr
			end

			/* *** Jay 2.14 *** */
			/****** vPNum1 >= 0 ******/
			Select @row=count('x') from inserted where vPNum1 < 0
			If @row>0 
			Begin
				Select @errmsg= 'Rupees Should >= Zero'
				Goto ErrHndlr
			End
			/****** vPNum1 = 0 *****
			select @row=count('x') from inserted where vPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum1 Should Be Zero'
				goto ErrHndlr
			end
			*/
			/* *** Jay 
 *** */

			/****** vPValue2 = Blank ******/
			select @row=count('x') from inserted where vPValue2<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue2 Should Be Blank'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = PMCD(YN) ******/
			select @row= count('x') from inserted ins where
				Not Exists (Select 'x' From Param Where PTyp = 'YN' And PMCD = ins.vPValidYN)
			if @row>0
			begin
				select @errmsg= 'PValidYN Not Defined'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */
			/***************************Geeta***Emr206*******************************/
			select @row= count('x') from inserted ins where ins.vPMCd ='ZSELF' and
				 ins.vPValidYN='N'
			if @row>0
			begin
				select @errmsg= ' ''ZSELF'' Cannot Be  Invalid'
				goto ErrHndlr
			end
			/***************************Geeta***Emr206*******************************/ 
		End

		/* ******* Geeta CRM 2.12 ******** */
		if @vPTyp = 'CRMWIW'
		Begin 
			/******* vPMCd should be Numeric *******/
			select @row= count('x') from inserted ins where
				Not(vPmCd in ('01','02','03','04','05'))
			if @row> 0
			begin
				select @errmsg= 'Please Enter Code One of These (01,02,03,04,05)'
				goto ErrHndlr
			end

			select @row= count('x') from inserted ins where vPdesc225<>'' and 
			( vPDesc='' or vPValue='')
			if @row>0 
			begin
				select @errmsg= 'Description / Display Name Cannot be Blank when Location Entered'
				goto ErrHndlr
			end

			/****** vPSCd = '' ******/
			select @row= count('x') from inserted where vPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'PSCd Should Be Blank'
				goto ErrHndlr
			end
			/****** vPNum = 0 ******/
			select @row= count('x') from inserted where vPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'PNum Should Be Zero'
				goto ErrHndlr
			end

			/****** vPValue1 = Blank ******/
			select @row= count('x') from inserted where vPValue1<> ''
			if @row>0 
			begin
				select @errmsg= 'PValue1 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPNum1 = 0 ******/
			select @row= count('x') from inserted where vPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** vPValue2 = Blank ******/
			select @row= count('x') from inserted where vPValue2<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue2 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue3 = Blank ******/
			select @row= count('x') from inserted where vPValue3<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue3 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValidYN = Blank ******/
			select @row= count('x') from inserted where vPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'vPValidYN Should Be Blank'
				goto ErrHndlr
			end
		End
	END

	if @mode in ('D')
	BEGIN
		/*** In Use Checks ***/
		/*** In Use Checks ***/
		/*** In Use Checks ***/
		/*** In Use Checks ***/
		/*** In Use Checks ***/
		/*** In Use Checks ***/

		if @vPTyp= 'CHR' 
		Begin 
			/****** Cannot delete Chr in use in vParam table where vPTyp= 'DEFCHR' ******/
			select @row= count('x') from deleted del where 
				exists (select 'x' from vParam Pm where Pm.vPCoCd= del.vPCoCd 
					and Pm.vPTyp= 'DEFCHR' and Pm.vPmCd= del.vPMCd 
					and Pm.vPValue= del.vPSCd) 
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete As Chr In Use In vParam Table Where vPTyp= ''DEFCHR'' '
				goto ErrHndlr
			end
			/****** Cannot delete Chr in use in Bag table ******/
			select @row= count('x') from deleted del where 
				exists (select 'x' from Bag where BCoCd= vPCoCd and 
							BOdTc= vPMCd and BOdChr= vPSCd)
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete As Chr In Use In Bag Table'
				goto ErrHndlr
			end
			/****** Cannot delete Chr in use in Fg table ******/
			select @row= count('x') from deleted del where 
				exists (select 'x' from Fg where FgCoCd= vPCoCd and FgTc= vPMCd and FgChr= vPSCd)
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete As Chr In Use In Fg Table'
				goto ErrHndlr
			end

			/****** Cannot delete Chr in use in Fgd table ******
			select @row= count('x') from deleted del where 
				exists (select 'x' from Fgd where FdCoCd = vPCoCd and (FdPrdOdTc= vPMCd and FdPrdOdChr= vPSCd) 
					or (FdExpOdTc= vPMCd and FdExpOdChr= vPSCd) or (FdInTc= vPMCd and FdInChr= vPSCd))
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete As Chr In Use In Fgd Table'
				goto ErrHndlr
			end
			*/

			/****** Cannot delete Chr in use in OrdMst table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdMst where OmCoCd= vPCoCd and OmTc= vPMCd and OmChr= vPSCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Chr In Use In OrdMst Table'
				goto ErrHndlr
			end
			/****** Cannot delete Chr in use in Txn table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Txn where TCoCd= vPCoCd and TTc= vPMCd and TChr= vPSCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Chr In Use In Txn Table'
				goto ErrHndlr
			end
			/****** Cannot delete Chr in use in TxndZ table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from TxndZ where TzCoCd= vPCoCd and TzTc= vPMCd and TzChr= vPSCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Chr In Use In TxndZ Table'
				goto ErrHndlr
			end
			/****** Cannot delete Chr in use in InvHd table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from InvHd where InCoCd= vPCoCd and InTc= vPMCd and InChr= vPSCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Chr In Use In Invoice Head Table'
				goto ErrHndlr
			end

			/****** Cannot delete Chr in use in MultiPrcQtMst table ******/
			/* ***** Manali 3.10.0 - Multi Price Qt Module *****/
			select @row=count('x') from deleted del where 
				exists (select 'x' from MultiPrcQtMst where MqmCoCd= vPCoCd and MqmTc= vPMCd and MqmChr= vPSCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Chr In Use In Multi Price Quotation Table'
				goto ErrHndlr
			end
		End


/******************************************************************************************/
		if @vPTyp= 'FGSUBLOC' 
		Begin 
			/****** Cannot delete FgSubLoc in use in Head table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Head where HCoCd= vPCoCd and HFgSubLoc= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As FgSubLoc In Use In Head Table'
				goto ErrHndlr
			end
			/****** Cannot delete FgSubLoc in use in Bag table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Bag where BCoCd= vPCoCd and BFgSubLoc= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As FgSubLoc In Use In Bag Table'
				goto ErrHndlr
			end
			/****** Cannot delete FgSubLoc in use in Fg table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from FG where FgCoCd= vPCoCd and FgSubLoc= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As FgsubLoc In Use In FG Table'
				goto ErrHndlr
			end
			/****** Cannot delete FgSubLoc in use in Fgd table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Fgd where FdCoCd= vPCoCd and FdSubLoc= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As FgsubLoc In Use In Fgd Table'
				goto ErrHndlr
			end

			/****** Cannot delete FgSubLoc in use in Fmd table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Fmd where FmdCoCd= vPCoCd and FmdFrFgSubLoc= vPMCd
					or FmdToFgSubLoc= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As FgsubLoc In Use In Fmd Table'
				goto ErrHndlr
			end
	
		End
/*****************************************************************************************/

		if @vPTyp= 'LINE' 
		Begin 
			/****** Cannot Delete 'ZZZ' Line For The Company If Other Line Rec Exists For The Company ******/ 
			select @row= count('x') from deleted del where vPMCd= @wSelfCoCd and 
				exists (Select 'x' from vParam vPrm 
					    where vPrm.vPCoCd= del.vPCoCd 
						  and vPrm.vPTyp= del.vPTyp 
						  and vPrm.vPMCd<> @wSelfCoCd) 
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete ''ZZZ'' Line For The Company If Other Line Rec Exists For The Company' 
				goto ErrHndlr
			end

			/****** Cannot delete Line in use in Head table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Head where HCoCd= vPCoCd and HLine= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As Line In Use In Head Table'
				goto ErrHndlr
			end
			/****** Cannot delete Line in use in OrdMst table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdMst where OmCoCd= vPCoCd and OmLine= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As Line In Use In OrdMst Table'
				goto ErrHndlr
			end
			/****** Cannot delete Line in use in OrdDsg table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdDsg where OdCoCd= vPCoCd and OdLine= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As Line In Use In OrdDsg Table'
				goto ErrHndlr
			end
			/****** Cannot delete Line in use in OrdPln table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdPln where OpCoCd= vPCoCd and OpLine= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As Line In Use In OrdPln Table'
				goto ErrHndlr
			end
		End

		if @vPTyp= 'PRDSEQ' 
		Begin 
			/****** Cannot delete Production Sequence in use in DsgMst table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from DsgMst where DmPrdSeq= vPMCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In DsgMst Table'
				goto ErrHndlr
			end
			/****** Cannot delete Production Sequence in use in Head table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Head where HCoCd= vPCoCd and HCd= @wHCd and hDmPrdSeq= vPMCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In Head Table'
				goto ErrHndlr
			end
			/****** Cannot delete Production Sequence in use in OrdDsg table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdDsg where OdCoCd= vPCoCd and OdPrdSeq= vPMCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In OrdDsg Table'
				goto ErrHndlr
			end

			/****** Cannot delete Production Sequence in use in Param table where PTyp= 'PRDCTG' ******
			select @row=count('x') from deleted del where 
				exists (select 'x' from Param Pm where Pm.PTyp= 'PRDCTG' and Pm.PValue= del.vPMCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In Param Table Where PTyp= 'PRDCTG''
				goto ErrHndlr
			end
			*/
		End

		if @vPTyp= 'WORK' 
		Begin 
			/****** Cannot delete Worker in use in Bag table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Bag where BCoCd= vPCoCd and BWrk= vPMCd)
			if @row>0 
			Begin
			select @errmsg='Cannot Delete As Worker In Use In Bag Table'
				goto ErrHndlr
			end
			/****** Cannot delete Worker in use in Txnd table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Txnd where TdCoCd= vPCoCd and (TdWrk= vPMCd or TdByWrk= vPMCd))
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Worker In Use In Txnd Table'
				goto ErrHndlr
			end
			/****** Cannot delete Worker in use in TxndPrd table ******/
			Select @row=count('x') from deleted del where 
				exists (select 'x' from TxndPrd where TpCoCd= vPCoCd and TpByWrk= vPMCd)
			If @row>0 
			Begin
				select @errmsg='Cannot Delete As Worker In Use In TxndPrd Table'
				goto ErrHndlr
			End
			/****** Bhavna Cannot delete Worker in use in TxndRwrk table ******/
			Select @row=count('x') from deleted del where 
				exists (select 'x' from TxndRwrk where TrwCoCd= vPCoCd and TrwByWrk= vPMCd)
			If @row>0 
			Begin
				select @errmsg='Cannot Delete As Worker In Use In TxndRwrk Table'
				goto ErrHndlr
			End

		End

		if @vPTyp In ('WIWSEQ' ,'WIWLONG')
		Begin 
			/* ****** WIWSEQ/WIWLONG Cannot be deleted From ZZZ if it exists in other companies ****** */
			Select @Row=Count('x') From Deleted Del Where Del.vPCoCd=@wSelfCoCd And Del.vPTyp In ('WIWSEQ','WIWLONG') And Del.vPValue3='N' 
				And Exists (Select 'x' From vParam vWIW Where vWIW.vPCoCd<>@wSelfCoCd And Del.vPTyp=vWIW.vPTyp And Del.vPMCd=vWIW.vPMCd 
							And Del.vPValue3=vWIW.vPValue3)  			
			If @Row > 0
			Begin
				select @errmsg= 'Cannot Delete As '+ @vPTyp + ' Sequence Exists in One of the Companies'
				goto ErrHndlr
			End
		End	
		/* *** JAY 3.2.0 [AutoTree] */ 
		if @vPTyp= 'TRDEF' 
		Begin 
			select @row=count('x') from deleted del 
			if @row>0 
			Begin
			select @errmsg='Cannot Delete Record'
				goto ErrHndlr
			end
		end
		/* *** JAY 3.2.0 [AutoTree] */ 
	End

	Return

ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
end

GOGO

/**********Kbs.123 Trigger ***************************************/

ALTER TRIGGER [dbo].[vParam_INUPDL] ON [dbo].[vParam] 
   For INSERT,UPDATE,DELETE NOT FOR REPLICATION
As
BEGIN
 /* Trigger Version 2.14.0 [Original] */	
 DECLARE @ROW INT
 DECLARE @mode char(1)
 DECLARE @errmsg varchar(255)
 DECLARE @vPTyp varchar(8)
 DECLARE @wHCd VARCHAR(8)
 DECLARE @wSelfCoCd VARCHAR(3)
 DECLARE @ReplAgt BIT  
	
 IF @@ROWCOUNT=0   RETURN

 If Exists(Select 'x' From TrgDisa Where TdTblNm = 'vParam' )
  RETURN

 select @mode=case (select count('x') from inserted) when 0 then 'D'
       else
   case (select count('x') from deleted) when 0 then 'A' else 'C' end
       end

	set @wHCd = 'ZSELF'	
	set @wSelfCoCd= 'ZZZ'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ vPCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ vPCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

 	/******** Records Of Only One vPTyp Can Be Inserted At A Time ********/ 
