 			Begin
				/* ****** WIWSEQ/WIWLONG if Not Present In the ZZZ Company will be Added to It ****** */
				Select @Row=Count('x') From Inserted Ins Where Ins.vPCoCd<>@wSelfCoCd And Ins.vPTyp In ('WIWSEQ','WIWLONG') And Ins.vPValue3='N' 
					And Not Exists (Select 'x' From vParam ZWIW Where ZWIW.vPCoCd=@wSelfCoCd And Ins.vPTyp=ZWIW.vPTyp And Ins.vPMCd=ZWIW.vPMCd 
					And Ins.vPValue3=ZWIW.vPValue3)  			
				If @Row > 0
				Begin
					Insert Into vParam (vPCoCd, vPTyp, vPMCd, vPSCd, vPDesc, vPDesc225, vPValue, vPNum, vPValue1, vPNum1, vPValue2,
							vPValue3, ModUsr, ModDt, ModTime, vPValidYN, vPValue4)  
						Select @wSelfCoCd, vPTyp, vPMCd, vPSCd, vPDesc, vPDesc225, vPValue, vPNum, vPValue1, vPNum1, 
							vPValue2, vPValue3, ModUsr, ModDt, ModTime, vPValidYN, vPValue4 From Inserted 				
				End
				/* *** JAY 3.2.0 [AutoTree] */ 
				if @vPTyp= 'TRDEF' 
				Begin 
					select @row=count('x') from Inserted Ins 
					if @row>0 
					Begin
					select @errmsg='Cannot Insert Record'
						goto ErrHndlr
					end
				end
				/* *** JAY 3.2.0 [AutoTree] */ 
			End
	

			/****** WIWSEQ,WIWLONG Sequence Has to be Subset of 'ZZZ'   ******/
			/*
			Select @row= count('x') From Inserted Ins Where Ins.vPCoCd<>@wSelfCoCd And Ins.vPTyp In ('WIWSEQ','WIWLONG')
			If @row>0
			Begin
				select @errmsg= '''WIWSEQ'' And ''WIWLONG'' Can Be Added/Edited Only Through the ''ZZZ'' Company Code'
				goto ErrHndlr
			End			
			*/
			/****** Sachin 2.14.0 - 07-11-06 [Multi-Company] ****** */
			
		End

		If @vPTyp= 'WORK' 
		Begin 
			/****** vPSCd = Blank ******/ 
			select @row= count('x') from inserted where vPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'Sub Code Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue = Blank or valid Process Loc ******/
			select @row= count('x') from inserted where vPValue<> '' and 
				not exists (select 'x' from Loc where LocCoCd= vPCoCd and LocTyp= 'P' and LocCd= vPValue)
			if @row>0 
			begin
				select @errmsg= 'Process Location Not Defined'
				goto ErrHndlr
			end
			/****** vPDesc225 = Blank ******/
			select @Row=count('x') from inserted where vPDesc225<> '' 
			if @row>0 
			begin
				select @errmsg= 'vPDesc225 Should Be Blank'
				goto ErrHndlr
			end
			/****Geeta***Emr208****/
			/****** vPValue1 = Valid Loc(vPCoCd,'L') ******/
			select @row=count('x') from inserted where vPValue1<> ''
			  and Not Exists (Select 'x' From Loc where LocCoCd=vPCoCd and 
					  LocTyp='L' and LocCd=vPvalue1)
			if @row>0 
			begin
				select @errmsg= 'Loss Location Not defined'
				goto ErrHndlr
			end

			/* *** Jay 2.14 *** */
			/****** vPNum1 >= 0 ******/
			Select @row=count('x') from inserted where vPNum1 < 0
			If @row>0 
			Begin
				Select @errmsg= 'Rupees Should >= Zero'
				Goto ErrHndlr
			End
			/****** vPNum1 = 0 *****
			select @row=count('x') from inserted where vPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum1 Should Be Zero'
				goto ErrHndlr
			end
			*/
			/* *** Jay 
 *** */

			/****** vPValue2 = Blank ******/
			select @row=count('x') from inserted where vPValue2<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue2 Should Be Blank'
				goto ErrHndlr
			end
/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
			/****** PValidYN = PMCD(YN) ******/
			select @row= count('x') from inserted ins where
				Not Exists (Select 'x' From Param Where PTyp = 'YN' And PMCD = ins.vPValidYN)
			if @row>0
			begin
				select @errmsg= 'PValidYN Not Defined'
				goto ErrHndlr
			end
/*  #########################################  Manoj  #########################################  */
			/***************************Geeta***Emr206*******************************/
			select @row= count('x') from inserted ins where ins.vPMCd ='ZSELF' and
				 ins.vPValidYN='N'
			if @row>0
			begin
				select @errmsg= ' ''ZSELF'' Cannot Be  Invalid'
				goto ErrHndlr
			end
			/***************************Geeta***Emr206*******************************/ 
		End

		/* ******* Geeta CRM 2.12 ******** */
		if @vPTyp = 'CRMWIW'
		Begin 
			/******* vPMCd should be Numeric *******/
			select @row= count('x') from inserted ins where
				Not(vPmCd in ('01','02','03','04','05'))
			if @row> 0
			begin
				select @errmsg= 'Please Enter Code One of These (01,02,03,04,05)'
				goto ErrHndlr
			end

			select @row= count('x') from inserted ins where vPdesc225<>'' and 
			( vPDesc='' or vPValue='')
			if @row>0 
			begin
				select @errmsg= 'Description / Display Name Cannot be Blank when Location Entered'
				goto ErrHndlr
			end

			/****** vPSCd = '' ******/
			select @row= count('x') from inserted where vPSCd<> ''
			if @row>0 
			begin
				select @errmsg= 'PSCd Should Be Blank'
				goto ErrHndlr
			end
			/****** vPNum = 0 ******/
			select @row= count('x') from inserted where vPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'PNum Should Be Zero'
				goto ErrHndlr
			end

			/****** vPValue1 = Blank ******/
			select @row= count('x') from inserted where vPValue1<> ''
			if @row>0 
			begin
				select @errmsg= 'PValue1 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPNum1 = 0 ******/
			select @row= count('x') from inserted where vPNum1<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum1 Should Be Zero'
				goto ErrHndlr
			end
			/****** vPValue2 = Blank ******/
			select @row= count('x') from inserted where vPValue2<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue2 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue3 = Blank ******/
			select @row= count('x') from inserted where vPValue3<> ''
			if @row>0 
			begin
				select @errmsg= 'vPValue3 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValidYN = Blank ******/
			select @row= count('x') from inserted where vPValidYN<> ''
			if @row>0
			begin
				select @errmsg= 'vPValidYN Should Be Blank'
				goto ErrHndlr
			end
		End
	END

	if @mode in ('D')
	BEGIN
		/*** In Use Checks ***/
		/*** In Use Checks ***/
		/*** In Use Checks ***/
		/*** In Use Checks ***/
		/*** In Use Checks ***/
		/*** In Use Checks ***/

		if @vPTyp= 'CHR' 
		Begin 
			/****** Cannot delete Chr in use in vParam table where vPTyp= 'DEFCHR' ******/
			select @row= count('x') from deleted del where 
				exists (select 'x' from vParam Pm where Pm.vPCoCd= del.vPCoCd 
					and Pm.vPTyp= 'DEFCHR' and Pm.vPmCd= del.vPMCd 
					and Pm.vPValue= del.vPSCd) 
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete As Chr In Use In vParam Table Where vPTyp= ''DEFCHR'' '
				goto ErrHndlr
			end
			/****** Cannot delete Chr in use in Bag table ******/
			select @row= count('x') from deleted del where 
				exists (select 'x' from Bag where BCoCd= vPCoCd and 
							BOdTc= vPMCd and BOdChr= vPSCd)
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete As Chr In Use In Bag Table'
				goto ErrHndlr
			end
			/****** Cannot delete Chr in use in Fg table ******/
			select @row= count('x') from deleted del where 
				exists (select 'x' from Fg where FgCoCd= vPCoCd and FgTc= vPMCd and FgChr= vPSCd)
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete As Chr In Use In Fg Table'
				goto ErrHndlr
			end

			/****** Cannot delete Chr in use in Fgd table ******
			select @row= count('x') from deleted del where 
				exists (select 'x' from Fgd where FdCoCd = vPCoCd and (FdPrdOdTc= vPMCd and FdPrdOdChr= vPSCd) 
					or (FdExpOdTc= vPMCd and FdExpOdChr= vPSCd) or (FdInTc= vPMCd and FdInChr= vPSCd))
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete As Chr In Use In Fgd Table'
				goto ErrHndlr
			end
			*/

			/****** Cannot delete Chr in use in OrdMst table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdMst where OmCoCd= vPCoCd and OmTc= vPMCd and OmChr= vPSCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Chr In Use In OrdMst Table'
				goto ErrHndlr
			end
			/****** Cannot delete Chr in use in Txn table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Txn where TCoCd= vPCoCd and TTc= vPMCd and TChr= vPSCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Chr In Use In Txn Table'
				goto ErrHndlr
			end
			/****** Cannot delete Chr in use in TxndZ table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from TxndZ where TzCoCd= vPCoCd and TzTc= vPMCd and TzChr= vPSCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Chr In Use In TxndZ Table'
				goto ErrHndlr
			end
			/****** Cannot delete Chr in use in InvHd table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from InvHd where InCoCd= vPCoCd and InTc= vPMCd and InChr= vPSCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Chr In Use In Invoice Head Table'
				goto ErrHndlr
			end

			/****** Cannot delete Chr in use in MultiPrcQtMst table ******/
			/* ***** Manali 3.10.0 - Multi Price Qt Module *****/
			select @row=count('x') from deleted del where 
				exists (select 'x' from MultiPrcQtMst where MqmCoCd= vPCoCd and MqmTc= vPMCd and MqmChr= vPSCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Chr In Use In Multi Price Quotation Table'
				goto ErrHndlr
			end
		End


/******************************************************************************************/
		if @vPTyp= 'FGSUBLOC' 
		Begin 
			/****** Cannot delete FgSubLoc in use in Head table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Head where HCoCd= vPCoCd and HFgSubLoc= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As FgSubLoc In Use In Head Table'
				goto ErrHndlr
			end
			/****** Cannot delete FgSubLoc in use in Bag table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Bag where BCoCd= vPCoCd and BFgSubLoc= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As FgSubLoc In Use In Bag Table'
				goto ErrHndlr
			end
			/****** Cannot delete FgSubLoc in use in Fg table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from FG where FgCoCd= vPCoCd and FgSubLoc= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As FgsubLoc In Use In FG Table'
				goto ErrHndlr
			end
			/****** Cannot delete FgSubLoc in use in Fgd table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Fgd where FdCoCd= vPCoCd and FdSubLoc= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As FgsubLoc In Use In Fgd Table'
				goto ErrHndlr
			end

			/****** Cannot delete FgSubLoc in use in Fmd table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Fmd where FmdCoCd= vPCoCd and FmdFrFgSubLoc= vPMCd
					or FmdToFgSubLoc= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As FgsubLoc In Use In Fmd Table'
				goto ErrHndlr
			end
	
		End
/*****************************************************************************************/

		if @vPTyp= 'LINE' 
		Begin 
			/****** Cannot Delete 'ZZZ' Line For The Company If Other Line Rec Exists For The Company ******/ 
			select @row= count('x') from deleted del where vPMCd= @wSelfCoCd and 
				exists (Select 'x' from vParam vPrm 
					    where vPrm.vPCoCd= del.vPCoCd 
						  and vPrm.vPTyp= del.vPTyp 
						  and vPrm.vPMCd<> @wSelfCoCd) 
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete ''ZZZ'' Line For The Company If Other Line Rec Exists For The Company' 
				goto ErrHndlr
			end

			/****** Cannot delete Line in use in Head table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Head where HCoCd= vPCoCd and HLine= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As Line In Use In Head Table'
				goto ErrHndlr
			end
			/****** Cannot delete Line in use in OrdMst table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdMst where OmCoCd= vPCoCd and OmLine= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As Line In Use In OrdMst Table'
				goto ErrHndlr
			end
			/****** Cannot delete Line in use in OrdDsg table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdDsg where OdCoCd= vPCoCd and OdLine= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As Line In Use In OrdDsg Table'
				goto ErrHndlr
			end
			/****** Cannot delete Line in use in OrdPln table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdPln where OpCoCd= vPCoCd and OpLine= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As Line In Use In OrdPln Table'
				goto ErrHndlr
			end
		End

		if @vPTyp= 'PRDSEQ' 
		Begin 
			/****** Cannot delete Production Sequence in use in DsgMst table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from DsgMst where DmPrdSeq= vPMCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In DsgMst Table'
				goto ErrHndlr
			end
			/****** Cannot delete Production Sequence in use in Head table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Head where HCoCd= vPCoCd and HCd= @wHCd and hDmPrdSeq= vPMCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In Head Table'
				goto ErrHndlr
			end
			/****** Cannot delete Production Sequence in use in OrdDsg table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdDsg where OdCoCd= vPCoCd and OdPrdSeq= vPMCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In OrdDsg Table'
				goto ErrHndlr
			end

			/****** Cannot delete Production Sequence in use in Param table where PTyp= 'PRDCTG' ******
			select @row=count('x') from deleted del where 
				exists (select 'x' from Param Pm where Pm.PTyp= 'PRDCTG' and Pm.PValue= del.vPMCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In Param Table Where PTyp= 'PRDCTG''
				goto ErrHndlr
			end
			*/
		End

		if @vPTyp= 'WORK' 
		Begin 
			/****** Cannot delete Worker in use in Bag table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Bag where BCoCd= vPCoCd and BWrk= vPMCd)
			if @row>0 
			Begin
			select @errmsg='Cannot Delete As Worker In Use In Bag Table'
				goto ErrHndlr
			end
			/****** Cannot delete Worker in use in Txnd table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Txnd where TdCoCd= vPCoCd and (TdWrk= vPMCd or TdByWrk= vPMCd))
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Worker In Use In Txnd Table'
				goto ErrHndlr
			end
			/****** Cannot delete Worker in use in TxndPrd table ******/
			Select @row=count('x') from deleted del where 
				exists (select 'x' from TxndPrd where TpCoCd= vPCoCd and TpByWrk= vPMCd)
			If @row>0 
			Begin
				select @errmsg='Cannot Delete As Worker In Use In TxndPrd Table'
				goto ErrHndlr
			End
			/****** Bhavna Cannot delete Worker in use in TxndRwrk table ******/
			Select @row=count('x') from deleted del where 
				exists (select 'x' from TxndRwrk where TrwCoCd= vPCoCd and TrwByWrk= vPMCd)
			If @row>0 
			Begin
				select @errmsg='Cannot Delete As Worker In Use In TxndRwrk Table'
				goto ErrHndlr
			End

		End

		if @vPTyp In ('WIWSEQ' ,'WIWLONG')
		Begin 
			/* ****** WIWSEQ/WIWLONG Cannot be deleted From ZZZ if it exists in other companies ****** */
			Select @Row=Count('x') From Deleted Del Where Del.vPCoCd=@wSelfCoCd And Del.vPTyp In ('WIWSEQ','WIWLONG') And Del.vPValue3='N' 
				And Exists (Select 'x' From vParam vWIW Where vWIW.vPCoCd<>@wSelfCoCd And Del.vPTyp=vWIW.vPTyp And Del.vPMCd=vWIW.vPMCd 
							And Del.vPValue3=vWIW.vPValue3)  			
			If @Row > 0
			Begin
				select @errmsg= 'Cannot Delete As '+ @vPTyp + ' Sequence Exists in One of the Companies'
				goto ErrHndlr
			End
		End	
		/* *** JAY 3.2.0 [AutoTree] */ 
		if @vPTyp= 'TRDEF' 
		Begin 
			select @row=count('x') from deleted del 
			if @row>0 
			Begin
			select @errmsg='Cannot Delete Record'
				goto ErrHndlr
			end
		end
		/* *** JAY 3.2.0 [AutoTree] */ 
	End

	Return

ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
end
GOGO
ALTER TRIGGER [dbo].[Fg_INUPDL] ON [dbo].[Fg] 
   FOR INSERT,UPDATE,DELETE  NOT FOR REPLICATION
AS  
BEGIN
	/* Trigger Version 3.02.0 (Speed Optimization) */  
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	Declare @wTcTyp Varchar(3)
	Declare @wEntTyp Varchar(8)
	Declare @wHCd Varchar(8)
	DECLARE @ReplAgt BIT  
	DECLARE @wCurrPrtn VarChar(1)
	
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'Fg' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	Select @wHCd= 'ZSELF'
	Select @wCurrPrtn='C'
		
	/*** Storing Tc Type In The Variable @wTcTyp ***/
	if @mode in ('A','C')
	Begin
		select @wTcTyp=max(PValue) from inserted join Param on PTyp= 'TC' and PMCd= FgTc and PSCd=''
	end
	if @mode in ('D')
	Begin
		select @wTcTyp=max(PValue) from deleted join Param on PTyp= 'TC' and PMCd= FgTc and PSCd=''
	end

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='C'
	begin
		Select @row=count('x') From Inserted Where FgPrtKey<>@wCurrPrtn
		If @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end

		Select @row=count('x') From Deleted del
					 Where Exists(Select 'x' From Inserted ins Where ins.FgIdNo=del.FgIdNo and ins.FgCoCd=del.FgCoCd and
									ins.FgTc=Del.FgTc and ins.FgYy=del.FgYy and ins.FgChr=del.FgChr and ins.FgNo=del.FgNo 
									and ins.FgPrtKey<>del.FgPrtKey) 
		If @row> 0 
		begin
			select @errmsg= 'Cannot Edit Partition Key Field'
			goto ErrHndlr
		end
	End

	if @mode='A'
	Begin
		Select @row=count('x') From Inserted Where FgPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 

	If @Mode='D' 
	Begin 
		select @row= count('x') from deleted del where del.FgPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */

	If  (@ReplAgt<>1)
	begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From inserted where FgPrtKey=@wCurrPrtn and  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ FgCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 

		/* Current Partition */
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where FgPrtKey=@wCurrPrtn and 
			Exists (select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ FgCoCd +',%')
				or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End 
	/******** Only One TcTyp records can be Inserted at a time ********/
	/* Partition Key Not Required */
	select @Row= Count(distinct(PValue)) from inserted Join param On
		PTyp= 'TC' and PMCd= FgTc and PSCd= ''
	If @Row > 1
	BEGIN
		Select @ErrMsg= 'Transactions of only One TcType can be Acted On'
	  	GoTo ErrHndlr
	END

	/******** Only One TcTyp records can be Deleted at a time *********/
	/* Partition Key Not Required */	
	select @Row= Count(distinct(PValue)) from deleted Join param on
		PTyp='TC' and PMcd= FgTc and PSCd= ''
	If @Row > 1
	BEGIN
		Select @ErrMsg='Transactions of only One TcType can be Acted On'
		GoTo ErrHndlr
	END
	
	/*** Storing Entry Type In The Variable @wEntTyp ***/
	select @wEntTyp= PValue1 from Param  where PTyp= 'TCTYP' and PMCd=@wTcTyp and PSCd=''
	
	if @mode in ('A','C')
	Begin
		/********** EntTyp Should Be 'FgBag' or 'FgRm' (Check In Param) ********/
		/* Current Partition */
		select @row=count('x') from inserted join Param p1 on
			p1.PTyp= 'TC'and p1.PMCd= FgTc and p1.PSCd= ''
			where FgPrtKey=@wCurrPrtn and IsNull((select p2.PValue1 from Param p2 where p2.PTyp='TCTYP'
						and p2.PMcd= p1.PValue and p2.PSCd= ''
		        		   ), '') not in ('FgBag', 'FgRm')
		if @row> 0
		Begin
			Select @ErrMsg='Transactions of only ''FgBag'' or ''FgRm'' Types permitted'
			GoTo ErrHndlr
		end
		
		/*****4.1.2********/	
		Select @Row=Count('x') From Inserted ins where 
			(Select hHolChkYN From Head where HCd='ZSELF' and HCoCd=FgCoCd)='Y' and
			(@Mode='A' or (@Mode='C' and  ins.FgDt<>IsNull((Select FgDt From Deleted del where 
									ins.FgPrtKey=del.FgPrtKey and ins.FgIdNo=del.FgIdNo 
									and ins.FgCoCd= del.FgCoCd and ins.FgTc= del.FgTc and ins.FgYy= del.FgYy 
										and ins.FgChr= del.FgChr and ins.FgNo= del.FgNo),ins.FgDt))) and  
							 exists(Select 'x' From DtTbl Where DtTag='HOL' and FgDt=DtDt and DtHolYN='Y')
		If @Row> 0
		begin  
			select @errmsg= 'Cannot Add Voucher On Holidays.'  
			goto ErrHndlr  
		end  
				

	


		/******  FgCoCd = HCoCd   *******/
		/* Current Partition */
		select @row= count('x') from inserted where FgPrtKey=@wCurrPrtn and not exists (select 'x' from Head where HCoCd= FgCoCd and HCd= @wHCd)
		if @row> 0
		begin
			select @errMsg= 'Company Code Not Valid'
			goto ErrHndlr
		end

		/******  FgYy  =  PMCd ('YY')  ******/
		/* Current Partition */
		select @row= count('x') from inserted where FgPrtKey=@wCurrPrtn and
			     not exists (select 'x' from Param where PTyp='YY' and PMCd= FgYy)
		if @row> 0
		begin
			select @errmsg= 'Voucher Year Not Defined'
			goto ErrHndlr
		end

		/******  FgChr  =  PSCd ('CHR', FgTc)  ******/
		/* Current Partition */
		select @row= count('x') from inserted where FgPrtKey=@wCurrPrtn and
			     not exists (select 'x' from vParam where vPCoCd= FgCoCd and
					vPTyp='CHR' and vPMCd= FgTc and vPSCd= FgChr)
		if @row> 0
		begin
			select @errmsg= 'Voucher Character Not Defined'
			goto ErrHndlr
		end

		/******  FgNo  <>  0  ******/
		/* Current Partition */
		select @row= count('x') from inserted where FgPrtKey=@wCurrPrtn and FgNo= 0
		if @row> 0
		begin
			select @errmsg= 'Voucher Number Cannot Be Zero'
			goto ErrHndlr
		end

		/****** Voucher Date Cannot Be Blank ******/
		/* Current Partition */
		select @Row= Count('x') from Inserted where FgPrtKey=@wCurrPrtn and FgDt in ('01/01/1980', '01/01/1900')
		If @Row > 0
		begin
			Select @ErrMsg= 'Date Cannot Be Blank'
			GoTo ErrHndlr
		end
	End

	if @mode in ('A','C') and @wTcTyp= 'FB'
	Begin
		/* (Bef 2.13) 
		******  FgFrRmLoc  ''  or  Valid Loc, LocTyp<> 'P'   ********
		Select @Row= Count('x') From Inserted Ins 
			Where Not Exists (Select 'x' From Loc where LocCoCd = FgCoCd and 
				LocTyp<> 'P' and LocCd = FgFrRmLoc)
				and FgFrRmLoc<> '' 
  	  	If @Row> 0 
		begin
			Select @ErrMsg= 'From Rm Loc Not Defined'
		  	GoTo ErrHndlr
		end

		******  FgToRmLoc  ''  or  Valid Loc, LocTyp<> 'P'   ********
		Select @Row=Count('x') From Inserted Ins
			Where Not Exists (Select 'x' From Loc where LocCoCd = FgCoCd and 
				LocTyp<> 'P' and LocCd = FgToRmLoc) 
				and FgToRmLoc<>'' 
  	  	If @Row>0
		begin
			Select @ErrMsg= 'To Rm Loc Not Defined'
		  	GoTo ErrHndlr
		end

		******  FgFrRmLoc  =  FgToRmLoc ********
		Select @Row=Count('x') From Inserted Ins where Ins.FgFrRmLoc = Ins.FgToRmLoc
  	  	If @Row>0
		begin
			Select @ErrMsg= 'To Rm Loc and From Rm Loc cannot be same'
		  	GoTo ErrHndlr
		end
		
		(Bef 2.13) */

		/*** (Jen 2.13) ***/
		/****** If TcTyp= 'FB' Then FgFrRmLoc Should Have LocTyp= 'W' ********/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins 
			Where Ins.FgPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd= FgCoCd 
				and LocTyp= 'W' and LocCd= FgFrRmLoc)
  	  	If @Row> 0
		begin
			Select @ErrMsg= 'From RM Loc Must Be Of Type ''W'' '
		  	GoTo ErrHndlr
		end

		/****** If TcTyp= 'FB' Then FgToRmLoc Should Have LocTyp= 'F' ********/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins 
			Where Ins.FgPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd= FgCoCd and LocTyp= 'F' 
				and LocCd= FgToRmLoc /* and (LocCd= FgFrRmLoc or LocCd= FgToRmLoc)*/)
	  	If @Row> 0
		begin
			Select @ErrMsg= 'To RM Loc Must Be Of Type ''F'' '
		  	GoTo ErrHndlr
		end
		/*** (Jen 2.13) ***/

		/******  FgFrBLoc  ''  or  Valid Loc, LocTyp= 'P'  ********/
		/**********Bhavna removed check for tc FB *********/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins
			Where Ins.FgPrtKey=@wCurrPrtn and (Not Exists (Select 'x' From Loc where LocCoCd = FgCoCd and
				LocTyp= 'P' and LocCd= FgFrBLoc)
			and FgFrBLoc<> '' and FgTc <> 'FB')
  	  	If @Row> 0
		begin
			Select @ErrMsg= 'From Bag Loc Not Defined'
		  	GoTo ErrHndlr
		end

		/******  FgToBLoc Is Hard Coded as 'PFG' (LocTyp= 'P')  ******/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins
			Where FgPrtKey=@wCurrPrtn and FgToBLoc<> 'PFG'
  	  	If @Row>0
		begin
			Select @ErrMsg= 'To Bag Loc Must Be ''PFG'' '
		  	GoTo ErrHndlr
		end

		/* (Bef 2.13)
		****** FgFrRmLoc or FgToRmLoc Should Have LocTyp= 'F'  ******
		Select @Row=Count('x') From Inserted Ins
			Where Not Exists (Select 'x' From Loc where LocCoCd = FgCoCd and
				LocTyp= 'F' and (LocCd= FgFrRmLoc or LocCd = FgToRmLoc))
  	  	If @Row>0
		begin
			Select @ErrMsg='Atleast One Default RM Loc Must Be Of Type ''F'' '
		  	GoTo ErrHndlr
		end
		(Bef 2.13) */

		/******  FgSubLoc  =  vPMCd ('FGSUBLOC')  ******/
		/* Current Partition */
		select @row= count('x') from inserted where FgPrtKEy=@wCurrPrtn and
			     not exists (select 'x' from vParam where vPCoCd= FgCoCd and
					vPTyp='FGSUBLOC' and vPMCd= FgSubLoc)
		if @row> 0
		begin
			select @errmsg= 'Finished Goods Sub Location Not Defined'
			goto ErrHndlr
		end
	End

	if @mode in ('A','C') and @wTcTyp in ('FR', 'FWR')
	Begin
		/****** FgFrRmLoc '' or Valid Loc, LocTyp<> 'P'  ********/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins
			Where FgPrtKey=@wCurrPrtn and (Not Exists (Select 'x' From Loc where LocCoCd = FgCoCd and
				LocTyp<> 'P' and LocCd= FgFrRmLoc)
				and FgFrRmLoc<> '')
  	  	If @Row> 0
		begin
			Select @ErrMsg= 'From Rm Loc Not Defined'
		  	GoTo ErrHndlr
		end

		/****** FgToRmLoc '' or Valid Loc, LocTyp<> 'P'  ********/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins
			Where FgPrtKey=@wCurrPrtn and (Not Exists (Select 'x' From Loc where LocCoCd = FgCoCd and
				LocTyp<> 'P' and LocCd = FgToRmLoc)
				and FgToRmLoc<>'')
  	  	If @Row>0
		begin
			Select @ErrMsg= 'To Rm Loc Not Defined'
		  	GoTo ErrHndlr
		end

		/****** FgFrRmLoc  =  FgToRmLoc  ********/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins where Ins.FgPrtKey=@wCurrPrtn and Ins.FgFrRmLoc = Ins.FgToRmLoc
  	  	If @Row>0
		begin
			Select @ErrMsg= 'To Rm Loc and From Rm Loc cannot be same'
		  	GoTo ErrHndlr
		end

		/****** FgFrBLoc, FgToBLoc should be Blank ********/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where FgPrtKey=@wCurrPrtn and (FgFrBLoc<> '' or FgToBLoc<> '')
  	  	If @Row>0
		begin
			Select @ErrMsg= 'From/ To Bag Loc Should Not Be Entered'
		  	GoTo ErrHndlr
		end

		/****** FgFrRmLoc or FgToRmLoc Should Have LocTyp= 'F'  ********/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins
			Where Ins.FgPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd = FgCoCd and
				LocTyp= 'F' and (LocCd= FgFrRmLoc or LocCd = FgToRmLoc))
  	  	If @Row>0
		begin
			Select @ErrMsg='Atleast One Default RM Loc Must Be Of Type ''F'' '
		  	GoTo ErrHndlr
		end

		/******  FgSubLoc  =  ''  ******/
		/* Current Partition */
		select @row= count('x') from inserted where FgPrtKey=@wCurrPrtn and FgSubLoc<> ''
		if @row> 0
		begin
			select @errmsg= 'Finished Goods Sub Location Should Be Blank'
			goto ErrHndlr
		end
	End
	if @mode in ('A','C') and @wTcTyp= 'FWB'
	Begin
		/* (Bef 2.13)
		****** FgFrRmLoc '' or Valid Loc, LocTyp <>'P'  ******
		Select @Row= Count('x') From Inserted Ins
			Where Not Exists (Select 'x' From Loc where LocCoCd = FgCoCd and
				LocTyp<> 'P' and LocCd = FgFrRmLoc)
				and FgFrRmLoc<> '' 
  	  	If @Row> 0
		begin
			Select @ErrMsg= 'From Rm Loc Not Defined'
		  	GoTo ErrHndlr
		end

		****** FgToRmLoc '' or Valid Loc, LocTyp<> 'P'  ******
		Select @Row= Count('x') From Inserted Ins
			Where Not Exists (Select 'x' From Loc where LocCoCd = FgCoCd and
				LocTyp<> 'P' and LocCd = FgToRmLoc) 
				and FgToRmLoc<> '' 
  	  	If @Row> 0
		begin
			Select @ErrMsg= 'To Rm Loc Not Defined'
		  	GoTo ErrHndlr
		end
	
		****** FgFrRmLoc  =  FgToRmLoc  ******
		Select @Row= Count('x') From Inserted Ins where Ins.FgFrRmLoc = Ins.FgToRmLoc
  	  	If @Row> 0
		begin
			Select @ErrMsg= 'To Rm Loc and From Rm Loc cannot be same'
		  	GoTo ErrHndlr
		end
		(Bef 2.13) */

		/*** (Jen 2.13) ***/
		/****** If TcTyp= 'FWB' Then FgFrRmLoc Should Have LocTyp= 'F' ********/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins 
			Where FgPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd= FgCoCd 
				and LocTyp= 'F' and LocCd= FgFrRmLoc)
  	  	If @Row> 0
		begin
			Select @ErrMsg= 'From RM Loc Must Be Of Type ''F'' '
		  	GoTo ErrHndlr
		end

		/****** If TcTyp= 'FWB' Then FgToRmLoc Should Have LocTyp= 'W' ********/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins 
			Where FgPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd= FgCoCd and LocTyp= 'W' 
				and LocCd= FgToRmLoc /* and (LocCd= FgFrRmLoc or LocCd= FgToRmLoc)*/)
	  	If @Row> 0
		begin
			Select @ErrMsg= 'To RM Loc Must Be Of Type ''W'' '
		  	GoTo ErrHndlr
		end
		/*** (Jen 2.13) ***/

		/******  FgFrBLoc Is Hard Coded as 'PFG' (LocTyp= 'P')  ******/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins
			Where FgPrtKey=@wCurrPrtn and FgFrBLoc<> 'PFG'
  	  	If @Row>0
		begin
			Select @ErrMsg= 'From Bag Loc Must Be ''PFG'' '
		  	GoTo ErrHndlr
		end
	
/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */
		/******  FgToBLoc '' or Valid Loc, LocTyp='P'  ********/
		Select @Row=Count('x') From Inserted Ins Where Ins.FgPrtKey=@wCurrPrtn and
			(Ins.FgToBLoc <> ISNULL((SELECT Del.FgToBLoc FROM Deleted Del Where Ins.FgIdNo=Del.FgIdNo and Ins.FgPrtKey=Del.FgPrtKey 
				and Ins.FgCoCd = Del.FgCoCd And Ins.FgTc = Del.FgTc AND Ins.FGYy = Del.FgYy AND Ins.FgChr = Del.FgChr AND Ins.FgNo = Del.FgNo), '')
			And Not Exists (Select 'x' From Loc where LocCoCd = FgCoCd and LocTyp= 'P' and LocCd = FgToBLoc AND LocValidYN = 'Y'))
			Or FgToBLoc = ''
			Or FgToBLoc= 'PFG'
  	  	If @Row>0
		begin
			Select @ErrMsg= 'To Bag Loc Not Defined/Invalid/ To Bag Loc Should Not Be ''PFG'' '
		  	GoTo ErrHndlr
		end
/* (Bef 2.06)
		Select @Row=Count('x') From Inserted Ins
			Where Not Exists (Select 'x' From Loc where LocCoCd = FgCoCd and
				LocTyp= 'P' and LocCd = FgToBLoc)
			or FgToBLoc= 'PFG'
  	  	If @Row>0
		begin
			Select @ErrMsg= 'To Bag Loc Not Defined/ To Bag Loc Should Not Be 'PFG''
		  	GoTo ErrHndlr
		end
*/
/*  #########################################  Manoj  #########################################  */

		/* (Bef 2.13)
		****** FgFrRmLoc or FgToRmLoc Should Have LocTyp= 'F'  ********
		Select @Row=Count('x') From Inserted Ins
			Where Not Exists (Select 'x' From Loc where LocCoCd = FgCoCd and
				LocTyp= 'F' and (LocCd= FgFrRmLoc or LocCd = FgToRmLoc))
  	  	If @Row>0
		begin
			Select @ErrMsg= 'Atleast One Default RM Loc Must Be Of Type ''F'' '
		  	GoTo ErrHndlr
		end
		(Bef 2.13) */

		/******  FgSubLoc  =  ''  ******/
		/* Current Partition */
		select @row= count('x') from inserted where FgPrtKey=@wCurrPrtn and FgSubLoc<> ''
		if @row> 0
		begin
			select @errmsg= 'Finished Goods Sub Location Should Be Blank'
			goto ErrHndlr
		end
	End

	If @Mode = 'C'
	Begin
		/*******Cannot Change Key values ********/
		/* Current Partition */
		select @Row= Count('x') from Deleted Del where Del.FgPrtKey=@wCurrPrtn and
			 Not Exists (Select 'x' from Inserted Ins where Ins.FgIdNo=Del.FgIdNo and
					Ins.FgPrtKey=Del.FgPrtKey and Ins.FgCoCd=Del.FgCoCd and Ins.FgTc=Del.FgTc and Ins.FgYy=Del.FgYy
					and Ins.FgChr= Del.FgChr and Ins.FgNo=Del.FgNo)
		If @Row> 0
		BEGIN
			Select @ErrMsg= 'Cannot Change Voucher No'
			GoTo ErrHndlr
		END

		/******* Cannot Change Date, FgFrBLoc, FgToBLoc, FgFrRmLoc, FgToRmLoc if Fgd records exist *******/
		/* Current Partition */
		select @row= count('x') from deleted del where del.FgPrtKey=@wCurrPrtn and
			 	(Not Exists (Select 'x' from Inserted Ins where Ins.FgIdNo=Del.FgIdNo 
					and Ins.FgPrtKey=Del.FgPrtKey and Ins.FgCoCd= Del.FgCoCd and Ins.FgTc= Del.FgTc and Ins.FgYy= Del.FgYy
					and Ins.FgChr= Del.FgChr and Ins.FgNo= Del.FgNo
					and Ins.FgDt= Del.FgDt and Ins.FgFrBLoc= Del.FgFrBLoc
					and Ins.FgToBLoc= Del.FgToBLoc and Ins.FgFrRmLoc= Del.FgFrRmLoc
					and Ins.FgToRmLoc= Del.FgToRmLoc and Ins.FgSubLoc= Del.FgSubLoc))
				and
				(Exists (Select 'X' from Fgd where del.FgPrtKey=FdPrtKey and del.FgIdNo=FdFgIdNo and del.FgCoCd= FdCoCd and
				del.FgTc= FdTc and del.FgYy= FdYy and del.FgChr= FdChr and del.FgNo= FdNo))
		if @row> 0
		begin
			select @errmsg= 'Cannot change Date/ Default Bag Locs/ Default Rm Locs/ Default FG SubLoc As Child Records Exist'
			goto ErrHndlr
		end
	End

	if @mode in ('D')
	Begin
		/****** Cannot Delete If Child Exists ******/
		/* Current Partition */
		select @row= count('x') from deleted, Fgd where FgPrtKey=@wCurrPrtn and FgPrtKey=FdPrtKey and FgIdNo=FdFgIdNo 
				and FgCoCd= FdCoCd and FgTc= FdTc and FgYy= FdYy and FgChr= FdChr and FgNo= FdNo
		if @row> 0
		begin
			select @errmsg='Cannot Delete As Child Records Exist'
			goto ErrHndlr
		end
	End
Return
ErrHndlr:
	Begin
		Select @ErrMsg='|'+@ErrMsg
		RaisError(@ErrMsg,16,1)
		Rollback Transaction
	End
END

GOGO

/*****************************************Ij8 Trigger***************/

ALTER TRIGGER [dbo].[RmRt_INUPDL] ON [dbo].[RmRt] 
         FOR INSERT,UPDATE,DELETE NOT FOR REPLICATION
AS
BEGIN
	/* Trigger Version 3.8.0 */
 	DECLARE @ROW INT
 	DECLARE @mode char(1)
 	DECLARE @errmsg varchar(255)
	DECLARE @SYS VARCHAR(5)
	DECLARE @ReplAgt BIT  
	DECLARE @wSelfCd VARCHAR(8)
	DECLARE @wCurrPrtn VARCHAR(1)

 	IF @@ROWCOUNT=0
	  	RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'RmRt')
		RETURN

	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '') 

	select @mode=case (select count('x') from inserted) when 0 then 'D'
       		           else
   			  case (select count('x') from deleted) when 0 then 'A' else 'C' end
       		           end

	set @wSelfCd = 'ZSELF'	
	Set @wCurrPrtn = 'C'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode ='A' and @ReplAgt<>1
	begin
		Select @row=count('x') From Inserted Where RrPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Records of Previous Partition'
			goto ErrHndlr
		end
	End

	if @mode ='C' and @ReplAgt<>1
	begin
		Select @row=count('x') From Inserted Where RrPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	end 

	if @mode ='D' and @ReplAgt<>1
	begin
		Select @row=count('x') From Deleted Where RrPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records of Previous Partition'
			goto ErrHndlr
		end
	end 

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */

	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

 	/******** Records Of Only One Typ Can Be Inserted At A Time ********/
	select @Row= Count(distinct(RrTcTyp)) from inserted
	If @Row > 1
	Begin
		Select @ErrMsg= 'Records Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/******** Records Of Only One Typ Can Be Deleted At A Time ********/
	select @Row= Count(distinct(RrTcTyp)) from deleted
	If @Row > 1
	Begin
		Select @ErrMsg= 'Records Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/******** RM Rate TcType Not Defined ********/
	select @row= count('x') from inserted where
  		not exists (select 'x' from Param where PTyp= 'RRTCTYP' and PMCd= RrTcTyp)
