	/* ****** Sachin 3.3.0 (24-06-08) - [14. Cost Markup in Invoicing] ****** */
 	select @row= count('x') from inserted where RrTcTyp Not In ('INL', 'MUP', 'FRT', 'IML','WXT','WCT') and
