	/* Manali 3.03 - 17/06/08 - 'LML' added */
	select @row= count('x') from inserted where RrCmCtg= 'T' 
		and RrTcTyp not in('LMG', 'LMP', 'LMS', 'LML', 'LS')
 	if @row> 0
