     Else (convert (decimal (16, 2), (case InTotAs when 'FOB' then InFOBRs +InDscRs    
               when 'CIF' then InFOBRs+ InCommRs+ InFrtRs+ InInsRs +InDscRs     
               when 'C&F' then InFOBRs+ InCommRs+ InFrtRs +InDscRs    
