    if @row> 0     
    begin    
     select @errmsg= 'Show BOE Details In Value Addition Annexur Report? Enter Yes Or No (Y/N)?'    
     goto ErrHndlr    
    end    
  End    
  /*** Shilpa Emr 2.04***/    
    
  /*** (Jen 2.13) ***/    
  /* Current Partition */    
   If @mode='A' or (@mode='C' and (Update(InShowGldLs)))    
   Begin    
    select @row= count('x') from inserted where InPrtKey=@wCurrPrtn and    
     Not Exists (select 'x' from Param where PTyp= 'YN' and PMCd= InShowGldLs)     
    if @row> 0     
    begin    
     select @errmsg= 'Show Gold Loss % In Invoice Reports? Enter Yes Or No (Y/N)?'    
     goto ErrHndlr    
    end    
  End    
  /*** (Jen 2.13) ***/    
    
  /* *** Jay 2.14(LclInv) *** */    
  /* Current Partition */    
   If @mode='A' or (@mode='C' and (Update(InLclInvYn)))    
   Begin    
    select @row= count('x') from inserted where InPrtKey=@wCurrPrtn and    
     Not Exists (select 'x' from Param where PTyp= 'YN' and PMCd= InLclInvYn)     
    if @row> 0     
    begin    
     select @errmsg= 'Invalid Local Invoice (Y/N)?'    
     goto ErrHndlr    
    end    
        
  /* Current Partition */    
    Select @row= count('x') from inserted ins where ins.InLclInvYn = 'Y' and ins.InPrtKey=@wCurrPRtn and    
      Not Exists (Select 'x' from Head where HCocd = ins.InCoCd and HLclInvYn= 'Y')    
    if @row> 0     
    begin    
     select @errmsg= 'Local Invoice Module Is Not Available'    
     goto ErrHndlr    
    End      
    End    
        
  /* Current Partition */    
   If @mode='A' or (@mode='C' and (Update(InHVatPer) or Update(InHCstPer) or Update(InLclInvYn)))    
   Begin    
    Select @row= count('x') from inserted where InPrtKey=@wCurrPrtn and InHVatPer <> 0 and InHCstPer <> 0 and InLclInvYn = 'Y'     
    if @row> 0     
    begin    
     select @errmsg= 'VAT and CST, Both Percentage Can Not Be Aplicable'    
     goto ErrHndlr    
    end    
  End      
        
  /* Current Partition */    
   If @mode='A' or (@mode='C' and (Update(InLclVatRs) or Update(InLclCstRs) or Update(InLclInvYn)))    
   Begin    
    Select @row= count('x') from inserted where InPrtKey=@wCurrPrtn and InLclVatRs <> 0 and InLclCstRs <> 0 and InLclInvYn = 'Y'     
    if @row> 0     
    begin    
     select @errmsg= 'VAT and CST, Both Values Can Not Be Aplicable'    
     goto ErrHndlr    
    end    
  End    
  /* *** Jay 2.14(LclInv) *** */    
    
  /* ***** Manali 3.6.0 - 30/10/09 - Use Notional Rate in Custom Matching ****** */    
   If @mode='A' or (@mode='C' and (Update(InNotionRtYn)))    
   Begin    
    select @row= count('x') from inserted where InPrtKey=@wCurrPrtn and    
     Not Exists (select 'x' from Param where PTyp= 'YN' and PMCd= InNotionRtYn)     
    if @row> 0     
    begin    
     select @errmsg= 'Use Notional Rate in Custom Matching (Y/N)?'    
     goto ErrHndlr    
    end    
    
/*    select @row= count('x') from inserted where InPrtKey=@wCurrPrtn and    
     InNotionRtYn='Y' and not Exists (select 'x' from Head where HCoCd= InCoCd and HCd= @wHCd and HExpLocal='Y')     
    if @row> 0     
    begin    
     select @errmsg= 'Use Notional Rate Option Cannot Be ''Y''es When DTA is No'    
     goto ErrHndlr    
    end */    
  End      
  /* ***** Manali 3.6.0 - 30/10/09 - Use Notional Rate in Custom Matching ****** */    
      
  /* ***** Sachin 3.11.0 - Use Markup for Gold on Stock Rate ****** */    
   If @mode='A' or (@mode='C' and (Update(InMetIRtwrtStkYN)))    
   Begin    
    Select @row= count('x') from inserted where InPrtKey=@wCurrPrtn and    
     Not Exists (select 'x' from Param where PTyp= 'YN' and PMCd=InMetIRtwrtStkYN)     
    if @row> 0     
    begin    
     select @errmsg= 'Use Metal Invoice Rate wrt Stock Rate should be (Y/N)?'    
     goto ErrHndlr    
    end    
    
      /* ***** Sachin 3.11.0 - Invoice RM Rate from Rate Chart ****** */    
    Select @row= count('x') from inserted where InPrtKey=@wCurrPrtn and    
     Not Exists (select 'x' from Param where PTyp= 'YN' and PMCd=InRmRtfrRtChrt)     
    if @row> 0     
    begin    
     select @errmsg= 'Use Invoice RM Rate from Rate Chart should be (Y/N)?'    
     goto ErrHndlr    
    end    
    
      /* ***** Sachin 3.11.0 - Invoice Labor Rate from Rate Chart ****** */    
    Select @row= count('x') from inserted where InPrtKey=@wCurrPrtn and    
     Not Exists (select 'x' from Param where PTyp= 'YN' and PMCd=InLabRtfrRtChrt)     
    if @row> 0     
    begin    
     select @errmsg= 'Use Invoice Labor Rate from Rate Chart should be (Y/N)?'    
     goto ErrHndlr    
    end    
          
    Select @row= count('x') from inserted where InPrtKey=@wCurrPrtn and    
     Not Exists (select 'x' from Param where PTyp= 'YN' and PMCd=InXIRtwrtStkYN)     
    if @row> 0     
    begin    
     select @errmsg= 'Use Accessories Invoice Rate wrt Stock Rate should be (Y/N)?'    
     goto ErrHndlr    
    end    
    
    Select @row= count('x') from inserted where InPrtKey=@wCurrPrtn and    
     Not Exists (select 'x' from Param where PTyp= 'YN' and PMCd=InIRtwrtStkYN)     
    if @row> 0     
    begin    
     select @errmsg= 'Use Diamond & Color Stones Invoice Rate wrt Stock Rate should be (Y/N)?'    
     goto ErrHndlr    
    end    
  End      
  /* ***** Sachin 3.11.0 - Use Markup for Gold on Stock Rate ****** */    
 End    
    
 -- 4.3.0.0    
 If @wTcTyp ='IN' And @mode = 'C' and Update(InDt)    
 Begin     
  Update InvRm Set IrDt=InDt From Inserted Where InCoCd=IrCoCd And InTc=IrTc And InYy=IrYy And InChr=IrChr And     
     InNo=IrNo And InDt<>IrDt    

  Update InvFgd Set ModUsr='MIC' From Inserted where Inserted.InCoCd=IfCoCd And Inserted.InTc=IfTc And Inserted.InYy=IfYy And Inserted.InChr=IfChr And     
     Inserted.InNo=IfNo and Inserted.InDt <> (select InDt from Deleted where Deleted.InCoCd = inserted.InCoCd and Deleted.InYy = Deleted.InYy and
											Deleted.InTc = Inserted.InTc and Deleted.InNo = Inserted.InNo)

 End     
    
 if @mode = 'D'     
 Begin    
  /****** Cannot Delete If Record Exists In InvDsg Table ******/    
  /*** Jay 3.3(FG) ***/      
  /* Current Partition */    
  select @row= count('x') from deleted, InvDsg where @wTcTyp= 'IN' and InPrtKey=@wCurrPrtn and InIdNo=IdInIdNo and InPrtKey=IdPRtKey and InCoCd= IdCoCd and InTc= IdTc     
   and InYy= IdYy and InChr= IdChr and InNo= IdNo     
  if @row> 0     
  begin    
   select @errmsg= 'Cannot Delete Invoice As Invoice Design Record Exists'    
   goto ErrHndlr    
  end    
      
  /****** Cannot Delete If Record Exists In OrdMst Table ******/    
  /*** Jay 3.3(FG) ***/      
  /* Current Partition */    
  select @row= count('x') from deleted, OrdMst where @wTcTyp= 'FG' and InPrtKey=@wCurrPrtn and InPrtKey=OmPRtKey and InCoCd= OmCoCd and InTc= OmTc     
   and InYy= OmYy and InChr= OmChr and InNo= OmNo     
  if @row> 0     
  begin    
   select @errmsg= 'Cannot Delete Invoice As Fg Out Transaction Record Exists'    
   goto ErrHndlr    
  end    
    
  /***** Manali Trading Module *****/    
  select @row= count('x') from deleted, OrdMst where @wTcTyp= 'JT' and InPrtKey=@wCurrPrtn and InPrtKey=OmPRtKey and InCoCd= OmCoCd and InTc= OmTc     
   and InYy= OmYy and InChr= OmChr and InNo= OmNo     
  if @row> 0     
  begin    
   select @errmsg= 'Cannot Delete Invoice As Master Record Exists'    
   goto ErrHndlr    
  end    
    
  /****** Cannot Delete If Record Exists In InvFgd Table ******/    
  /* Current Partition */    
  select @row= count('x') from deleted, InvFgd where InPrtKey=@wCurrPrtn and InIdNo=IfInIdNo and InPrtKey=IfPrtKey and InCoCd= IfCoCd and InTc= IfTc     
   and InYy= IfYy and InChr= IfChr and InNo= IfNo     
  if @row> 0     
  begin    
   select @errmsg= 'Cannot Delete Invoice As Invoice Bag Record Exists'    
   goto ErrHndlr    
  end    
 End    
    
 return    
ErrHndlr:    
 begin    
  select @errmsg='|'+@errmsg   raiserror(@errmsg,16,1)    
  rollback transaction     
 end    
end    
    
/*******************************************************************************************************************/
/******************************************************  UD1 *******************************************************/
GOGO

ALTER Trigger [dbo].[Grade_INUPDL] ON [dbo].[Grade] 
	    For Insert,Update,Delete NOT FOR REPLICATION
As 
Begin 
	DECLARE @ROW INT 
	DECLARE @mode char(1) 
	DECLARE @errmsg varchar(255) 
	DECLARE @SYS VARCHAR(5)
	DECLARE @ReplAgt BIT  
 
	IF @@ROWCOUNT=0 RETURN 
 
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'Grade' ) 
		Return 
 
	select @mode=case (select count('x') from inserted) when 0 then 'D' 
	else 
		case (select count('x') from deleted) when 0 then 'A' else 'C' end 
	end 
 
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If (@ReplAgt<>1)
	Begin
		if @mode in ('A','C','D')
		Begin 
			if exists (Select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	

 	if @mode = 'C'
 	Begin
		select @Row= Count('x') from deleted del where 
			not exists (Select 'x' from inserted ins where ins.GrTyp= del.GrTyp 
					and ins.GrCmCd= del.GrCmCd and 
				    ins.GrRmCtg= del.GrRmCtg and ins.GrCd= del.GrCd and ins.GrRmId= del.GrRmId)
		If @Row > 0
		begin 
			Select @ErrMsg= 'Cannot Change GradeTyp/CmCd/RmCtg/GrCd/RmId'
			GoTo ErrHndlr
		end
	End

 	if @mode in ('A','C') 
	Begin 
		select @row= count('x') from inserted where 
			not exists (select 'x' from Param  where PTyp='GRDTYP' and PMCd= GrTyp)
		if @row> 0 
		begin
			select @errmsg= 'Grade Type Not Defined'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where GrTyp= 'FIN' and 
			(GrRmCtg<>'' or GrRmId<> '' or GrRmCd<> '')
		if @row> 0 
		begin
			select @errmsg= 'RmCtg, RmId, RmCd Should Be Blank For Grade Type = ''FIN'''
			goto ErrHndlr
		end

		select @row= count('x') from inserted where 
			not exists (select 'x' from CustMst where CmCtg='C' and CmCd= GrCmCd)
		if @row> 0 
		begin
			select @errmsg= 'Customer Code  Not Defined/Invalid'
			goto ErrHndlr
		end
	
		select @row= count('x') from inserted where GrTyp<>'FIN' and
			not exists (select 'x' from Param where PTyp= 'GRDRMCTG' and PMCd=GrTyp and PSCd=GrRmCtg )
		if @row> 0 
		begin
			select @errmsg= 'Grade RmCtg Not Defined'
			goto ErrHndlr
		end
	
		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
					PTyp= 'GRDCD' and PMCd= GrTyp and PSCd= GrCd)
		if @row> 0 
		begin
			select @errmsg= 'Grade Code Not Defined'
			goto ErrHndlr
		end
	
		select @row= count('x') from inserted where GrTyp<>'FIN' and
			not exists (select 'x' from Param where 
					PTyp= 'RMID' and PMCd= GrRmCtg and PSCd= GrRmId)
		if @row> 0 
		begin
			select @errmsg= 'RmId Not Defined'
			goto ErrHndlr
		end
	
		select @row= count('x') from inserted where GrTyp<>'FIN' and
		not exists (select 'x' From RmMst where ((GrTyp='MET' and GrRmCtg in ('G','P','S','L','X')) Or
							  RmCtg=GrRmCtg) and GrRmCd=RmCd)
		if @row> 0 
		begin
			select @errmsg= 'RmCd Not Valid for this GrTyp'
			goto ErrHndlr
		end	
	
		/**********************Bhavna******/
	/******  The Size Range should be unique  (i.e. it shouldn't overlap other size 
		ranges for the same key  ******/
    	select @row= count('x') from inserted ins where 
  		(Select count('x') from Grade Gr where ins.GrTyp= Gr.GrTyp 
					and ins.GrCmCd= Gr.GrCmCd and 
				    ins.GrRmCtg= Gr.GrRmCtg and ins.GrCd= Gr.GrCd and 
				    ins.GrRmId= Gr.GrRmId and 
				    (ins.GrRmCtg = 'D' OR ins.GrRmCtg = 'C') and 
   		  (    (Gr.GrFrLn<= ins.GrFrLn and
      			 Gr.GrToLn>= ins.GrFrLn)
		    or  	(Gr.GrFrLn<= ins.GrToLn and
		      	 Gr.GrToLn>= ins.GrToLn)
    		    or  	(ins.GrFrLn<= Gr.GrFrLn and
			 ins.GrToLn>= Gr.GrToLn)
		 )
  		) > 1   
	if @row> 0
 	begin
  		select @errmsg= 'Size Range Already Defined'
  		goto ErrHndlr
 	end 
		/**********************Bhavna******/
		
		select @row= count('x') from inserted where GrTyp='FIN' and
		(GrRmCtg<>'' Or GrRmId<>'')
		if @row> 0 
		begin
			select @errmsg= 'RmCtg And RmId Should Be Blank For  Grade Type =''FIN'' '
			goto ErrHndlr
		end	
	END
return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
END


/*************** IJ.12 ***********************************************************************************************************/

GOGO
alter TRIGGER DsgMst_INUPDL ON dbo.DsgMst 
    With Encryption  FOR INSERT,UPDATE,DELETE  NOT FOR REPLICATION
AS  
BEGIN  
	/* Trigger Version 3.10.0 */
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	DECLARE @wSelfCoCd varchar(3)
	DECLARE @ctSelfCmCd varchar(8)	
	DECLARE @SYS VARCHAR(5)
	DECLARE @ReplAgt BIT  
	DECLARE @wCurrPrtn VarChar(1)

	set @wSelfCoCd= 'ZZZ'
	set @ctSelfCmCd= 'ZSELF'
	set @wCurrPrtn = 'C'

	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '') 

	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'DsgMst' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
	case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   
	
	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='A' And @ReplAgt <> 1
	begin
		Select @row=count('x') From Inserted Where DmPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */

	if @mode='C' And @ReplAgt <> 1
	begin
		Select @row=count('x') From Inserted Where DmPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	end

	if @mode='D' And @ReplAgt <> 1
	begin
		/******* Sachin 3.02.0 [30/11/07] - Purge Partition */
		select @row= count('x') from deleted del where del.DmPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	end

	If  (@ReplAgt<>1)
	begin
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
			If   exists (select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
			exists (select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
				Begin 
					select @errmsg= 'Cannot Insert /Update /Delete ' 
					goto ErrHndlr 
				end 
		End 				
		If @Mode='D' 
		Begin 
			/* *** jay 2.13(CT) *** (DsgCT) */  
			/*****Geeta***2.10**DsgPrt*DsgTgt*/
			/****** Delete all records of the child tables DsgRm, DsgLab, DsgAna ******/
			/* 3.02 Deletions On Current Db As all tables for the current design will be on current partition only  */
			Delete DsgRm From deleted, DsgRm where DmPrtKey=DrPrtKey and DmIdNo=DrDmIdNo and DmTcTyp= DrTcTyp 
				and DmCd= DrCd and DmSz= DrSz 
			Delete DsgLab From deleted, DsgLab where DmPrtKey=DlPrtKey and DmIdNo=DlDmIdNo and DmTcTyp= DlTcTyp 
				and DmCd= DlCd and DmSz= DlSz 
			Delete DsgAna From deleted join DsgAna on DmPrtKey=DaPrtKey and DmIdNo=DaDmIdNo and DmTcTyp= DaTcTyp 
				and DmCd= DaCd and DmSz= DaSz 
			Delete DsgTgt From deleted, DsgTgt where DmTcTyp= DtTcTyp 
				and DmCd= DtCd and DmSz= DtSz 
			Delete DsgModAvl From deleted, DsgModAvl where DmTcTyp= DmaTcTyp 
				and DmCd= DmaCd and DmSz= DmaSz 		
			Delete DsgCT From deleted, DsgCT where DmPrtKey=DctPrtKey and DmIdNo=DctDmIdNo and DmTcTyp= DctTcTyp 
				and DmCd= DctDmCd and DmSz= DctDmSz 
			/*** Jay 3.4(FG) ***/
			Delete DsgPrm From deleted, DsgPrm where DpDmCd= DmCd
			/*** Jay 3.4(FG) ***/
		End
	End  

 	/******** Key Cannot Be Changed ********/ 
 	if @mode = 'C'
 	Begin
		/* ****** Sachin 3.02 - Current Partition */
  		select @Row=Count('x') from deleted del where DmPrtKey=@wCurrPrtn and
    		not exists (Select 'x' from inserted ins where ins.DmIdNo=del.DmIdNo and ins.DmTcTyp= del.DmTcTyp and ins.DmCd= del.DmCd 
							and ins.DmSz= del.DmSz)
  		If @Row > 0
	  	begin 
			Select @ErrMsg = 'Cannot Change DsgMst Key'
			GoTo ErrHndlr
		end
	End

	if @mode in ('A','C')
	begin
		/******  DmTcTyp  =  PMCd ('DMTCTYP')  ******/
		/* ****** Sachin 3.02 - Partition Key Not required */
		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
				PTyp= 'DMTCTYP' and PMCd= DmTcTyp)
		if @row> 0 
		Begin
			select @errmsg= 'Design Type Not Defined'
			goto ErrHndlr
		end

		/* ****** Sachin 3.02 - Partition Key Not required */
		/******  DmCd  =  Not Blank ******/
		select @row=count('x') from inserted where DmCd= '' 
		if @row>0 
		Begin
			select @errmsg='Design Code Cannot Be Blank'
			goto ErrHndlr
		end

/*
		******  DmHistory, DmFaults  =  Not Blank ******
		select @row=count('x') from inserted where DmHistory= '' or DmFaults= '' 
		if @row>0 
		Begin
			select @errmsg= 'Design History/ Faults Cannot Be Blank'
			goto ErrHndlr
		end
*/

/*		Manoj 2.10.0		*/
		/******  If DmTcTyp  = 'DM' or 'SM'   then  DmSz = Blank or PMCd ('DMSZ')  ******/
/*		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') 
			and DmSz<> '' and not exists (select 'x' from Param where 
			PTyp= 'DMSZ' and PMCd= DmSz)
		if @row> 0 
		Begin
			select @errmsg= 'Design Size Not Defined'
			goto ErrHndlr
		end
*/
		/* ****** Sachin 3.02 - Partition Key Not required */
		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') 
			and DmSz<> '' and not exists (select 'x' from Param where 
			PTyp= 'DMSZ' and PMCd= DmSz And PValidYn = 'Y')
		if @row> 0 
		Begin
			select @errmsg= 'Design Size Not Defined / Invalid.'
			goto ErrHndlr
		end
/*		Manoj 2.10.0		*/


		/***************Geeta*******2.10***********/
		/* *** Jay 2.13(CT) *** */ 

		/******  If DmTcTyp  = 'PM'  then  DmSz <> Blank  ******/
/*		select @row= count('x') from inserted where DmTcTyp= 'PM' and DmSz= '' 
		if @row> 0 
		Begin
			select @errmsg= 'Design Component Code Cannot Be Blank'
			goto ErrHndlr
		end
*/
		/******  If DmTcTyp  = 'PM'  then  DmSz = Not Blank  ******/
/*		select @row= count('x') from inserted where DmTcTyp= 'PM' and DmSz<> '' and 
			not exists (select 'x' from Param where PTyp= 'BCHR' and PMCd= DmSz And PValue= 'C')
		if @row> 0 
		Begin
			select @errmsg= 'Design Component Code Not Defined / Invalid.'
			goto ErrHndlr
		end
*/		/* *** Jay 2.13(CT) *** */ 


		/***Geeta*2.10****/
		/******  If DmSz = Not Blank then record with Blank Size should exist in DsgMst for the same DmTcTyp ('DM' in case of 'PM') and DmCd  ******/
		/* Sachin 3.02 - 02-01-08 - Current Partition */
		select @row= count('x') from inserted ins where DmPrtKey=@wCurrPrtn and DmSz<> '' And DmTcTyp <>'PM' 
			and not exists (select 'x' from DsgMst DM where 
					DM.DmTcTyp= (case when ins.DmTcTyp = 'DM' then 'DM'  
									  when ins.DmTcTyp = 'SM' then 'SM' else '' end) 
					and DM.DMCd= ins.DmCd and DM.DmSz= '' and Dm.DmPrtKey=ins.DmPrtKey)
		if @row> 0 
		Begin
			select @errmsg= 'Design Code With Size Blank Does Not Exist'
			goto ErrHndlr
		end
/*
	select @row= count('x') from inserted ins where DmSz<> '' and  not exists (select 'x' from DsgMst DM where 
			DM.DmTcTyp= (case when ins.DmTcTyp in ('DM','PM') then 'DM'  
			when ins.DmTcTyp = 'SM' then 'SM' else '' end) 
			and DM.DMCd= ins.DmCd and DM.DmSz= '')
		if @row> 0 
		Begin
			select @errmsg= 'Design Code With Size Blank Does Not Exist'
			goto ErrHndlr
		end
*/

/*		Manoj 2.10.0		*/
		/******  DmCtg  =  PMCd ('DMCTG')  (Blank allowed in case of 'PM')  ******/
/*		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
			PTyp= 'DMCTG' and PMCd= DmCtg) and DmCtg<> ''
		if @row> 0 
		Begin
			select @errmsg= 'Design Category Not Defined'
			goto ErrHndlr
		end
*/
		/* ***** Partition Key added ***** */
		select @row= count('x') from inserted Ins where Ins.DmCtg<> '' And
			Ins.DmCtg <> IsNull((Select Del.DmCtg From Deleted Del Where Ins.DmPrtKey=Del.DmPrtKey 
				and Ins.DmIdNo=Del.DmIdNo and Ins.DmTcTyp = Del.DmTcTyp And Ins.DmCd = Del.DmCd 
				And Ins.DmSz = Del.DmSz), '') And not exists (select 'x' from Param where PTyp= 'DMCTG' and PMCd= Ins.DmCtg And PValidYn = 'Y') 
		if @row> 0 
		Begin
			select @errmsg= 'Design Category Not Defined / Invalid.'
			goto ErrHndlr
		end
/*		Manoj 2.10.0		*/

		/* Sachin 3.02 - 02-01-08 - Current Partition */
		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') and DmCtg= '' and DmPrtKey=@wCurrPrtn
		if @row> 0 
		Begin
			select @errmsg= 'Design Category Should Be Entered'
			goto ErrHndlr
		end

/*		Manoj 2.10.0		*/
		/******  DmPrdCtg  =  PMCd ('PRDCTG')  (Blank allowed in case of 'PM')  ******/
/*		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
			PTyp= 'PRDCTG' and PMCd= DmPrdCtg) and DmPrdCtg<> ''
		if @row> 0 
		Begin
			select @errmsg= 'Design Production Category Not Defined'
			goto ErrHndlr
		end
*/
		/* ***** Partition Key/IdNo added */
		Select @row= count('x') from inserted Ins where Ins.DmPrdCtg <> '' And 
			Ins.DmPrdCtg <> IsNull((Select Del.DmPrdCtg From Deleted Del Where 
				Ins.DmIdNo=Del.DmIdNo and Ins.DmTcTyp = Del.DmTcTyp 
				And Ins.DmCd = Del.DmCd And Ins.DmSz = Del.DmSz), '') And 
			not exists (select 'x' from Param where PTyp= 'PRDCTG' and PMCd= Ins.DmPrdCtg And PValidYn = 'Y')
		If @row> 0 
		Begin
			select @errmsg= 'Design Production Category Not Defined / Invalid.'
			goto ErrHndlr
		end
/*		Manoj 2.10.0		*/

		/* Sachin 3.02 - 02-01-08 - Current Partition */
		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') and DmPrdCtg= '' and DmPrtKey=@wCurrPrtn
		if @row> 0 
		Begin
			select @errmsg= 'Design Production Category Should Be Entered'
			goto ErrHndlr
		end

/*		Manoj 2.10.0		*/
		/******  DmSalCtg  =  PMCd ('SALCTG')  (Blank allowed in case of 'PM')  ******/
/*		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
			PTyp= 'SALCTG' and PMCd= DmSalCtg) and DmSalCtg<> ''
		if @row> 0 
		Begin
			select @errmsg= 'Design Sales Category Not Defined'
			goto ErrHndlr
		end
*/

		/*********Geeta*****Crm***2.12************/
		select @row= count('x') from inserted Ins where Ins.DmSalCtg<> '' And
			Ins.DmSalCtg <> IsNull((Select Del.DmSalCtg From Deleted Del Where 
				Ins.DmIdNo=Del.DmIdNo and Ins.DmTcTyp = Del.DmTcTyp 
				And Ins.DmCd = Del.DmCd And Ins.DmSz = Del.DmSz), '') And 
			not exists (select 'x' from Param where PTyp= 'SALCTG'  and PMCd=DmCtg and PSCd= DmSalCtg And PValidYn = 'Y') 
		if @row> 0 
		Begin
			select @errmsg= 'Design Sales Category Not Defined / Invalid.'
			goto ErrHndlr
		end

		select @row= count('x') from inserted Ins where 
			not exists (select 'x' from Param where PTyp= 'SALCTG' and PMCd=DmCtg and PSCd= DmSalCtg) 
		if @row> 0 
		Begin
			select @errmsg= 'Design Sales Category Not Defined.'
			goto ErrHndlr
		end
	
		/*********Geeta*****Crm***2.12************/
/*		Manoj 2.10.0		*/

		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') and DmSalCtg= ''
		if @row> 0 
		Begin
			select @errmsg= 'Design Sales Category Should Be Entered'
			goto ErrHndlr
		end

		/******  DmBagPcs  > 0  (<= Zero allowed in case of 'PM')  ******/
		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') and DmBagPcs<= 0
		if @row> 0 
		Begin
			select @errmsg= 'Bag Opening Pieces Cannot Be Zero'
			goto ErrHndlr
		end

		/**** Jay 3.1.0_1 *** */
		Select @row= count('x') from inserted Ins 
			where not exists (select 'x' from Param where PTyp= 'SETCD' and PMCd= Ins.DmSetCd)
				and exists(select 'x' from Head where HCoCd= 'ZZZ' and HValidDsgSetCd= 'Y')
		If @row> 0 
		Begin
			select @errmsg= 'Design Set Code Not Defined/Can Not Be Blank.'
			goto ErrHndlr
		end
		/**** Jay 3.1.0_1 *** */

		/******  DmCmCd  =  Blank  or  valid  CmCd  from CustMst (CmCtg = 'C')  ******/
		select @row= count('x') from inserted where DmCmCd<> '' 
			and not exists (select 'x' from CustMst where 
			CmCtg= 'C' and (',' + DmCmCd + ',') Like ('%,' + CmCd + ',%'))			
		if @row> 0 
		Begin
			select @errmsg= 'One of the Customer Code Not Defined'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where DmPrfVendCd<> '' 
			and not exists (select 'x' from CustMst where 
			CmCtg= 'S' and CmCd =DmPrfVendCd) 		
		if @row> 0 
		Begin
			select @errmsg= 'Preferred Vendor Code Invalid'
			goto ErrHndlr
		end
		/******  DmHld  =  PMCd ('YN')  ******/
		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
			PTyp= 'YN' and PMCd= DmHld)
		if @row> 0 
		Begin
			select @errmsg= 'Enter Design On Hold as ''Y'' or ''N'' '
			goto ErrHndlr
		end

		/******  DmParts  >  0  ******/
		select @row= count('x') from inserted where DmParts<= 0
		if @row> 0 
		Begin
			select @errmsg= 'Design Parts Cannot Be Zero'
			goto ErrHndlr
		end

/*		MAnoj 2.10.0		*/
		/******  DmCol  =  PMCd ('DMCOL')  ******/
/*		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where PTyp= 'DMCOL' and PMCd= DmCol)
		if @row> 0 
		Begin
			select @errmsg= 'Design Colour Not Defined'
			goto ErrHndlr
		end
*/

		/*** (Bef 3.01)
		select @row= count('x') from inserted Ins where 
			Ins.DmCol <> IsNull((Select Del.DmCol From Deleted Del Where 
				Ins.DmTcTyp = Del.DmTcTyp And Ins.DmCd = Del.DmCd And Ins.DmSz = Del.DmSz), '') And 
			not exists (select 'x' from Param where PTyp= 'DMCOL' and PMCd= Ins.DmCol And PValidYn = 'Y')
		if @row> 0 
		Begin
			select @errmsg= 'Design Colour Not Defined / Invalid.'
			goto ErrHndlr
		end
		(Bef 3.01) ***/
/*		Manoj 2.10.0		*/

		/*** (Jen 3.01) ***/
		select @row= count('x') from inserted Ins where 
			Ins.DmCol= '' or 
			(	Ins.DmCol <> IsNull((Select Del.DmCol From Deleted Del Where Ins.DmIdNo=Del.DmIdNo and 
				Ins.DmTcTyp = Del.DmTcTyp And Ins.DmCd = Del.DmCd And Ins.DmSz = Del.DmSz), '') And 
				not exists (select 'x' from Param where PTyp= 'DMCOL' and PMCd= Ins.DmCol And PValidYn = 'Y')
			)
		if @row> 0 
		Begin
			select @errmsg= 'Design Colour Not Defined / Invalid.'
			goto ErrHndlr
		end
		/*** (Bef 3.01) ***/


		/******  DmPrdSeq  =  PMCd ('PRDSEQ')  (Blank allowed in case of 'PM')  ******/
		select @row= count('x') from inserted where DmPrdSeq<> '' and 
			not exists (select 'x' from vParam where 
				vPTyp= 'PRDSEQ' and vPMCd= DmPrdSeq) 
		if @row> 0 
		Begin
			select @errmsg= 'Production Sequence Not Defined'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') and DmPrdSeq= ''
		if @row> 0 
		Begin
			select @errmsg= 'Production Sequence Should Be Entered'
			goto ErrHndlr
		end

		/******  DmUom  =  PMCd ('DMUOM')  (Blank allowed in case of 'PM')  ******/ 
		select @row= count('x') from inserted where DmUom<> '' and 
			not exists (select 'x' from Param where 
			PTyp= 'DMUOM' and PMCd= DmUom)
		if @row> 0 
		Begin
			select @errmsg= 'Design Unit Of Measurement Not Defined'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') and DmUom= ''
		if @row> 0 
		Begin
			select @errmsg= 'Design Unit Of Measurement Should Be Entered'
			goto ErrHndlr
		end

		/******  DmVaCtg  =  PMCd ('VACTG')  (Blank allowed in case of 'PM')  ******/
		select @row= count('x') from inserted where DmVaCtg<>'' and 
			not exists (select 'x' from Param where 
			PTyp= 'VACTG' and PMCd= DmVaCtg)
		if @row> 0 
		Begin
			select @errmsg= 'Value Addition Category Not Defined'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where DmTcTyp in ('DM', 'SM') and DmVaCtg= '' 
		if @row> 0 
		Begin
			select @errmsg= 'Value Addition Category Should Be Entered'
			goto ErrHndlr
		end

		/******  DmKt  =  PMCd ('KT')  ******/
		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
			PTyp= 'KT' and PMCd= DmKt)
		if @row> 0 
		Begin
			select @errmsg='Karat Not Defined'
			goto ErrHndlr
		end

		/******  DmLsCtg  =  valid  PMCd ('LSCTG')  ******/
		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where PTyp= 'LSCTG' and PmCd= DmLsCtg)
		if @row> 0 
		Begin
			select @errmsg= 'Loss Category Not Defined'
			goto ErrHndlr
		end

		/******  DmRegnExc  =  Blank  or  valid  PMCd ('YN')  ******/
		select @row= count('x') from inserted where DmRegnExc<> '' 
			and not exists (select 'x' from Param where 
			PTyp= 'YN' and PmCd= DmRegnExc)
		if @row> 0 
		Begin
			select @errmsg= 'Region Exclusivity Not Defined'
			goto ErrHndlr
		end

		/******  DmRegnExc  =  valid  PMCd ('YN') when DmCmCd<> '' ******/
		select @row= count('x') from inserted where DmCmCd<> '' and DmRegnExc= '' 
		if @row> 0 
		Begin
			select @errmsg= 'Specify Whether The Dsg Is Region Exclusive For The Cust Or Not'
			goto ErrHndlr
		end

		/******  DmRegnExc  =  Blank when DmCmCd= '' ******/
		select @row= count('x') from inserted where DmCmCd= '' and DmRegnExc<> '' 
		if @row> 0 
		Begin
			select @errmsg= 'Region Exclusivity Not To Be Entered When Customer Is Not Specified'
			goto ErrHndlr
		end
		/******      *******/
/*		select @row= count('x') from inserted where DrQty <> DrPrdQty and DrWt <> DrPrdWt and
			(Select HShowPrdRmDets from head where HCd= @ctSelfCmCd and HCoCd = @wSelfCoCd) = 'N' 
		if @row> 0 
		Begin
			select @errmsg= 'Both the Weights and Quantities should be equal'
			goto ErrHndlr
		end
*/

/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */
		/******  DmLockYN =  valid  PMCd ('YN')  ******/
		select @row= count('x') from inserted where
			Not Exists (select 'x' from Param where PTyp= 'YN' and PmCd= DmLockYN)
		if @row> 0
		Begin
			select @errmsg= 'Design Lock (Y/N) Not Defined'
			goto ErrHndlr
		end
/*  #########################################  Manoj  #########################################  */
	end


	/****** Check For Use In OrdDsg, CustDsg, Fgd   ******/	
	/****** If In Use Do Not Allow Delete ******/
	if @mode = 'D'  And @ReplAgt <> 1
	begin
		/****** Cannot a delete a record with DmSz= '' if record with DmSz Not Blank exists for the same DmTcTyp ('DM' in case of 'PM') and DmCd ******/
/****Geeta***2.10***/
/*
		select @row= count('x') from deleted del where DmSz= '' and 
			( (del.DmTcTyp = 'DM' and exists (select 'x' from DsgMst DM where DM.DmTcTyp in ('DM','PM') 
				and DM.DMCd= del.DmCd and DM.DmSz<> ''))
			or (del.DmTcTyp = 'SM' and exists (select 'x' from DsgMst DM where DM.DmTcTyp= 'SM'  
				and DM.DMCd= del.DmCd and DM.DmSz<> ''))
			)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete Design As Record With Size Not Blank Exists'
			goto ErrHndlr
		end
*/
		/* Sachin 3.02 - 02-01-08 */
		select @row= count('x') from deleted del where DmSz= '' and 
			 del.DmTcTyp <> 'PM' and exists (select 'x' from DsgMst DM where DM.DmTcTyp =Del.DmTctyp 
				and DM.DMCd= del.DmCd and DM.DmSz<> '' and del.DmPRtKey=DM.DmPrtKey)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete Design As Record With Size Not Blank Exists'
			goto ErrHndlr
		end

		/* *** Jay 2.13(CT) *** */
		/* Sachin 3.02 - 02-01-08 */
		select @row= count('x') from deleted del where DmTcTyp = 'PM' and DmPRtKey=@wCurrPrtn
			and exists (select 'x' from DsgCt where DctCd= DmCd and DctSz=DmSz and DctPrtKey=DmPrtKey)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Component Used In DsgCt Table'
			goto ErrHndlr
		end
		/* *** Jay 2.13(CT) *** */	

		/* *** Jay 2.13(CT) *** */
		select @row= count('x') from deleted del where DmTcTyp = 'PM' 
			and exists (select 'x' from OrdCt where OctCd= DmCd and OctSz=DmSz)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Component Used In OsgCt Table'
			goto ErrHndlr
		end
		/* *** Jay 2.13(CT) *** */	

		/* Bef 2.13(CT)
		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp = 'PM' 
			and exists (select 'x' from DsgPrt where DpPrtCd= DmCd and DpPrtSz=DmSz)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Part In Use In DsgPrt Table'
			goto ErrHndlr
		end
		 Bef 2.13(CT)*/
		/***********Geeta****2.10******************/	
		/* Complete Database */
		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp = 'DM' 
			and exists (select 'x' from OrdDsg where OdDmIdNo=DmIdNo and OdDmCd= DmCd and 
					(Select PValue from Param where PTyp= 'TC' and PMCd= OdTc) in ('SO', 'QT', 'PL') )
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Design In Use In OrdDsg Table'
			goto ErrHndlr
		end

		/* Complete Database */
		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp = 'SM' 
			and exists (select 'x' from OrdDsg where OdDmIdNo=DmIdNo and OdDmCd= DmCd and 
					(Select PValue from Param where PTyp= 'TC' and PMCd= OdTc)= 'QS')
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Sketch In Use In OrdDsg Table'
			goto ErrHndlr
		end

/*		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp in('DM', 'SM') 
			and exists (select 'x' from OrdDsg where OdDmCd= DmCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Design In Use In OrdDsg Table'
			goto ErrHndlr
		end
*/
		/* Complete Database */
		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp = 'DM' 
			and exists (select 'x' from CustDsg where CdPrtKey=DmPrtKey and CdOurDmCd= DmCd)
		if @row> 0 
		Begin
			select @errmsg='Cannot Delete As Design In Use In CustDsg Table'
			goto ErrHndlr
		end

		/* Complete Database */
		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp = 'DM' 
			and exists (select 'x' from Fgd where FdDmIdNo=DmIdNo and FdDmCd= DmCd and FdBNo= 0)
		if @row> 0 
		Begin
			select @errmsg='Cannot Delete As Design In Use In Fgd Table'
			goto ErrHndlr
		end

    /***** Manali 3.9.1 - RfId Module */		
		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp = 'DM' 
			and exists (select 'x' from RfIdMst where DmCd=RimDmCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Design Is In Use In RfId Master Table'
			goto ErrHndlr
		end
		
    /***** Manali 3.10.0 - Multi Price QT Module */		
		select @row= count('x') from deleted del where DmSz= '' and DmTcTyp = 'DM' 
			and exists (select 'x' from MultiPrcQtDsg where DmCd=MqdDmCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Design Is In Use In Multi Price Quotation Master Table'
			goto ErrHndlr
		end
		
		
		/****Geeta**Crm**2.12*********Moved To Not For Replication Trigger*****/ 
		/*****Geeta***2.10**DsgPrt*DsgTgt*/
		/****** Delete all records of the child tables DsgRm, DsgLab, DsgAna ******/
/*		Delete DsgRm From deleted, DsgRm where DmTcTyp= DrTcTyp 
			and DmCd= DrCd and DmSz= DrSz 
		Delete DsgLab From deleted, DsgLab where DmTcTyp= DlTcTyp 
			and DmCd= DlCd and DmSz= DlSz 
		Delete DsgAna From deleted join DsgAna on DmTcTyp= DaTcTyp 
			and DmCd= DaCd and DmSz= DaSz 
		Delete DsgPrt From deleted, DsgPrt where DmTcTyp= DpTcTyp 
			and DmCd= DpCd and DmSz= DpSz 
		Delete DsgTgt From deleted, DsgTgt where DmTcTyp= DtTcTyp 
			and DmCd= DtCd and DmSz= DtSz 
*/
	end

	if @SYS= 'XEMR' 
	BEGIN

		/****** If In Use Do Not Allow Delete ******/
		if @mode = 'D' 
		Begin

			/****** Check For Use In xTxnDsg, xDsgYyMm   ******/	
			/****** If In Use Do Not Allow Delete ******/
			select @row= count('x') from deleted where exists
				(select 'x' from xTxnDsg where xTdDmSz= '' and xTdDmTyp= DmTcTyp
					and xTdDmCd= DmCd)	
			if @row> 0 
			Begin
				select @errmsg='Cannot Delete As Design In Use In xTxnDsg Table'
				goto ErrHndlr
			end
			
			select @row= count('x') from deleted where exists
				(select 'x' from xDsgYyMm where xDyDmSz= '' and DmTcTyp= 'DM'
					and xDyDmCd= DmCd)	
			if @row> 0 
			Begin
				select @errmsg='Cannot Delete As Design In Use In xDsgYyMm Table'
				goto ErrHndlr
			end
		End

	END


	
return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
end


/***Bug fix of Ij 57****************************************************************************************************************************/
GOGO

               
ALTER TRIGGER [dbo].[Txnd_INUPDL] ON [dbo].[Txnd]              
       FOR INSERT,UPDATE,DELETE              NOT FOR REPLICATION
AS              
BEGIN              
 /* Trigger Version 3.10.0 */              
 Declare @Row Int              
 Declare @Mode Char(1)              
 Declare @ErrMsg Varchar(255)              
 Declare @wTcTyp Char(3)               
 Declare @wTc Char(3)               
 Declare @wEntTyp Char(8)              
 Declare @wHCd Varchar(8)              
 DECLARE @ReplAgt BIT                
 DECLARE @wCurrPrtn VarChar(1)              
      
 If @@RowCount=0              
  Return              
 If Exists(Select 'x' From TrgDisa Where TdTblNm = 'Txnd' )              
  RETURN              
              
 Select @Mode=Case (Select Count('x') From Inserted)              
    When 0 Then 'D'              
   Else Case (Select Count('x') From Deleted)              
    When 0 Then 'A'              
    Else 'C'              
        End              
   End              
              
 Select @wHCd= 'ZSELF'              
 Select @wCurrPrtn='C'              
      
              
 /* **** Checking Whether a Normal Transaction or Replicated One **** */              
 Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))              
               
 /******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */              
 if @mode='C'              
 begin              
  Select @row=count('x') From Inserted Where TdPrtKey<>@wCurrPrtn              
  if @row> 0               
  begin              
   select @errmsg= 'Cannot Edit Records of Previous Partition'              
   goto ErrHndlr              
  end              
              
  Select @row=count('x') From Deleted del              
      Where Exists(Select 'x' From Inserted ins               
         Where ins.TdIdNo=del.TdIdNo and ins.TdCoCd=del.TdCoCd and ins.TdTc=del.TdTc and              
            ins.TdYy=del.TdYy and ins.TdChr=del.TdChr and ins.TdNo=del.TdNo and               
            ins.TdSr=del.TdSr and ins.TdSrNo=del.TdSrNo and ins.TdPrtKey<>del.TdPrtKey)               
  if @row> 0               
  begin              
   select @errmsg= 'Cannot Edit Partition Key Field'              
   goto ErrHndlr              
  end              
              
 End              
              
 if @mode='A'              
 Begin              
  Select @row=count('x') From Inserted Where TdPrtKey <> @wCurrPrtn               
  if @row> 0               
  begin              
   select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''              
   goto ErrHndlr              
  end              
 end               
              
 If @Mode='D'               
 Begin               
  select @row= count('x') from deleted del where del.TdPrtKey<>@wCurrPrtn              
  if @row> 0               
  begin              
   select @errmsg= 'Cannot Delete Records From Previous Partition'              
   goto ErrHndlr              
  end              
 End              
 /******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */              
      
              
 If  (@ReplAgt<>1)              
 Begin              
              
  /******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/              
  /***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/              
  if @mode in ('A','C')              
  Begin              
  /* Current Partition */              
  select @ROW =Count('x')  From inserted where TdPrtKey=@wCurrPrtn and              
  Exists ( select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ TdCoCd +',%'))              
   or (SysId='CRM' and SysDb='WEB'))              
  If @Row > 0              
   Begin              
    select @errmsg= 'Cannot Insert /Update '              
    goto ErrHndlr              
   end              
  End             
              
  If @mode in ('D')              
  Begin              
  /* Current Partition */              
  select @ROW =Count('x')  From Deleted where TdPRtKey=@wCurrPRtn and              
  Exists ( select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ TdCoCd +',%'))              
   or (SysId='CRM' and SysDb='WEB'))              
  If @Row > 0              
   Begin              
    select @errmsg= 'Cannot Delete '              
    goto ErrHndlr              
   end              
  End              
              
  If @Mode in ('A','C')              
  Begin              
              
   Select @wTcTyp= Max(PValue) From Inserted Join Param On PTyp='TC'              
     And PMcd= TdTc And PScd=''              
              
  /* Zubin 212 */              
   Select @wTc= TdTc From Inserted Join Param On PTyp='TC'              
     And PMcd= TdTc And PSCd=''              
  /* Zubin 212 */              
  End              
               
  /********** Select @wTcTyp from Deleted **********/              
  If @Mode in ('D')              
  Begin              
   Select @wTcTyp= Max(PValue) From Deleted Join Param On PTyp='TC'              
     And PMcd=TdTc And PScd=''              
  End              
               
  /********** Select @wTcEntTyp from Param ********/              
  select @wEntTyp = PValue1 from Param where PTyp='TCTYP'              
     and PMcd=@wTcTyp and PSCd=''              
                
  If @wEntTyp= 'TxnBag'              
  BEGIN               
   /****** Bag in Control of other User, Check either              
    PrevYy+Key Or TdYy+Key = LstYy+Key, for TdSrNo=0,<>0 ********/              
              
   /* Current Partition */              
   select @Row= Count('x') from inserted              
    join Bag on TdBIdNo=BIdNo and TdCoCd= BCoCd and TdBYy= BYy and TdBChr= BChr and TdBNo= BNo               
      and TdPrtKey=BPrtKey              
    where TdPrtKey=@wCurrPrtn and Not ((TdCoCd= BCoCd and TdPrevYy= BLstYy and TdPrevKey= BLstKey)              
    Or (TdCoCd= BCoCd and TdYy= BLstYy and TdKey= BLstKey))              
   If @Row > 0              
   begin              
    Select @ErrMsg= 'Bag in Control of other user'              
    GoTo ErrHndlr              
   end              
               
   /****** Cannot Add Or Change As Bag Is In Finished Goods Location ********/              
   /* Current Partition */              
   select @Row= Count('x') from inserted              
    join Bag on TdBIdNo=BIdNo and TdCoCd= BCoCd and TdBYy= BYy and TdBChr= BChr and TdBNo= BNo               
      and TdPrtKey=BPrtKey              
    where BPrtKey=@wCurrPrtn and BLoc= 'PFG'              
   If @Row > 0              
   begin              
    Select @ErrMsg= 'Cannot Add/ Change As Bag In Finished Goods Location'              
    GoTo ErrHndlr              
   end              
               
   /****** Cannot Change Or Delete As Bag Is In Finished Goods Location ********/              
   /* Current Partition */              
        select @Row= Count('x') from deleted              
    join Bag on TdBIdNo=BIdNo and TdCoCd= BCoCd and TdBYy= BYy and TdBChr= BChr and TdBNo= BNo               
     and TdPRtKey=BPrtKEy              
    where BPrtKey=@wCurrPrtn and BLoc= 'PFG'              
   If @Row > 0              
   begin              
    Select @ErrMsg= 'Cannot Change/ Delete As Bag In Finished Goods Location'              
    GoTo ErrHndlr              
   end              
               
   /****** If TcType= 'BV' then TdFrBLoc & TdToBLoc cannot be 'PFG' ********/              
   /* Current Partition */              
   select @Row= Count('x') from inserted where @wTcTyp= 'BV' and TdPRtKey=@wCurrPrtn and              
    (TdFrBLoc= 'PFG' or TdToBLoc= 'PFG')              
   If @Row > 0              
   begin              
    Select @ErrMsg= 'From/ To Bag Location Cannot Be ''PFG'' In Bag Movement'              
    GoTo ErrHndlr              
   end              
               
/**** Cannot Update or Delete if Not the last Txn of the Bag              
         Checking for TdSrNo=0, <>0 records *******/              
   /* Current Partition */              
   select @Row=Count('x') from deleted where TdPrtKey=@wCurrPrtn and              
    Not Exists (Select 'x' from Bag where TdBIdNo=BIdNo and TdCoCd= BCoCd and              
         TdByy= BYy and TdBChr= BChr and TdBNo= BNo and TdPrtKey=BPRtKey and              
         ((TdYy>= BLstYy and TdKey>= BLstKey)              
           or IsNull(BLstKey, 0)= 0))              
   If @Row > 0              
   Begin              
    Select @ErrMsg= 'Cannot Update Or Delete, Not The Last Txn Of The Bag'              
    GoTo ErrHndlr              
   end              
              
  If @Mode in ('A')              
  Begin              
   /* Sachin 3.2.2 - Bag Opn Dt should be Less than Min Transaction Date */              
   select @Row= Count('x') from inserted              
    join Bag on TdBIdNo=BIdNo and TdCoCd= BCoCd and TdBYy= BYy and TdBChr= BChr and TdBNo= BNo               
      and TdPrtKey=BPrtKey              
    where TdPrtKey=@wCurrPrtn and TdDt<BOpnDt              
   If @Row > 0              
   begin              
    Select @ErrMsg= 'Transaction Date Cannot Be Less Than Bag Opening Date'              
    GoTo ErrHndlr              
   end              
              
   /**** Sachin 3.02.0 - Bag Transaction Should be at a later than that of the earlier Max Tran Date */              
   /* Current Partition */              
   Select @Row=Count('x') from Inserted               
       Join Bag on TdPrtKey=BPrtKey and TdBIdNo=BIdNo and TdCoCd= BCoCd and              
        TdByy= BYy and TdBChr= BChr and TdBNo= BNo              
   Where Tddt<BMaxTxnDt              
   If @Row > 0              
   Begin              
    Select @ErrMsg= 'A Transaction of Later Date Exists For this Bag'              
    GoTo ErrHndlr              
   end              
   /**** Sachin 3.02.0 - Bag Transaction Should be at a later than that of the earlier Max Tran Date */              
              
  End              
   End                
 End              
 /******* If Mode = 'C' then Cannot change Key Values,              
  Cannot Change VchNo, BagNo **********/              
 If @Mode = 'C'              
 Begin              
  /* Current Partition */                
  select @Row=Count('x') from Deleted Del where TdPrtKey=@wCurrPrtn and              
    Not Exists (Select 'x' from Inserted Ins where Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd=Del.TdCoCd              
     and Ins.TdTc=Del.TdTc and Ins.Tdyy=Del.TdYy and Ins.TdChr= Del.TdChr and Ins.TdNo=Del.TdNo              
     and Ins.TdSr=Del.TdSr and Ins.TdSrNo=Del.TdSrNo and Ins.TdPrtKey=Del.TdPrtKey              
     and Ins.TdByy=Del.TdByy and Ins.TdBChr=Del.TdBChr              
     and Ins.TdBNo=Del.TdBNo and Ins.TdKey= Del.TdKey)              
  If @Row > 0              
  Begin              
   Select @ErrMsg='Cannot Change Company Code/ Voucher No./Bag No/ Key'              
   GoTo ErrHndlr              
  End              
 End              
              
 /******** Records Of Only One TcTyp can be Inserted at a time.********/              
 /* Partition KEy Not required */               
 select @Row= Count(distinct(PValue)) from inserted Join param On              
    PTyp= 'TC' and PMCd= TdTc and PScd= ''              
 If @Row > 1              
 BEGIN              
  Select @ErrMsg= 'Transactions of only One TcType can be Acted On'              
  GoTo ErrHndlr              
 END              
              
 /******** Records Of Only One TcTyp can be Deleted at a time.*********/              
 /* Partition KEy Not required */              
 select @Row= Count(distinct(PValue)) from deleted Join param on              
    PTyp='TC' and PMcd=TdTc and PSCd=''              
 If @Row > 1              
 BEGIN              
  Select @ErrMsg='Transactions of only One TcType can be Acted on'              
  GoTo ErrHndlr              
 END              
            
 /********** Select @wTcEntTyp from Param ********/              
 /* Partition Key Not required */              
 select @wEntTyp = PValue1 from Param where PTyp='TCTYP'              
    and PMcd=@wTcTyp and PSCd=''              
 If @wEntTyp <> 'TxnBag' and @wEntTyp <> 'TxnRm'              
 Begin              
  Select @ErrMsg='Transactions of only ''Txn'' Type permitted'              
  GoTo ErrHndlr              
 end              
              
 /********* field level Validation Checks ********/              
 /****************   ****************/      
              
 /******* Valid TdCoCd,TdTc,TdYy,TdChr, TdNo ********/              
 /* Current Partition */               
 Select @Row= Count('x') From Inserted Ins Where Ins.TdPrtKey=@wCurrPrtn and              
  Not Exists (Select 'x' From Txn Where Txn.TIdNo=Ins.TdTIdNo and Txn.TCoCd=Ins.TdCoCd And Txn.TTc=Ins.TdTc              
   And Txn.TYy=Ins.TdYy And  Txn.TChr=Ins.TdChr And Txn.TNo=Ins.TdNo And Txn.TPrtKey=Ins.TdPrtKey)              
   If @Row> 0              
  begin              
  Select @ErrMsg= 'Voucher No. Does Not Exist'              
  GoTo ErrHndlr              
   end              
              
 /***** TdSr <> 0 *****/              
 /* Current Partition */               
 Select @Row= Count('x') From Inserted Ins Where TdPrtKey=@wCurrPrtn and TdSr=0              
 If @Row> 0              
 Begin              
    Select @ErrMsg= 'Sr. Cannot be 0'              
    GoTo ErrHndlr              
 End              
              
 /******* TdKey <> 0 ***********/              
 /* Current Partition */              
   Select @Row= Count('x') From Inserted Ins Where TdPrtKey=@wCurrPrtn and TdKey<= 0              
 If @Row> 0              
 Begin              
  Select @ErrMsg= 'Key Cannot Be Zero'              
  GoTo ErrHndlr              
 End              
              
 /******* TdToRmDc should be Opp of  TdFrRmDc ( '' if TdFrRmDc= '' ) *******/              
 /* Current Partition */           
   Select @Row=Count('x') From Inserted Ins              
  Where Ins.TdPrtKey=@wCurrPrtn and (TdToRmDc=TdFrRmDc And TdFrRmDc<>'')  Or              
   (TdFrRmDc<>'' and TdToRmDc='')              
   If @Row>0              
 Begin              
  Select @ErrMsg='Invalid To Rm Dc'              
  GoTo ErrHndlr              
 End              
              
              
