/* Zubin 212 TdLotNo added */              
  /********TdRmQty if 'TxnBag' then  sum of RmQty should be >=0 for the given RmCd, Sz, StkRt ********/              
  /* Current Partition */           
  /***** Manali 3.8.0 Str(Td.TdRmSz, 16, 3) Chnaged To Str(Td.TdRmSz, 16, 4) For Pointer    ****/      
  Select @Row=Count('x') From Inserted Ins Where Ins.TdPrtKey=@wCurrPrtn and Ins.TdRmCd<>'' and              
   IsNull((Select sum(Td.TdRmQty* (              
        Case when Td.TdFrRmLoc= 'W' and Td.TdFrRmDc= 'D' then 1              
     when Td.TdFrRmLoc= 'W' and Td.TdFrRmDc= 'C' then -1              
     when Td.TdToRmLoc= 'W' and Td.TdToRmDc= 'D' then 1              
     when Td.TdToRmLoc= 'W' and Td.TdToRmDc= 'C' then -1              
            Else 0 end))              
     from Txnd Td where Td.TdPrtKey=Ins.TdPrtKey and Td.TdBIdNo=Ins.TdBIdNo               
     and Td.TdCoCd= Ins.TdCoCd and Td.TdBYy= Ins.TdBYy              
     and Td.TdBChr= Ins.TdBChr and Td.TdBNo= Ins.TdBNo              
     and Td.TdRmCd= Ins.TdRmCd and Td.TdLotNo= Ins.TdLotNo              
     and Str(Td.TdRmSz, 16, 4)= Str(Ins.TdRmSz, 16, 4)              
     and Str(Td.TdRmStkRt, 16, 2)= Str(Ins.TdRmStkRt, 16, 2)), 0)< 0              
    If @Row>0              
  BEGIN              
   Select @ErrMsg='Rm Qty Is Less Than Zero In Bag'              
   GoTo ErrHndlr              
  END              
              
  /* Manali 3.2.2 - not allowing negative RM Qty in bag in change mode*/              
 /***** Manali 3.8.0 Str(Td.TdRmSz, 16, 3) Chnaged To Str(Td.TdRmSz, 16, 4) For Pointer    ****/      
  If @Mode in ('C')              
  Begin              
   Select @Row= Count('x') From Deleted Del Where Del.TdPrtKey=@wCurrPrtn and Del.TdRmCd<> '' and               
    exists(Select 'x' from Inserted Ins where               
  Ins.TdPrtKey=Del.TdPRtKey and Ins.TdBIdNo=Del.TdBIdNo              
     and Ins.TdCoCd= Del.TdCoCd and Ins.TdBYy= Del.TdBYy              
     and Ins.TdBChr= Del.TdBChr and Ins.TdBNo= Del.TdBNo              
     and (Ins.TdRmCd<> Del.TdRmCd or Ins.TdLotNo<> Del.TdLotNo              
     or Str(Ins.TdRmSz, 16, 3)<> Str(Del.TdRmSz, 16, 3)              
     or Str(Ins.TdRmStkRt, 16, 2)<> Str(Del.TdRmStkRt, 16, 2))) and              
     Round(IsNull((Select sum(Td. TdRmQty* (              
     Case when Td.TdFrRmLoc= 'W' and Td.TdFrRmDc= 'D' then 1              
      when Td.TdFrRmLoc= 'W' and Td.TdFrRmDc= 'C' then -1              
      when Td.TdToRmLoc= 'W' and Td.TdToRmDc= 'D' then 1              
      when Td.TdToRmLoc= 'W' and Td.TdToRmDc= 'C' then -1              
     Else 0 end))              
    from Txnd Td where Td.TdPrtKey=Del.TdPRtKey and Td.TdBIdNo=Del.TdBIdNo              
    and Td.TdCoCd= Del.TdCoCd and Td.TdBYy= Del.TdBYy              
    and Td.TdBChr= Del.TdBChr and Td.TdBNo= Del.TdBNo              
    and Td.TdRmCd= Del.TdRmCd and Td.TdLotNo= Del.TdLotNo              
    and Str(Td.TdRmSz, 16, 4)= Str(Del.TdRmSz, 16, 4)              
    and Str(Td.TdRmStkRt, 16, 2)= Str(Del.TdRmStkRt, 16, 2)), 0), 3)< 0               
  If @Row>0              
  Begin              
   Select @ErrMsg='Rm Qty Is Less Than Zero In Bag'              
   GoTo ErrHndlr              
  End              
  End              
              
              
  if @Mode='D'              
  Begin              
/* Zubin 212 TdLotNo added */              
   /********TdRmQty if 'TxnBag' then  sum of RmQty should be >=0 for the given RmCd, Sz, StkRt ********/              
   /* Current Partition */          
 /***** Manali 3.8.0 Str(Td.TdRmSz, 16, 3) Chnaged To Str(Td.TdRmSz, 16, 4) For Pointer    ****/          
   Select @Row=Count('x') From Deleted Del Where Del.TdPrtKey=@wCurrPrtn and Del.TdRmCd<>'' and              
    IsNull((Select sum(Td.TdRmQty* (              
         Case when Td.TdFrRmLoc= 'W' and Td.TdFrRmDc= 'D' then 1              
      when Td.TdFrRmLoc= 'W' and Td.TdFrRmDc= 'C' then -1              
      when Td.TdToRmLoc= 'W' and Td.TdToRmDc= 'D' then 1              
      when Td.TdToRmLoc= 'W' and Td.TdToRmDc= 'C' then -1              
             Else 0 end))            
      from Txnd Td where Td.TdPrtKey=Del.TdPrtKey and Td.TdBIdNo=Del.TdBIdNo              
      and Td.TdCoCd= Del.TdCoCd and Td.TdBYy= Del.TdBYy              
      and Td.TdBChr= Del.TdBChr and Td.TdBNo= Del.TdBNo              
      and Td.TdRmCd= Del.TdRmCd and Td.TdLotNo= Del.TdLotNo              
      and Str(Td.TdRmSz, 16, 4)= Str(Del.TdRmSz, 16, 4)              
      and Str(Td.TdRmStkRt, 16, 2)= Str(Del.TdRmStkRt, 16, 2)), 0)< 0              
     If @Row>0              
   begin              
    Select @ErrMsg='Rm Qty Is Less Than Zero In Bag'              
    GoTo ErrHndlr              
   end              
  End              
              
/* Zubin 212 TdLotNo added */              
  /********TdRmWt  if 'TxnBag' then sum of RmWt should be >=0 for the given RmWt, Sz, StkRt **********/              
  /* Current Partition */              
 /***** Manali 3.8.0 Str(Td.TdRmSz, 16, 3) Chnaged To Str(Td.TdRmSz, 16, 4) For Pointer    ****/      
  Select @Row= Count('x') From Inserted Ins Where Ins.TdPrtKey=@wCurrPrtn and Ins.TdRmCd<> '' and              
   Round(IsNull((Select sum(Td.TdRmWt* (              
        Case when Td.TdFrRmLoc= 'W' and Td.TdFrRmDc= 'D' then 1              
     when Td.TdFrRmLoc= 'W' and Td.TdFrRmDc= 'C' then -1              
     when Td.TdToRmLoc= 'W' and Td.TdToRmDc= 'D' then 1              
     when Td.TdToRmLoc= 'W' and Td.TdToRmDc= 'C' then -1              
            Else 0 end))              
     from Txnd Td where Td.TdPrtKey=Ins.TdPrtKey and Td.TdBIdNo=Ins.TdBIdNo              
     and Td.TdCoCd= Ins.TdCoCd and Td.TdBYy= Ins.TdBYy              
     and Td.TdBChr= Ins.TdBChr and Td.TdBNo= Ins.TdBNo              
     and Td.TdRmCd= Ins.TdRmCd and Td.TdLotNo= Ins.TdLotNo              
     and Str(Td.TdRmSz, 16, 4)= Str(Ins.TdRmSz, 16, 4)              
     and Str(Td.TdRmStkRt, 16, 2)= Str(Ins.TdRmStkRt, 16, 2)), 0), 3)< 0              
    If @Row>0              
  BEGIN              
   Select @ErrMsg='Rm Wt Is Less Than Zero In Bag'              
   GoTo ErrHndlr              
  END              
              
  /* Manali 3.2.2 - not allowing negative RM Wt in bag in change mode*/          
/***** Manali 3.8.0 Str(Td.TdRmSz, 16, 3) Chnaged To Str(Td.TdRmSz, 16, 4) For Pointer    ****/          
  If @Mode in ('C')              
  Begin              
   Select @Row= Count('x') From Deleted Del Where Del.TdPrtKey=@wCurrPrtn and Del.TdRmCd<> '' and               
    exists(Select 'x' from Inserted Ins where            
     Ins.TdPrtKey=Del.TdPRtKey and Ins.TdBIdNo=Del.TdBIdNo              
     and Ins.TdCoCd= Del.TdCoCd and Ins.TdBYy= Del.TdBYy              
     and Ins.TdBChr= Del.TdBChr and Ins.TdBNo= Del.TdBNo              
     and (Ins.TdRmCd<> Del.TdRmCd or Ins.TdLotNo<> Del.TdLotNo              
     or Str(Ins.TdRmSz, 16, 3)<> Str(Del.TdRmSz, 16, 3)              
     or Str(Ins.TdRmStkRt, 16, 2)<> Str(Del.TdRmStkRt, 16, 2))) and              
     Round(IsNull((Select sum(Td.TdRmWt* (              
     Case when Td.TdFrRmLoc= 'W' and Td.TdFrRmDc= 'D' then 1              
      when Td.TdFrRmLoc= 'W' and Td.TdFrRmDc= 'C' then -1              
      when Td.TdToRmLoc= 'W' and Td.TdToRmDc= 'D' then 1              
      when Td.TdToRmLoc= 'W' and Td.TdToRmDc= 'C' then -1              
     Else 0 end))              
    from Txnd Td where Td.TdPrtKey=Del.TdPRtKey and Td.TdBIdNo=Del.TdBIdNo              
    and Td.TdCoCd= Del.TdCoCd and Td.TdBYy= Del.TdBYy              
    and Td.TdBChr= Del.TdBChr and Td.TdBNo= Del.TdBNo              
    and Td.TdRmCd= Del.TdRmCd and Td.TdLotNo= Del.TdLotNo              
    and Str(Td.TdRmSz, 16, 4)= Str(Del.TdRmSz, 16, 4)              
    and Str(Td.TdRmStkRt, 16, 2)= Str(Del.TdRmStkRt, 16, 2)), 0), 3)< 0               
  If @Row>0              
  Begin              
   Select @ErrMsg='Rm Wt Is Less Than Zero In Bag'              
   GoTo ErrHndlr              
  End              
  End              
              
              
  if @Mode='D'              
  Begin              
/* Zubin 212 TdLotNo added */              
   /********TdRmWt  if 'TxnBag' then sum of RmWt should be >=0 for the given RmWt, Sz, StkRt **********/              
   /* Current Partition */         
 /***** Manali 3.8.0 Str(Td.TdRmSz, 16, 3) Chnaged To Str(Td.TdRmSz, 16, 4) For Pointer    ****/         
   Select @Row= Count('x') From Deleted Del Where Del.TdPrtKey=@wCurrPrtn and Del.TdRmCd<> '' and              
    Round(IsNull((Select sum(Td.TdRmWt* (              
         Case when Td.TdFrRmLoc= 'W' and Td.TdFrRmDc= 'D' then 1              
      when Td.TdFrRmLoc= 'W' and Td.TdFrRmDc= 'C' then -1              
      when Td.TdToRmLoc= 'W' and Td.TdToRmDc= 'D' then 1              
      when Td.TdToRmLoc= 'W' and Td.TdToRmDc= 'C' then -1              
             Else 0 end))              
      from Txnd Td where Td.TdPrtKey=Del.TdPRtKey and Td.TdBIdNo=Del.TdBIdNo              
      and Td.TdCoCd= Del.TdCoCd and Td.TdBYy= Del.TdBYy              
      and Td.TdBChr= Del.TdBChr and Td.TdBNo= Del.TdBNo              
      and Td.TdRmCd= Del.TdRmCd and Td.TdLotNo= Del.TdLotNo              
      and Str(Td.TdRmSz, 16, 4)= Str(Del.TdRmSz, 16, 4)              
      and Str(Td.TdRmStkRt, 16, 2)= Str(Del.TdRmStkRt, 16, 2)), 0), 3)< 0              
     If @Row>0              
   begin              
    Select @ErrMsg='Rm Wt Is Less Than Zero In Bag'              
    GoTo ErrHndlr              
   end              
  End              
              
              
  /******* Bag Rej Qty >= 0 **********/              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins              
   Where TdPRtKey=@wCurrPrtn               
   and Not Exists (Select 'x' From Bag Where BPrtKey=Ins.TdPrtKey and BIdNo=Ins.TdBIdNo              
       and BCoCd= Ins.TdCoCd              
       and BYy= Ins.TdByy and BChr=Ins.TdBChr              
       and BNo = Ins.TdBNo and BRjQty>= 0)              
    If @Row>0              
  BEGIN              
   Select @ErrMsg= 'Cannot accept Bag Rej Qty going -ve'              
   GoTo ErrHndlr              
  END              
              
  /* ****** commented after 15/05/02 as Rej Part Qty can be -ve ******              
  ******* TdRjPtQty vBRjPtQty >=0 *******              
  Select @Row=Count('x') From Inserted Ins              
   Where Not Exists (Select 'x' From Bag              
   Where BYy= Ins.TdBYy and BChr= Ins.TdBChr and BNo = Ins.TdBNo              
    and BRjPtQty>= 0)              
    If @Row>0              
  BEGIN              
   Select @ErrMsg='Cannot accept Bag Rej Pt Qty going -ve'              
   GoTo ErrHndlr              
  END              
  */              
 End              
              
 /***** End of performing fields Valids for wEntTyp='TxnBag' ********/              
 /***************************************************************/              
              
 /******* Checks only For @wEntTyp='TxnBag'  ***********/              
 /*************    **************/              
 If @wEntTyp= 'TxnBag'              
 BEGIN              
              
  /**** if RefYy<>'' or RefKey<> 0, TdYy,TdKey should exist in same Vchr ***/              
  /*** (Bef 2.13)              
  select @Row= Count('x') from inserted Ins where              
   (TdRefYy<>'' or TdRefKey<>0) and              
   Not Exists (Select 'x' from Txnd Td where              
   Td.TdCoCd= Ins.TdCoCd and Td.TdTc= Ins.TdTc and Td.Tdyy= Ins.Tdyy              
   and Td.TdChr= Ins.TdChr and Td.TdNo= Ins.TdNo              
   and Td.TdYy= Ins.TdRefYy and Td.TdKey= Ins.TdRefKey)              
  (Bef 2.13) ***/              
  /*** (Jen 2.13) ***/               
  /* Current Partition */         
 /**** Manali 3.8.0 *****/           
  select @Row= Count('x') from inserted Ins       
  Join Txn On TPrtKey=Ins.TdPRtKey and TIdNo=Ins.TdTIdNo and TCoCd=Ins.TdCoCd and TTc=Ins.TdTc and TYy=Ins.TdYy and              
     TChr=Ins.TdChr and TNo=Ins.TdNo      
  where @wTcTyp= 'BS' and TdPRtKEy=@wCurrPrtn and TMultiIr<>'I'  and            
   (TdRefYy<> '' or TdRefKey<> 0) and               
   Not Exists (Select 'x' from Txnd Td where Td.TdPrtKey=Ins.TdPrtKey and Td.TdTIdNo=Ins.TdTIdNo               
   and Td.TdCoCd= Ins.TdCoCd and Td.TdTc= Ins.TdTc and Td.Tdyy= Ins.TdYy               
   and Td.TdChr= Ins.TdChr and Td.TdNo= Ins.TdNo               
   and Td.TdYy= Ins.TdRefYy and Td.TdKey= Ins.TdRefKey)      
  /*** (Jen 2.13) ***/              
  If @Row > 0              
  Begin              
   Select @ErrMsg= 'RefYy, RefKey is not in the Voucher'              
   GoTo ErrHndlr              
  end              
              
 /**** Bef 3.8.0 ****/      
/*  select @Row= Count('x') from inserted Ins       
  where @wTcTyp= 'BS' and TdPRtKEy=@wCurrPrtn and               
   (TdRefYy<> '' or TdRefKey<> 0) and               
   Not Exists (Select 'x' from Txnd Td where Td.TdPrtKey=Ins.TdPrtKey and Td.TdTIdNo=Ins.TdTIdNo               
   and Td.TdCoCd= Ins.TdCoCd and Td.TdTc= Ins.TdTc and Td.Tdyy= Ins.TdYy               
   and Td.TdChr= Ins.TdChr and Td.TdNo= Ins.TdNo               
   and Td.TdYy= Ins.TdRefYy and Td.TdKey= Ins.TdRefKey)               
  /*** (Jen 2.13) ***/              
  If @Row > 0              
  Begin              
   Select @ErrMsg= 'RefYy, RefKey is not in the Voucher'              
   GoTo ErrHndlr              
  end        */      
      
  /****** TdSrno=0 record to exist for SrNo<> 0 records also BagNo *******/              
  /* Current Partition */              
  select @Row=Count('x') from inserted Ins where Ins.TdPrtKey=@wCurrPrtn and Ins.TdSrNo<>0 and              
   Not Exists (Select 'x' from Txnd Td               
   where Td.TdPRtkey=Ins.TdPrtKey and Td.TdTIdNo=Ins.TdTIdNo               
   and Td.TdCoCd=Ins.TdCoCd and Td.TdTc=Ins.TdTc and Td.Tdyy=Ins.Tdyy              
   and Td.TdChr= Ins.TdChr and Td.TdNo=Ins.TdNo              
   and Td.TdSr=Ins.TdSr and Td.TdSrNo=0              
   and Td.TdBIdNo=Ins.TdBIdNo and Td.TdBYy= Ins.TdBYy and Td.TdBChr= Ins.TdBChr              
   and Td.TdBNo= Ins.TdBNo)              
  If @Row > 0              
  Begin              
   Select @ErrMsg='TdSrNo=0 record does not exist'              
   GoTo ErrHndlr              
  end              
                

  if @wTc <> 'DT'
  begin 
  /* Zubin 212 */              
  /* Lot No shld be valid from SYyMm for CoCd */              
  /* Current Partition */              
  /* Manali 3.6.0 - Company level check removed (DiaJewel )*/      
  Select @Row= Count('x') From Inserted Ins where TdPrtKey=@wCurrPrtn and TdLotNo<> '' and              
   Not(TdFrRmDc= 'C' and TdFrRmLoc= 'W') and Not(TdFrRmDc= 'D' and TdToRmLoc= 'W') and              
   /*Not ((Select PValue from Param where PTyp='MWOPT' and PMCd='MULCOTRF' and PSCd='')='Y' and @wTcTyp= 'DT') and */            
   Not Exists (Select 'x' from SYyMm where SPrtKey=TdPrtKey /*and SCoCd= TdCoCd*/ and SLotNo= TdLotNo)              
  If @Row> 0              
  begin              
   Select @ErrMsg= 'Invalid Lot No./Lot No. Does Not Exist'              
     GoTo ErrHndlr              
  end              
  /* Zubin 212 */              
  end
  
                
  /****** Cannot Update or Delete if Not the last Txn of the Bag              
   Checking for TdSrNo<>0 records *******/              
  /****** This Check Not required as Now TdPrevKey, TdKey are written in SrNo<>0              
   records, which has same value as that of SrNo=0,              
   Check is therefore same & performed with SrNo=0 check *******/              
              
  If @wTcTyp= 'BS'              
  Begin              
   /*******  TdBDc = PMCd('DC') *********/              
   /* Current Partition */              
   Select @Row= Count('x') From Inserted Ins Where TdPrtKey=@wCurrPrtn and TdSrNo= 0 and              
    Not Exists (Select 'x' From Param where PTyp= 'DC'              
        and PMCd = Ins.TdBDc and PSCd= '')              
     If @Row>0              
   begin              
    Select @ErrMsg= 'Invalid Bag DC'              
    GoTo ErrHndlr              
   end              
/* **** Zubin 211 **** */              
   /* Bag Split Can Take Place Between same Bag type, ie. between primary or between sec. bags              
    only */              
   /* Current Partition */              
   Select @Row= Count('x') From Inserted Ins              
    Join Param P1 On P1.PTyp= 'BCHR' and P1.PMCd= ins.TdBChr and P1.PSCd= ''              
    where ins.TdPrtKey=@wCurrPrtn and ins.TdSrNo= 0 and          
     Exists (Select 'x' from Txnd Td              
      Join Param P2 On P2.PTyp= 'BCHR' and P2.PMCd= Td.TdBChr and P2.PSCd= ''              
      where Td.TdPRtKey=Ins.TdPRtKey and Td.TdTIdNo=Ins.TdTIdNo and Td.TdCoCd= Ins.TdCoCd and              
      Td.TdTc= Ins.TdTc and Td.TdYy= Ins.TdYy and Td.TdChr= Ins.TdChr and              
      Td.TdNo= Ins.TdNo and Td.TdSrNo= 0 and P2.PValue<> P1.PValue )              
     If @Row> 0              
   begin              
    Select @ErrMsg= 'Bag Split Can Take Place Between Same Bag Type'              
    GoTo ErrHndlr              
   end              
/* **** Zubin 211 **** */              
           
   /****** If Pvalue(TdTc)= 'BS' and TdSrNo= 0, and More              
    than 1 record with SrNo= 0, TdBDc= 'C' in same Vchr              
    Only One Parent Bag allowed in Bag Split ********/          
   /* Current Partition */        
 /***** Manali 3.8.0 ****/             
   select @Row= Count('x') from inserted Ins       
  Join Txn On TPrtKey=Ins.TdPRtKey and TIdNo=Ins.TdTIdNo and TCoCd=Ins.TdCoCd and TTc=Ins.TdTc and TYy=Ins.TdYy and              
     TChr=Ins.TdChr and TNo=Ins.TdNo      
  where Ins.TdPRtKey=@wCurrPrtn and (TMultiIr='R' or TTrfQty>0) and       
    (Select count('x') from Txnd  where Txnd.TdPrtKey=Ins.TdPRtKey               
     and Txnd.TdTIdNo=Ins.TdTIdNo and Txnd.TdCoCd=Ins.TdCoCd and              
     Txnd.TdTc=Ins.TdTc and Txnd.TdYy=Ins.TdYy and              
     Txnd.TdChr=Ins.TdChr and Txnd.TdNo=Ins.TdNo and              
     Txnd.TdSrNo= 0 and Txnd.TdBDc='C')> 1              
    and TdBDc='C' and TdSrNo= 0              
   If @Row > 0              
      begin              
 Select @ErrMsg='Only One Parent Bag allowed in Bag Split'              
    GoTo ErrHndlr              
   end              
      
   select @Row= Count('x') from inserted Ins       
  Join Txn On TPrtKey=Ins.TdPRtKey and TIdNo=Ins.TdTIdNo and TCoCd=Ins.TdCoCd and TTc=Ins.TdTc and TYy=Ins.TdYy and              
     TChr=Ins.TdChr and TNo=Ins.TdNo      
  where Ins.TdPRtKey=@wCurrPrtn and TMultiIr='I' and       
    (Select count('x') from Txnd  where Txnd.TdPrtKey=Ins.TdPRtKey               
     and Txnd.TdTIdNo=Ins.TdTIdNo and Txnd.TdCoCd=Ins.TdCoCd and              
     Txnd.TdTc=Ins.TdTc and Txnd.TdYy=Ins.TdYy and              
     Txnd.TdChr=Ins.TdChr and Txnd.TdNo=Ins.TdNo and              
     Txnd.TdSrNo= 0 and Txnd.TdBDc='D')> 1              
    and TdBDc='D' and TdSrNo= 0              
   If @Row > 0              
      begin              
    Select @ErrMsg='Only One Child Bag allowed in Bag Split'              
    GoTo ErrHndlr              
   end              
      
   select @Row= Count('x') from inserted Ins       
  Join Txn On TPrtKey=Ins.TdPRtKey and TIdNo=Ins.TdTIdNo and TCoCd=Ins.TdCoCd and TTc=Ins.TdTc and TYy=Ins.TdYy and              
     TChr=Ins.TdChr and TNo=Ins.TdNo      
  where Ins.TdPRtKey=@wCurrPrtn and TMultiIr='I' and       
    exists(Select 'x' from Txnd  where Txnd.TdPrtKey=Ins.TdPRtKey               
     and Txnd.TdTIdNo=Ins.TdTIdNo and Txnd.TdCoCd=Ins.TdCoCd and              
     Txnd.TdTc=Ins.TdTc and Txnd.TdYy=Ins.TdYy and              
     Txnd.TdChr=Ins.TdChr and Txnd.TdNo=Ins.TdNo and              
     Txnd.TdSr<Ins.TdSr and Txnd.TdSrNo= 0 and Txnd.TdBDc='D')      
    and TdBDc='C' and TdSrNo= 0              
   If @Row > 0              
      begin              
    Select @ErrMsg='Only 1 set allowed in Bag Split'              
    GoTo ErrHndlr              
   end              
      
/***** Bef 3.8.0 *****/      
/*   select @Row= Count('x') from inserted Ins where Ins.TdPRtKey=@wCurrPrtn and              
    (Select count('x') from Txnd  where Txnd.TdPrtKey=Ins.TdPRtKey               
     and Txnd.TdTIdNo=Ins.TdTIdNo and Txnd.TdCoCd=Ins.TdCoCd and              
     Txnd.TdTc=Ins.TdTc and Txnd.TdYy=Ins.TdYy and              
     Txnd.TdChr=Ins.TdChr and Txnd.TdNo=Ins.TdNo and              
     Txnd.TdSrNo= 0 and Txnd.TdBDc='C')> 1              
    and TdBDc='C' and TdSrNo= 0              
   If @Row > 0              
      begin              
    Select @ErrMsg='Only One Parent Bag allowed in Bag Split'              
    GoTo ErrHndlr              
   end        */      
              
              
   /****** If  Pvalue(TdTc)='Bs', TdSrNo=0 and TdBc= 'D',               
    and No  record with SrNo= 0, TdBdc= 'C' in same Vchr               
    No Parent Bag for the Child Bag ************/              
   /* Current Partition */              
   select @Row= Count('x') from inserted Ins where TdPrtKEy=@wCurrPRtn and TdSrNo= 0 and TdBDc= 'D' and               
    Not Exists (Select 'x' from Txnd                
      where Txnd.TdPrtKey=Ins.TdPrtKey and Txnd.TdTIdNo=Ins.TdTIdNo              
       and Txnd.TdCoCd=Ins.TdCoCd and Txnd.TdTc=Ins.TdTc and Txnd.TdYy=Ins.Tdyy and               
      Txnd.TdChr=Ins.TdChr and Txnd.TdNo=Ins.Tdno and               
         Txnd.TdSrno= 0 and Txnd.TdBDc= 'C')               
     If @Row > 0               
     Begin              
    Select @ErrMsg= 'No Parent Bag For The Child Bag '              
      GoTo ErrHndlr              
     end              
              
   /******** If Pvalue(TdTc)= 'Bs' and TdSrno=0 and Bdc= 'D'               
     Then RefYy<>'' and RefKey<>0 *********/               
   /* Current Partition */         
 /**** Manali 3.8.0 *****/          
   select @Row= Count('x') from inserted Ins      
  Join Txn On TPrtKey=Ins.TdPRtKey and TIdNo=Ins.TdTIdNo and TCoCd=Ins.TdCoCd and TTc=Ins.TdTc and TYy=Ins.TdYy and              
     TChr=Ins.TdChr and TNo=Ins.TdNo      
  where TdPrtKey=@wCurrPrtn and TdSrNo= 0 and ((TMultiIr<>'I' and TdBDc= 'D') /*or (TMultiIr='I' and TdBDc= 'C')*/)      
    and (TdRefYy= '' or TdRefKey<= 0)              
       If @Row > 0              
        begin              
    Select @ErrMsg= 'RefYy / RefKey cannot be Blank'              
      GoTo ErrHndlr              
     end              
            
  /***** Bef 3.8.0 *****/        
   /* select @Row= Count('x') from inserted where TdPrtKey=@wCurrPrtn and TdSrNo= 0 and TdBDc= 'D'               
    and (TdRefYy= '' or TdRefKey<= 0)              
       If @Row > 0              
        begin              
    Select @ErrMsg= 'RefYy / RefKey cannot be Blank'              
      GoTo ErrHndlr              
     end */      
      
   /****** If Pvalue(TdTc) = 'BS', TdSrno=0 and TdBDc='D'              
    Bag in RefYy, RefKey shall be of same BodDmCd *******/              
    /* Current Partition */          
  /**** Manali 3.8.0 *****/      
    select @Row= Count('x') from inserted Ins       
  Join Txn On TPrtKey=Ins.TdPRtKey and TIdNo=Ins.TdTIdNo and TCoCd=Ins.TdCoCd and TTc=Ins.TdTc and TYy=Ins.TdYy and              
     TChr=Ins.TdChr and TNo=Ins.TdNo      
  where Ins.TdPRtKey=@wCurrPrtn and              
    Not Exists (Select 'x' from Txnd where Txnd.TdPRtKey=Ins.TdPrtKey and Txnd.TdCoCd= Ins.TdCoCd and            
         ((TMultiIr<>'I' and Txnd.TdYy= Ins.TdRefYy and Txnd.TdKey= Ins.TdRefKey)      
     or       
         (TMultiIr='I' and Txnd.TdRefYy= Ins.TdYy and Txnd.TdRefKey= Ins.TdKey))      
         and (select BOdDmCd from Bag where BPrtKey=Txnd.TdPrtKey and BIdNo=Txnd.TdBIdNo              
       and BCoCd= Txnd.TdCoCd and BYy= Txnd.TdByy and BChr= Txnd.TdBChr              
       and BNo= Txnd.TdBNo)              
           = (select BOdDmCd from Bag where BPrtKey=Ins.TdPrtKey and BIdNo=Ins.TdBIdNo              
       and BCoCd= Ins.TdCoCd and Byy= Ins.TdByy and BChr= Ins.TdBChr and BNo= Ins.TdBNo)              
            )              
          and TdBDc= 'D' and TdSrNo= 0              
    and Str(TtrfQty, 16, 1) = Str(0, 16, 1)              
        If @Row > 0              
        Begin              
    Select @ErrMsg='Design Code Of Parent Not Same As Child '      
      GoTo ErrHndlr              
        end            
       
  /**** Bef 3.8.0 *****/      
    /*   select @Row= Count('x') from inserted Ins where Ins.TdPRtKey=@wCurrPrtn and              
    Not Exists (Select 'x' from Txnd where Txnd.TdPRtKey=Ins.TdPrtKey and Txnd.TdCoCd= Ins.TdCoCd and              
         Txnd.TdYy= Ins.TdRefYy and Txnd.TdKey= Ins.TdRefKey              
         and (select BOdDmCd from Bag where BPrtKey=Txnd.TdPrtKey and BIdNo=Txnd.TdBIdNo              
       and BCoCd= Txnd.TdCoCd and BYy= Txnd.TdByy and BChr= Txnd.TdBChr              
       and BNo= Txnd.TdBNo)              
           = (select BOdDmCd from Bag where BPrtKey=Ins.TdPrtKey and BIdNo=Ins.TdBIdNo              
       and BCoCd= Ins.TdCoCd and Byy= Ins.TdByy and BChr= Ins.TdBChr and BNo= Ins.TdBNo)              
            )              
          and TdBDc= 'D' and TdSrNo= 0              
    and exists (Select 'x' from Txn where TPrtKey=TdPrtKEy and TIdNo=TdTIdNo and TCoCd = TdCoCd and TTc= TdTc               
         and TYy= TdYy and TChr= TdChr and TNo= TdNo              
         and Str(TtrfQty, 16, 1) = Str(0, 16, 1))              
        If @Row > 0              
        Begin              
    Select @ErrMsg='Design Code Of Parent Not Same As Child'              
      GoTo ErrHndlr              
        end    */          
              
 /****** If PValue(TdTc) = 'BS', TdSrNo= 0 and TdBc= 'D'              
    Child OrdRm should have the same RM Content as in the parent Bag *******/              
    /* Current Partition */        
  /**** Manali 3.8.0 *****/       
 If Exists(Select 'x' from Txn      
   Join Inserted on TdCoCd=TCoCd and TTc=TdTc and TYy=TdYy and TChr=TdChr and TNo=TdNo and       
    TIdNo=TdTIdNo and TPRtKey=TdPrtKey      
   Where TdBDc= 'D' and TdSrNo= 0 and TMultiIr='I') and @mode='A'      
 Begin           
    select @Row= Count('x') from inserted Ins       
  /*Join Txn On TPrtKey=Ins.TdPRtKey and TIdNo=Ins.TdTIdNo and TCoCd=Ins.TdCoCd and TTc=Ins.TdTc and TYy=Ins.TdYy and              
     TChr=Ins.TdChr and TNo=Ins.TdNo*/      
  where Ins.TdPrtKey=@wCurrPrtn and               
    Exists (Select 'x' from Txnd Td               
 join Txnd Tdr on Tdr.TdPrtKey=Td.TdPrtKey and Tdr.TdBIdNo=Td.TdBIdNo              
         and Tdr.TdCoCd= Td.TdCoCd and Tdr.TdBYy= Td.TdBYy and Tdr.TdBChr= Td.TdBChr               
         and Tdr.TdBNo= Td.TdBNo and Tdr.TdSrNo<> 0               
     where Td.TdSrNo= 0 and Td.TdPrtKey=Ins.TdPrtKey and Td.TdCoCd= Ins.TdCoCd and           
   Td.TdRefYy= Ins.TdYy and Td.TdRefKey= Ins.TdKey      
        /* ((TMultiIr<>'I' and Td.TdYy= Ins.TdRefYy and Td.TdKey= Ins.TdRefKey) or      
     (TMultiIr='I' and Td.TdRefYy= Ins.TdYy and Td.TdRefKey= Ins.TdKey))*/      
         and Tdr.TdRmCd Not in (select OrRmCd from Bag               
        join OrdRm on BPrtKey=OrPrtKey and BOdIdNo=OrOdIdNo and              
         BCoCd= OrCoCd and BOdTc= OrTc and BOdYy= OrYy and BOdChr= OrChr               
         and BOdNo= OrNo and BOdSr= OrSr               
         where BPrtKey=Ins.TdPrtKey and BIdNo=Ins.TdBIdNo and BCoCd= Ins.TdCoCd               
          and BYy= Ins.TdBYy and BChr= Ins.TdBChr and BNo= Ins.TdBNo)               
         )              
          and Ins.TdBDc= 'D' and Ins.TdSrNo= 0              
    If @Row > 0              
        Begin              
    Select @ErrMsg= 'RM Code Of Parent Not Same As Child'              
      GoTo ErrHndlr              
        end              
 eND      
      
  /***** Bef 3.8.0 *****/      
 If Exists(Select 'x' from Txn      
   Join Inserted on TdCoCd=TCoCd and TTc=TdTc and TYy=TdYy and TChr=TdChr and TNo=TdNo and       
    TIdNo=TdTIdNo and TPRtKey=TdPrtKey      
   Where TdBDc= 'D' and TdSrNo= 0 and TMultiIr='R')  and @mode='A'      
 Begin      
    select @Row= Count('x') from inserted Ins where Ins.TdPrtKey=@wCurrPrtn and               
    Exists (Select 'x' from Txnd Td               
       join Txnd Tdr on Tdr.TdPrtKey=Td.TdPrtKey and Tdr.TdBIdNo=Td.TdBIdNo              
         and Tdr.TdCoCd= Td.TdCoCd and Tdr.TdBYy= Td.TdBYy and Tdr.TdBChr= Td.TdBChr               
         and Tdr.TdBNo= Td.TdBNo and Tdr.TdSrNo<> 0               
     where Td.TdSrNo= 0 and Td.TdPrtKey=Ins.TdPrtKey and Td.TdCoCd= Ins.TdCoCd and               
         Td.TdYy= Ins.TdRefYy and Td.TdKey= Ins.TdRefKey               
         and Tdr.TdRmCd not in(select OrRmCd from Bag               
        join OrdRm on BPrtKey=OrPrtKey and BOdIdNo=OrOdIdNo and              
         BCoCd= OrCoCd and BOdTc= OrTc and BOdYy= OrYy and BOdChr= OrChr               
         and BOdNo= OrNo and BOdSr= OrSr               
         where BPrtKey=Ins.TdPrtKey and BIdNo=Ins.TdBIdNo and BCoCd= Ins.TdCoCd               
          and BYy= Ins.TdBYy and BChr= Ins.TdBChr and BNo= Ins.TdBNo)               
         )              
          and Ins.TdBDc= 'D' and Ins.TdSrNo= 0              
    If @Row > 0              
        Begin              
    Select @ErrMsg= 'RM Code Of Parent Not Same As Child'              
      GoTo ErrHndlr              
        end       
 End           
              
/****** Cross Transfer ******/              
/****** Cross Transfer ******/              
/****** Cross Transfer ******/              
              
   /****** Check if Transfer Qty is Available in the Bag  *******/              
    /* Current Partition */              
        select @Row= Count('x') from inserted              
    join Txn on TPrtKey=TdPrtKey and TCoCd = TdCoCd and TTc = TdTc and TYy = TdYy              
     and TChr = TdChr and TNo = TdNo              
    where Str(TtrfQty, 16, 1) <> Str(0, 16, 1) and              
     Round(TtrfQty, 1) > Round(IsNull((Select BQty from Bag              
        where BPrtKey=TdPrtkey and BIdNo=TdBIdNo and BCoCd = TdCoCd              
        and BYy = TdBYy              
        and BChr = TdBChr              
        and BNo = TdBNo), 0), 1)              
        If @Row > 0              
        Begin              
    Select @ErrMsg= 'Transfer Quantity Is More Than Bag Quantity'              
      GoTo ErrHndlr              
        end              
              
   /****** If Transfer Qty is Available Then TdBQty = 0 & TdPtQty = 0 *******/              
    /* Current Partition */              
        select @Row= Count('x') from inserted              
join Txn on TPrtKey=TdPrtKey and TIdNo=TdTIdNo and              
     TCoCd = TdCoCd and TTc = TdTc and TYy = TdYy              
     and TChr = TdChr and TNo = TdNo              
    where TdPrtKEy=@wCurrPrtn and  (Str(TdBQty, 16, 1) <> Str(0, 16, 1)              
      Or Str(TdPtQty, 16, 1) <> Str(0, 16, 1)              
        )              
     AND Str(TTrfQty, 16, 1) <> Str(0, 16, 1)              
        If @Row > 0              
        Begin              
    Select @ErrMsg= 'Bag Issue/ Receipt Qty Should Be Zero If Transfer Quantity Is Entered'              
      GoTo ErrHndlr              
        end              
              
   /****** If Pvalue(TdTc)='BS' and TdSrno= 0, and More              
    than 1 record with Srno= 0, TdBdc= 'D' in same Vchr              
    Only One Child Bag allowed in Bag Split with Cross Transfer ********/              
   /* Current Partition */              
   select @Row= Count('x') from inserted Ins where Ins.TdPrtKey=@wCurrPrtn and               
    (Select count('x') from Txnd  where Txnd.TdPrtKey=Ins.TdPrtKey               
     and Txnd.TdTIdNo=Ins.TdTIdNo and Txnd.TdCoCd=Ins.TdCoCd and              
     Txnd.TdTc=Ins.TdTc and Txnd.TdYy=Ins.TdYy and              
     Txnd.TdChr=Ins.TdChr and Txnd.TdNo=Ins.TdNo and              
     Txnd.TdSrNo= 0 and Txnd.TdBDc= 'D')> 1              
    and TdBDc= 'D' and TdSrNo= 0            
    and exists (Select 'x' from Txn where TPrtKey=TdPrtKey and TCoCd = TdCoCd and TTc= TdTc              
         and TYy= TdYy and TChr= TdChr and TNo= TdNo              
         and Str(TtrfQty, 16, 1) <> Str(0, 16, 1))              
   If @Row> 0              
      begin              
    Select @ErrMsg= 'Only One Child Bag Allowed In Cross Transfer'              
    GoTo ErrHndlr              
   end              
              
   /****** If PValue(TdTc) = 'BS', TdSrNo= 0 and TdBc= 'D'              
    Parent OrdRm should have the same RM Content as in the child Bag *******/              
    /* Current Partition */             
      
        select @Row= Count('x') from inserted Ins where Ins.TdPrtKey=@wCurrPrtn and               
    exists (Select 'x' from Txn where TPRtKey=Ins.TdPrtKey               
      and TIdNo=Ins.TdTIdNo and TCoCd = Ins.TdCoCd and TTc= Ins.TdTc              
         and TYy= Ins.TdYy and TChr= Ins.TdChr and TNo= Ins.TdNo              
         and Str(TtrfQty, 16, 1) <> Str(0, 16, 1)) and              
    Exists (Select 'x' from Txnd TdD where TdD.TdSrNo<> 0 and TdD.TdPrtKey=Ins.TdPrtKey               
      and TdD.TdBIdNo=Ins.TdBIdNo and TdD.TdCoCd= Ins.TdCoCd and              
         TdD.TdBYy= Ins.TdBYy and TdD.TdBChr= Ins.TdBChr and TdD.TdBNo= Ins.TdBNo              
    and TdD.TdRmCd not in(select OrRmCd from Txnd TdC              
          join Bag on BPrtKey=TdC.TdPrtKey and BIdNo=TdC.TdBIdNo              
         and BCoCd= TdC.TdCoCd and BYy= TdC.TdBYy              
         and BChr= TdC.TdBChr and BNo= TdC.TdBNo              
          join OrdRm on BPrtKey=OrPrtKey and BOdIdNo=OrOdIdNo              
         and BCoCd= OrCoCd and BOdTc= OrTc              
         and BOdYy= OrYy and BOdChr= OrChr              
         and BOdNo= OrNo and BOdSr= OrSr              
          where TdC.TdSrNo= 0 and TdC.TdPrtKEy=Ins.TdPrtKey               
         and TdC.TdCoCd= Ins.TdCoCd and TdC.TdYy= Ins.TdRefYy              
         and TdC.TdKey= Ins.TdRefKey)              
         )              
          and Ins.TdBDc= 'D' and Ins.TdSrNo= 0              
        If @Row > 0              
        Begin              
    Select @ErrMsg= 'RM Code Of Child Not Same As Parent'      
      GoTo ErrHndlr              
        end           
              
/****** Cross Transfer ******/              
/****** Cross Transfer ******/              
/****** Cross Transfer ******/              
              
              
   if @mode in ('D')              
   begin              
              
    /****** Cannot Delete 'Bs', TdDc='C', Tdsrno= 0              
    If exists TdBDc='D', TdSrno=0 in same voucher ********/              
    /* Current Partition */               
    select @Row=Count('x') from Deleted Del where Del.TdPrtKey=@wCurrPrtn and              
     Exists (Select 'x' from Txnd  where Txnd.TdPRtKEy=Del.TdPrtKey and              
      Txnd.TdTIdNo=Del.TdTIdNo and Txnd.TdCoCd= Del.TdCoCd and Txnd.TdTc= Del.TdTc and              
      Txnd.TdYy= Del.TdYy and Txnd.TdChr= Del.TdChr and              
      Txnd.TdNo= Del.TdNo and Txnd.TdBDc= 'D' and TdSrNo= 0              
             )              
           and TdBDc= 'C' and TdSrNo= 0              
    If @Row > 0              
         begin              
       Select @ErrMsg='Cannot Delete Parent, Child Exists'              
       GoTo ErrHndlr              
         end              
              
   end              
              
  End              
              
              
/* **** Zubin 211 **** */ /* **** Zubin 211 **** */ /* **** Zubin 211 **** */ /* **** Zubin 211 **** */              
  If @wTcTyp= 'BM'              
  Begin              
   /*******  TdBDc = PMCd('DC') *********/              
   /* Current Partition */              
   Select @Row= Count('x') From Inserted Ins Where TdPrtKey=@wCurrPrtn and TdSrNo= 0 and              
    Not Exists (Select 'x' From Param where PTyp= 'DC' and PMCd = Ins.TdBDc and PSCd= '')              
     If @Row> 0              
   begin              
    Select @ErrMsg= 'Invalid Bag DC'              
    GoTo ErrHndlr              
   end              
              
   /* 'Primary' bag will always be Receiving Bag */              
   /****** (Jay 2.13 CT) where clause changed for 'BCHR' ******/              
   /* Current Partition */              
   Select @Row= Count('x') From Inserted Ins Where TdPrtkey=@wCurrPrtn and TdSrNo= 0 and              
    Exists (Select 'x' from Param where PTyp= 'BCHR' and PMCd= TdBChr and PSCd= '' and              
     PValue= 'P') and TdBDc= 'C'              
     If @Row> 0              
   begin              
    Select @ErrMsg= 'Primary Bag Will Always Be The Receiving Bag'              
    GoTo ErrHndlr              
   end              
              
   /****** (Jen 2.13 CT) where clause changed for 'BCHR' ******/              
   /* 'Sec' Bag will always be Issuing bag */              
   /* Current Partition */              
   Select @Row= Count('x') From Inserted Ins Where TdPRtKey=@wCurrPrtn and TdSrNo= 0 and              
    Exists (Select 'x' from Param where PTyp= 'BCHR' and PMCd= TdBChr and PSCd= '' and              
     PValue in ('C', 'F')) and TdBDc= 'D'              
     If @Row> 0              
   begin              
    Select @ErrMsg= 'Flute/ Component Bag Will Always Be The Issuing Bag'              
    GoTo ErrHndlr            
   end              
              
   /* issuing Bag character will always be same */              
   /*** (Bef 2.13)               
   Select @Row= Count('x') From Inserted Ins Where ins.TdSrNo= 0 and ins.TdBDc= 'C' and              
    Exists (Select 'x' from Txnd Td where ins.TdCoCd= Td.TdCoCd and ins.TdTc= Td.TdTc and              
     ins.TdYy= Td.TdYy and ins.TdChr= Td.TdChr and ins.TdNo= Td.TdNo and              
     Td.TdSrNo= 0 and Td.TdBDc= 'C' and Td.TdBChr<> ins.TdBChr)              
     If @Row> 0              
   begin              
    Select @ErrMsg= 'Flute Bag Character In Bag Merge Should Be Same'              
    GoTo ErrHndlr              
   end              
   (Bef 2.13) ***/              
           
   /* if flute bag then BQty >= 0 */              
   /* Current Partition */              
   Select @Row= Count('x') From Inserted Where TdPrtKey=@wCurrPrtn and TdSrNo= 0 and TdBDc= 'C' and TdBQty< 0              
     If @Row> 0              
   begin              
    Select @ErrMsg= 'Flute Bag Quantity Should Be >= 0 '              
    GoTo ErrHndlr              
   end              
              
              
   /*** (Bef 2.13)              
   --****** If  Pvalue(TdTc)='BM', TDSrno=0 and TdBc='D',              
   -- and No  record with Srno=0, TdBdc='C' in same Vchr              
   -- No Parent Bag for the Child Bag ************              
   select @Row= Count('x') from inserted Ins where              
    Not Exists (Select 'x' from Txnd where Txnd.TdCoCd= Ins.TdCoCd and              
         Txnd.TdTc= Ins.TdTc and Txnd.TdYy= Ins.TdYy and              
      Txnd.TdChr= Ins.TdChr and Txnd.TdNo= Ins.TdNo and              
         Txnd.TdSrno= 0 and Txnd.TdBDc= 'C')              
    and TdBDc= 'D' and TdSrno= 0              
     If @Row> 0              
        Begin              
    Select @ErrMsg= 'No Parent Bag For The Child Bag'              
      GoTo ErrHndlr              
     end              
              
   --******** If Pvalue(TdTc)='BM' and TdSrNo=0              
   --   Then RefYy<>'' and RefKey<> 0 *********              
   select @Row= Count('x') from inserted where TdSrNo= 0 and (TdRefYy<> '' or TdRefKey<> 0)              
       If @Row > 0              
        begin              
    Select @ErrMsg='RefYy / RefKey Should be Blank'              
      GoTo ErrHndlr              
     end              
              
   --****** If Pvalue(TdTc) = 'BM', TdSrNo= 0 then the BOdDmCd shld be the same as that of               
    the issuing bag *******               
   select @Row= Count('x') from inserted Ins              
    Join Txnd Td On Td.TdCoCd= Ins.TdCoCd and              
     Td.TdTc= Ins.TdTc and Td.TdYy= Ins.TdYy and Td.TdChr= Ins.TdChr and              
     Td.TdNo= Ins.TdNo and Td.TdSrNo= 0              
    where Ins.TdSrNo= 0 and              
     (select BOdDmCd from Bag where BCoCd= Td.TdCoCd and              
      BYy= Td.TdBYy and BChr= Td.TdBChr and BNo= Td.TdBNo)<>              
     (select BOdDmCd from Bag where BCoCd= Ins.TdCoCd and              
      Byy= Ins.TdBYy and BChr= Ins.TdBChr and BNo= Ins.TdBNo)              
        If @Row> 0              
        Begin              
    Select @ErrMsg= 'Design Code Not Same As That Of Previous Bag'              
      GoTo ErrHndlr              
        end              
             
   --****** If PValue(TdTc) = 'BM', TdSrNo= 0 and TdBc= 'D'              
    Child OrdRm should have the same RM Content as in the parent Bag *******              
        select @Row= Count('x') from inserted Ins where              
    Exists (Select 'x' from Txnd Td              
      join Txnd TdRm on TdRm.TdCoCd= Td.TdCoCd              
       and TdRm.TdBYy= Td.TdBYy and TdRm.TdBChr= Td.TdBChr              
       and TdRm.TdBNo= Td.TdBNo and TdRm.TdSrNo<> 0              
      where Td.TdSrNo= 0 and Td.TdBDc= 'C' and Td.TdCoCd= Ins.TdCoCd and              
       Td.TdTc= Ins.TdTc and Td.TdYy= Ins.TdYy and              
       Td.TdChr= Ins.TdChr and Td.TdNo= Ins.TdNo and              
       TdRm.TdRmCd Not In(select OrRmCd from Bag              
        join OrdRm on BCoCd= OrCoCd and              
          BOdTc= OrTc and BOdYy= OrYy and BOdChr= OrChr              
         and BOdNo= OrNo and BOdSr= OrSr              
         where BCoCd= Ins.TdCoCd and BYy= Ins.TdBYy              
          and BChr= Ins.TdBChr and BNo= Ins.TdBNo)              
         )              
          and Ins.TdSrNo= 0 and Ins.TdBDc= 'D'              
    If @Row> 0              
        Begin              
    Select @ErrMsg= 'RM Code Of Parent Not Same As Child'              
      GoTo ErrHndlr              
        end              
              
   (Bef 2.13) ***/              
              
              
              
   /*** (Jen 2.13) ***/              
              
   /****** If  Pvalue(TdTc)='BM', TDSrno=0 and TdBc='D',              
    and No  record with SrNo= 0, TdBdc='C' with same TdRefKey in same Vchr              
    No Parent Bag for the Child Bag ************/              
   /* Current Partition */              
   select @Row= Count('x') from inserted Ins where Ins.TdPRtKey=@wCurrPrtn and              
    Not Exists (Select 'x' from Txnd where Txnd.TdPrtKey=Ins.TdPrtKey and Txnd.TdTIdNo=Ins.TdTIdNo              
      and Txnd.TdCoCd= Ins.TdCoCd and Txnd.TdTc= Ins.TdTc               
         and Txnd.TdYy= Ins.TdYy and Txnd.TdChr= Ins.TdChr and Txnd.TdNo= Ins.TdNo               
         and Txnd.TdSrNo= 0 and Txnd.TdBDc= 'C' and Txnd.TdRefKey= Ins.TdRefKey)               
    and TdBDc= 'D' and TdSrNo= 0              
     If @Row> 0              
        Begin            
    Select @ErrMsg= 'No Parent Bag For The Child Bag'              
      GoTo ErrHndlr              
     end              
              
   /*** 18/09/2006 ***/              
   /* Current Partition */               
   select @Row= Count('x') from               
     (Select sum(TdBQty) as qQty from Txnd Tc               
     where exists (Select 'x' from inserted ins               
      where ins.TdBDc= 'D' and ins.TdSrNo= 0               
      and ins.TdPRtKey=Tc.TdPrtKey and ins.TdTIdNo=Tc.TdTIdNo               
      and ins.TdCoCd= Tc.TdCoCd and ins.TdTc= Tc.TdTc               
      and ins.TdYy= Tc.TdYy and ins.TdChr= Tc.TdChr               
      and ins.TdNo= Tc.TdNo and ins.TdRefKey= Tc.TdRefKey)              
      and Tc.TdSrNo= 0 and Tc.TdBDc= 'C'                
     group By TdBChr) Tbl               
     having convert (decimal (16, 1), min(qQty))<> convert (decimal (16, 1), max(qQty))               
     If @Row> 0               
        Begin              
    Select @ErrMsg= 'Total Issue Qty For All Bag Characters Do Not Match'              
      GoTo ErrHndlr              
     end              
   /*** 18/09/2006 ***/              
              
   /****** If Pvalue(TdTc)= 'BM' (Bag Merge) and TdSrNo= 0, in same Vchr               
    Multiple Issue/Receipt sets allowed. A new set is allowed only               
    if the earlier sets are completely matched ********/              
   /*** (18/09/2006) (Works for Multiple Issue Bag Characters)               
    sum for 'D' and max for 'C' as total BQty of 'C' bags for all Bag Chr's put together               
    should match total of each Bag Chr of 'D' Bags ***/                
   if @mode in ('A')              
   begin              
    /* Current Partition */              
 /* Check below is changed            
    select @Row= Count('x') from               
     (Select sum(case when Tc.TdBDc= 'C' then Tc.TdBQty else 0 end) as qCrQty,               
      sum(case when Tc.TdBDc= 'D' then Tc.TdBQty else 0 end) as qDrQty,               
      Tc.TdRefKey as qTdRefKey               
     from Txnd Tc where Tc.TdPrtKey=@wCurrPrtn and exists (Select 'x' from inserted ins               
      where ins.TdBDc= 'C' and ins.TdSrNo= 0               
      and ins.TdPrtKey=Tc.TdPrtKey and ins.TdTIdNo=Tc.TdTIdNo               
      and ins.TdCoCd= Tc.TdCoCd and ins.TdTc= Tc.TdTc   
      and ins.TdYy= Tc.TdYy and ins.TdChr= Tc.TdChr               
      and ins.TdNo= Tc.TdNo and Tc.TdRefKey< ins.TdRefKey)               
     and Tc.TdSrNo= 0               
     group By Tc.TdRefKey, Tc.TdBChr) Tbl               
     group By qTdRefKey               
     having convert( decimal (16, 1), sum(qDrQty))<> convert( decimal (16, 1), max(qCrQty))               
    If @Row > 0              
       begin              
     Select @ErrMsg= 'Complete The Matching Of Previous Parent-Child Records Before Starting Another Set'              
     GoTo ErrHndlr              
    end               
 */            
            
 /*            
 And exists (Select 'x' from inserted ins  where              
      and ins.TdPrtKey=Tc.TdPrtKey and ins.TdTIdNo=Tc.TdTIdNo               
      and ins.TdCoCd= Tc.TdCoCd and ins.TdTc= Tc.TdTc               
      and ins.TdYy= Tc.TdYy and ins.TdChr= Tc.TdChr               
      and ins.TdNo= Tc.TdNo and Tc.TdRefKey< ins.TdRefKey)               
     */              
            
    Select @Row= Count('x') from               
     (Select sum(case when Tc.TdBDc= 'C' then Tc.TdBQty else 0 end) as qCrQty,               
    sum(case when Tc.TdBDc= 'D' then Tc.TdBQty else 0 end) as qDrQty,               
    Tc.TdRefKey as qTdRefKey               
    From Txnd Tc             
  Join Inserted ins on ins.TdPrtKey=Tc.TdPrtKey and ins.TdTIdNo=Tc.TdTIdNo             
       and ins.TdCoCd= Tc.TdCoCd and ins.TdTc= Tc.TdTc             
       and ins.TdYy= Tc.TdYy and ins.TdChr= Tc.TdChr and ins.TdNo= Tc.TdNo             
       and Tc.TdRefKey<ins.TdRefKey             
 Where Tc.TdPrtKey=@wCurrPrtn and ins.TdBDc='C' and ins.TdSrNo=0 and Tc.TdSrNo=0              
    Group By Tc.TdRefKey, Tc.TdBChr) Tbl               
    Group By qTdRefKey               
    Having Convert(decimal(16, 1), sum(qDrQty))<>Convert(decimal(16, 1), max(qCrQty))            
    If @Row > 0              
    begin              
   Select @ErrMsg= 'Complete The Matching Of Previous Parent-Child Records Before Starting Another Set'              
   GoTo ErrHndlr              
    end               
              
   /* (This works too)               
   select @Row= Count('x') from inserted ins               
    where ins.TdBDc= 'C' and ins.TdSrNo= 0               
     and exists (Select 'x' from Txnd Tc where ins.TdCoCd= Tc.TdCoCd               
     and ins.TdTc= Tc.TdTc and ins.TdYy= Tc.TdYy and ins.TdChr= Tc.TdChr               
     and ins.TdNo= Tc.TdNo and Tc.TdSrNo= 0 and Tc.TdBDc= 'C'               
     and Tc.TdRefKey< ins.TdRefKey group By Tc.TdRefKey, Tc.TdBChr               
     having convert( decimal (16, 1), sum(TdBQty))<>               
      convert( decimal (16, 1), IsNull((Select Sum(TdBQty) From Txnd Td               
      where Td.TdCoCd= ins.TdCoCd and Td.TdTc= ins.TdTc and Td.TdYy= ins.TdYy               
      and Td.TdChr= ins.TdChr and Td.TdNo= ins.TdNo and Td.TdRefKey= Tc.TdRefKey               
      and Td.TdBDc= 'D' and Td.TdSrNo= 0), 0))               
     )               
   */              
   /*** (18/09/2006) ***/              
              
   /*** (Bef 18/09/2006) (Works only for single Issue 'BCHR')               
   select @Row= Count('x') from inserted Ins where               
    TdBDc= 'C' and TdSrNo= 0 and               
    IsNull((Select sum(Td.TdBQty* (case when Td.TdBDc= 'C' then -1 when Td.TdBDc= 'D' then 1 else 0 end))               
     from Txnd Td where Td.TdCoCd= Ins.TdCoCd and Td.TdTc= Ins.TdTc               
     and Td.TdYy= Ins.TdYy and Td.TdChr= Ins.TdChr and Td.TdNo= Ins.TdNo               
     and Td.TdSrNo= 0               
     and Td.TdSr<= IsNull((Select max(Mx.TdSr) from Txnd Mx               
     where Mx.TdCoCd= Ins.TdCoCd and Mx.TdTc= Ins.TdTc and Mx.TdYy= Ins.TdYy               
     and Mx.TdChr= Ins.TdChr and Mx.TdNo= Ins.TdNo and Mx.TdSr< ins.TdSr               
     and Mx.TdSrNo= 0 and Mx.TdBDc= 'D'), 0)               
    ), 0)<> 0               
              
   If @Row > 0              
  begin              
    Select @ErrMsg= 'Complete The Matching Of Previous Parent-Child Records Before Starting Another Set'              
    GoTo ErrHndlr              
   end              
   (Bef 18/09/2006) ***/              
              
    /*** 18/09/06 ***/              
    /****** If Pvalue(TdTc)= 'BM' (Bag Merge) and TdSrNo= 0, in same Vchr               
     Multiple Issue/Receipt sets allowed. A new set is allowed only               
     if the Rm Wt/Qty of earlier sets are completely matched ********/              
    /* Current Partition */              
    select @Row= Count('x') from inserted ins               
     where ins.TdPrtKey=@wCurrPrtn and ins.TdSrNo= 0 and ins.TdBDc= 'C'               
      and exists (Select 'x' from Txnd Bc               
      join Txnd Tc on Tc.TdPrtKey=Bc.TdPrtKey and Tc.TdTIdNo=Bc.TdTIdNo              
       and Tc.TdCoCd= Bc.TdCoCd and Tc.TdTc= Bc.TdTc and Tc.TdYy= Bc.TdYy               
       and Tc.TdChr= Bc.TdChr and Tc.TdNo= Bc.TdNo and Tc.TdSr= Bc.TdSr               
       and Tc.TdSrNo> 0               
      where ins.TdPrtKey=Bc.TdPrtKey and ins.TdTIdNo=Bc.TdTIdNo              
       and ins.TdCoCd= Bc.TdCoCd and ins.TdTc= Bc.TdTc and ins.TdYy= Bc.TdYy               
       and ins.TdChr= Bc.TdChr and ins.TdNo= Bc.TdNo and Bc.TdSrNo= 0               
       and Bc.TdRefKey< ins.TdRefKey               
      group By Bc.TdRefKey, Tc.TdRmCd, convert (decimal (12, 4), Tc.TdRmSz),               
       convert (decimal (12, 2), Tc.TdRmStkRt), Tc.TdLotNo               
      having convert (decimal (16, 3), sum(case               
        when Tc.TdFrRmLoc= 'W' and Tc.TdFrRmDc= 'C' then -Tc.TdRmWt               
        when Tc.TdFrRmLoc= 'W' and Tc.TdFrRmDc= 'D' then Tc.TdRmWt               
        when Tc.TdToRmLoc= 'W' and Tc.TdToRmDc= 'C' then -Tc.TdRmWt               
        when Tc.TdToRmLoc= 'W' and Tc.TdToRmDc= 'D' then Tc.TdRmWt               
        else 0 end)) <> convert (decimal (16, 3), 0)               
       or               
       sum(case when Tc.TdFrRmLoc= 'W' and Tc.TdFrRmDc= 'C' then -Tc.TdRmQty               
        when Tc.TdFrRmLoc= 'W' and Tc.TdFrRmDc= 'D' then Tc.TdRmQty               
        when Tc.TdToRmLoc= 'W' and Tc.TdToRmDc= 'C' then -Tc.TdRmQty               
        when Tc.TdToRmLoc= 'W' and Tc.TdToRmDc= 'D' then Tc.TdRmQty               
        else 0 end) <> 0               
      )               
    If @Row > 0              
       begin              
     Select @ErrMsg= 'Complete The RM Matching Of Previous Parent-Child Records Before Starting Another Set'              
     GoTo ErrHndlr              
    end               
    /*** 18/09/06 ***/              
   end              
              
              
   /******** If Pvalue(TdTc)= 'BM' and TdSrNo= 0 Then RefYy= '' *********/              
   /* Current Partition */              
   select @Row= Count('x') from inserted where TdPRtKEy=@wCurrPrtn and TdSrNo= 0 and TdRefYy<> ''               
       If @Row > 0              
        begin              
    Select @ErrMsg= 'RefYy Should Be Blank'              
      GoTo ErrHndlr              
     end              
              
   /******** If Pvalue(TdTc)= 'BM' and TdSrNo= 0 Then RefKey<> 0 *********/              
   /* Current Partition */              
   select @Row= Count('x') from inserted where TdPrtKey=@wCurrPrtn and TdSrNo= 0 and TdRefKey= 0               
       If @Row > 0              
        begin              
    Select @ErrMsg= 'RefKey Cannot Be Blank'              
      GoTo ErrHndlr              
     end              
              
   If @Mode = 'C'               
   Begin              
    /*** Cannot change RefKey ***/              
    /* Current Partition */              
    select @Row=Count('x') from Deleted Del where Del.TdPrtKey=@wCurrPrtn and              
      Not Exists (Select 'x' from Inserted Ins where INs.TdPrtKey=Del.TdPrtKey               
       and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd= Del.TdCoCd               
       and Ins.TdTc= Del.TdTc and Ins.Tdyy= Del.TdYy               
       and Ins.TdChr= Del.TdChr and Ins.TdNo= Del.TdNo               
       and Ins.TdSr= Del.TdSr and Ins.TdSrNo= Del.TdSrNo               
       and Ins.TdRefKey= Del.TdRefKey)           
    If @Row > 0              
    begin              
     Select @ErrMsg='Cannot Change Ref Key'              
     GoTo ErrHndlr              
    end              
   End              
              
   /****** If Pvalue(TdTc)= 'BM' and TdSrNo= 0, Debit Cannot Be More Than Credit ********/              
   /*** 18/09/06 sum for 'D' and max for 'C' as total BQty of 'C' bags for all Bag Chr's put               
    together should match total of each Bag Chr of 'D' Bags               
  ***/              
   /* Current Partition */              
   select @Row= Count('x') from               
     (Select sum(case when Tc.TdBDc= 'C' then Tc.TdBQty else 0 end) as qCrQty,               
      sum(case when Tc.TdBDc= 'D' then Tc.TdBQty else 0 end) as qDrQty               
     from Txnd Tc where Tc.TdPrtKey=@wCurrPrtn and exists(Select 'x' from inserted ins               
      where ins.TdBDc= 'D' and ins.TdSrNo= 0               
       and ins.TdPrtKey=Tc.TdPrtKey and ins.TdTIdNo=Tc.TdTIdNo              
       and ins.TdCoCd= Tc.TdCoCd and ins.TdTc= Tc.TdTc               
       and ins.TdYy= Tc.TdYy and ins.TdChr= Tc.TdChr               
       and ins.TdNo= Tc.TdNo and ins.TdRefKey= Tc.TdRefKey)         
      and Tc.TdSrNo= 0               
     group By Tc.TdBChr) Tbl               
     having convert( decimal (16, 1), sum(qDrQty))> convert( decimal (16, 1), max(qCrQty))               
   /*** 18/09/06 ***/              
              
   /*** (Bef 18/09/06) (This works only when single Bag Chr is allowed for 'D' Bags)               
   select @Row= Count('x') from inserted Ins where               
    TdSrNo= 0 and               
    (Select sum(Td.TdBQty* (case when Td.TdBDc= 'C' then -1 when Td.TdBDc= 'D' then 1 else 0 end))               
     from Txnd Td where Td.TdCoCd= Ins.TdCoCd and Td.TdTc= Ins.TdTc               
     and Td.TdYy= Ins.TdYy and Td.TdChr= Ins.TdChr and Td.TdNo= Ins.TdNo               
     and Td.TdSrNo= 0 and Td.TdRefKey= Ins.TdRefKey )> 0               
   (Bef 18/09/06) ***/              
   If @Row > 0               
      begin              
    Select @ErrMsg= 'Receipt Quantity Cannot Be More Than Issue'              
    GoTo ErrHndlr              
   end              
              
   /****** TdRefKey of subsequent TdSr should be >= previous ones ********/              
   /* Current Partition */              
   select @Row= Count('x') from inserted Ins where TdPrtKEy=@wCurrPrtn and              
    TdSrNo= 0 and exists               
    (Select 'x' from Txnd Td where Td.TdPrtKEy=Ins.TdPrtKey and Td.TdTIdNo=Ins.TdTIdNo              
     and Td.TdCoCd= Ins.TdCoCd and Td.TdTc= Ins.TdTc               
     and Td.TdYy= Ins.TdYy and Td.TdChr= Ins.TdChr and Td.TdNo= Ins.TdNo               
     and Td.TdSrNo= 0 and Td.TdSr< Ins.TdSr and Td.TdRefKey> Ins.TdRefKey)               
   If @Row > 0               
      begin              
    Select @ErrMsg= 'RefKey Should Be >= That Of Previous Sr'              
    GoTo ErrHndlr              
   end              
              
   /*** (Bef 2.14 Next) ***              
   ****** If Pvalue(TdTc) = 'BM', TdSrNo= 0 then the BOdDmCd shld be the same as that of               
    the issuing bag *******               
   select @Row= Count('x') from inserted Ins               
    Join Txnd Td On Td.TdCoCd= Ins.TdCoCd and               
     Td.TdTc= Ins.TdTc and Td.TdYy= Ins.TdYy and Td.TdChr= Ins.TdChr and               
     Td.TdNo= Ins.TdNo and Td.TdSrNo= 0 and Td.TdRefKey= Ins.TdRefKey               
    where Ins.TdSrNo= 0 and               
     (select BOdDmCd from Bag where BCoCd= Td.TdCoCd and               
      BYy= Td.TdBYy and BChr= Td.TdBChr and BNo= Td.TdBNo)<>               
     (select BOdDmCd from Bag where BCoCd= Ins.TdCoCd and               
      Byy= Ins.TdBYy and BChr= Ins.TdBChr and BNo= Ins.TdBNo)               
        If @Row> 0              
        Begin              
    Select @ErrMsg= 'Design Code Not Same As That Of Previous Bag'              
      GoTo ErrHndlr              
        end              
   *** (Bef 2.14 Next) ***/              
              
              
   /*** (Jen 2.14 Next) ***/              
   /****** If Pvalue(TdTc) = 'BM', TdSrNo= 0 then all the issuing & Receiving Bags of one group               
    (having same TdRefKey) shld belong to the same Order Serial *******/              
   /* Current Partition */              
   select @Row= Count('x') from inserted Ins               
    Join Txnd Td On Td.TdPrtKey=Ins.TdPrtKey and Td.TdTIdNo=Ins.TdTIdNo              
     and Td.TdCoCd= Ins.TdCoCd and Td.TdTc= Ins.TdTc and Td.TdYy= Ins.TdYy and Td.TdChr= Ins.TdChr and               
     Td.TdNo= Ins.TdNo and Td.TdSrNo= 0 and Td.TdRefKey= Ins.TdRefKey               
    where Ins.TdSrNo= 0 and               
     not exists (select 'x' from Bag B1               
      join Bag B2 on B1.BPrtKey=B2.BPrtKey and B1.BOdIdNo=B2.BOdIdNo              
       and B1.BCoCd= B2.BCoCd and B1.BOdTc= B2.BOdTc               
       and B1.BOdYy= B2.BOdYy and B1.BOdChr= B2.BOdChr               
       and B1.BOdNo= B2.BOdNo and B1.BOdSr= B2.BOdSr               
      where B1.BPrtKey=Td.TdPrtKey and B1.BIdNo=Td.TdBIdNo and B1.BCoCd= Td.TdCoCd               
       and B1.BYy= Td.TdBYy and B1.BChr= Td.TdBChr and B1.BNo= Td.TdBNo               
       and B2.BCoCd= Ins.TdCoCd and B2.BYy= Ins.TdBYy               
       and B2.BChr= Ins.TdBChr and B2.BNo= Ins.TdBNo)               
        If @Row> 0               
        Begin              
    Select @ErrMsg= 'Order Design Serial Not Same As That Of Previous Bag'               
      GoTo ErrHndlr               
        end              
   /*** (Jen 2.14 Next) ***/              
              
              
   /****** If PValue(TdTc) = 'BM', TdSrNo= 0 and TdBc= 'D'              
    Child OrdRm should have the same RM Content as in the parent Bag *******/              
    /* Current Partition */              
        select @Row= Count('x') from inserted Ins where Ins.TdPRtKey=@wCurrPrtn and              
    Exists (Select 'x' from Txnd Td               
      join Txnd TdRm on TdRm.TdPrtKey=Td.TdPrtKey               
       and TdRm.TdBIdNo=Td.TdBIdNo and TdRm.TdCoCd= Td.TdCoCd               
       and TdRm.TdBYy= Td.TdBYy and TdRm.TdBChr= Td.TdBChr               
       and TdRm.TdBNo= Td.TdBNo and TdRm.TdSrNo<> 0               
      where Td.TdSrNo= 0 and Td.TdBDc= 'C' and Td.TdPrtKey=Ins.TdPrtKey               
       and Td.TdTIdNo=Ins.TdTIdNo and Td.TdCoCd= Ins.TdCoCd and               
       Td.TdTc= Ins.TdTc and Td.TdYy= Ins.TdYy and               
       Td.TdChr= Ins.TdChr and Td.TdNo= Ins.TdNo and               
       Td.TdRefKey= Ins.TdRefKey and               
       TdRm.TdRmCd Not In(select OrRmCd from Bag               
        join OrdRm on BPrtKey=OrPRtKey and BOdIdNo=OrOdIdNo and BCoCd= OrCoCd and               
          BOdTc= OrTc and BOdYy= OrYy and BOdChr= OrChr               
         and BOdNo= OrNo and BOdSr= OrSr               
         where BPrtKey=Ins.TdPrtKey and BIdNo=Ins.TdBIdNo and BCoCd= Ins.TdCoCd               
          and BYy= Ins.TdBYy and BChr= Ins.TdBChr and BNo= Ins.TdBNo)               
         )               
          and Ins.TdSrNo= 0 and Ins.TdBDc= 'D'               
    If @Row> 0               
        Begin              
    Select @ErrMsg= 'RM Code Of Parent Not Same As Child'              
      GoTo ErrHndlr              
        end              
   /*** (Jen 2.13) ***/              
              
              
