    Exists (Select 'x' from Txnd Td where Td.TdCoCd= ins.TdCoCd and              
      Td.TdTc= ins.TdTc and Td.TdYy= ins.TdYy and Td.TdChr= ins.TdChr and              
      Td.TdNo= ins.TdNo and Td.TdSrNo= 0 and Td.TdBDc= 'C' and              
      Td.TdSr> ins.TdSr)              
    If @Row> 0              
        Begin              
    Select @ErrMsg= 'Cannot Have Another Receiving Bag Before Having An Issuing Bag In This Transaction'              
      GoTo ErrHndlr              
        end              
   (Bef 2.13) ***/              
              
              
   /* Qty of recv. bags cannot be changed while adding rec */              
    /* Current Partition */              
        select @errmsg= TdBQty from inserted where TdPrtKey=@wCurrPrtn and TdSrNo= 0 and TdBDc= 'D' and              
    Not Exists (Select 'x' from Bag where BPrtKey=TdPrtKey and BIdNo=TdBIdNo and BCoCd= TdCoCd and BYy= TdBYy and              
     BChr= TdBChr and BNo= TdBNo and              
    convert(decimal(16, 1), TdBQty)= convert(decimal(16, 1), BQty))              
    If @Row> 0              
        Begin              
    Select @ErrMsg= 'Cannot Change Quantity Of Receiving Bag'              
      GoTo ErrHndlr              
        end              
/* CHECK THIS LATER */              
   /* Part Qty cannot be changed while adding rec */              
/*        select @Row= Count('x') from inserted where TdSrNo= 0 and              
    Not Exists (select 'x' from Bag where BCoCd= TdCoCd and BYy= TdBYy and              
     BChr= TdBChr and BNo= TdBNo and BPtQty= TdPtQty)              
    If @Row> 0              
        Begin              
    Select @ErrMsg= 'Cannot Change Part Quantity'              
      GoTo ErrHndlr              
        end */              
              
/*   if @mode= 'C'              
   Begin              
*/    /* Qty of recv. bags cannot be changed while editing rec */              
/*         select @Row= Count('x') from inserted ins where ins.TdSrNo= 0 and ins.TdBDc= 'D' and              
     Not Exists (Select 'x' from deleted del where ins.TdCoCd= del.TdCoCd and             
      ins.TdTc= del.TdTc and ins.TdYy= del.TdYy and ins.TdChr= del.TdChr and              
      ins.TdNo= del.TdNo and ins.TdSr= del.TdSr and ins.TdBQty = del.TdBQty)              
     If @Row> 0              
         Begin              
     Select @ErrMsg= 'Cannot Change Quantity Of Primary Bag'              
       GoTo ErrHndlr              
         end              
*/    /* Part Qty cannot be changed while editing rec */              
/*         select @Row= Count('x') from inserted ins where ins.TdSrNo= 0 and              
     Not Exists (Select 'x' from deleted del where ins.TdCoCd= del.TdCoCd and              
      ins.TdTc= del.TdTc and ins.TdYy= del.TdYy and ins.TdChr= del.TdChr and              
      ins.TdNo= del.TdNo and ins.TdSr= del.TdSr and ins.TdPtQty = del.TdPtQty)              
     If @Row> 0              
         Begin              
     Select @ErrMsg= 'Cannot Change Part Quantity'              
       GoTo ErrHndlr              
         end              
   End              
*/              
/* **** Not required **** */              
   /* Issuing Qty shld be <= receiving Qty of all receiving bags */              
/*        select @Row= Count('x') from inserted Ins              
    Join Txnd Td On Td.TdCoCd= ins.TdCoCd and Td.TdTc= ins.TdTc and              
     Td.TdYy= ins.TdYy and Td.TdChr= ins.TdChr and Td.TdNo= ins.TdNo and              
     Td.TdSrNo= 0 and Td.TdBDc= (case when ins.TdBDc= 'D' then 'C'              
       when ins.TdBDc= 'C' then 'D' end)              
     and (case when ins.TdBDc= 'D' then ins.TdBQty              
       when ins.TdBDc= 'C' then Td.TdBQty end)<              
      (case when ins.TdBDc= 'D' then Td.TdBQty              
       when ins.TdBDc= 'C' then ins.TdBQty end)              
    where ins.TdSrNo= 0              
    If @Row> 0              
        Begin              
    Select @ErrMsg= 'Receiving Bag Quantity Cannot Be < Issuing Bag Quantity'              
      GoTo ErrHndlr              
        end              
*/              
/* **** Not required **** */              
              
   if @mode in ('D')              
   begin              
    /*** (Bef 2.13)              
    --****** Cannot Delete 'BM', TdDc='C', Tdsrno= 0              
     If exists TdBDc='D', TdSrno=0 in same voucher ********              
    select @Row=Count('x') from Deleted Del where              
     Exists (Select 'x' from Txnd  where              
      Txnd.TdCoCd= Del.TdCoCd and Txnd.TdTc= Del.TdTc and              
      Txnd.TdYy= Del.TdYy and Txnd.TdChr= Del.TdChr and              
 Txnd.TdNo= Del.TdNo and Txnd.TdBDc= 'D' and TdSrNo= 0              
             )              
           and TdBDc= 'C' and TdSrNo= 0              
    If @Row > 0              
     begin              
       Select @ErrMsg='Cannot Delete Parent, Child Exists'              
       GoTo ErrHndlr              
         end              
    (Bef 2.13) ***/              
              
              
    /*** (Jen 2.13) ***/              
    /****** Cannot Delete 'BM', TdDc= 'C', TdSrNo= 0               
    If exists TdBDc= 'D', TdSrNo= 0, with same TdRefKey in same voucher ********/               
    /* Current Partition */              
    select @Row= Count('x') from Deleted Del where Del.TdPrtKey=@wCurrPrtn and               
     Exists (Select 'x' from Txnd Td where Td.TdPrtKey=Del.TdPrtKey and              
      Td.TdTIdNo=Del.TdTIdNo and Td.TdCoCd= Del.TdCoCd and Td.TdTc= Del.TdTc and               
      Td.TdYy= Del.TdYy and Td.TdChr= Del.TdChr and               
      Td.TdNo= Del.TdNo and Td.TdBDc= 'D' and Td.TdSrNo= 0 and               
      Td.TdRefKey= Del.TdRefKey               
      /* and Td.TdSr> Del.TdSr */              
             )               
           and TdBDc= 'C' and TdSrNo= 0               
    If @Row > 0              
         begin              
       Select @ErrMsg= 'Cannot Delete Parent, Child Exists'              
       GoTo ErrHndlr              
         end              
    /*** (Jen 2.13) ***/              
              
   end              
              
  End              
              
              
/* **** Zubin 211 **** */ /* **** Zubin 211 **** */ /* **** Zubin 211 **** */ /* **** Zubin 211 **** */              
 END              
              
 /******* End of Checks only For @wEntTyp='TxnBag'  ***********/              
 /******************************************************************/              
              
              
              
              
 /***** performing fields Valids for wEntTyp='TxnRm' ********/              
 /********************************************************/              
              
 IF @wEntTyp='TxnRm'              
 BEGIN              
  /********* All Bag fields should be Blank *********/              
  /* Current Partition */             
Select @Row=Count('x') From Inserted Ins where Ins.TdPrtKey=@wCurrPrtn and               
   TdBYy<> '' or TdBChr<>'' or TdBNo<>0 or TdBDc <> ''              
        or TdFrBLoc <> '' or TdToBLoc <> '' or TdBGrWt <> 0              
        or TdBQty <> 0 or TdPtQty <> 0              
      If @Row>0              
  BEGIN              
   Select @ErrMsg='Bag related fields should be empty'              
   GoTo ErrHndlr              
  END              
              
/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */              
  /********** TdFrRmLoc Then Valid Loc, LocTyp<>'P' ************/              
  /* Current Partition */               
  Select @Row=Count('x') From Inserted Ins              
   Where Ins.TdPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and              
    LocTyp<> 'P' and LocCd = Ins.TdFrRmLoc And LocValidYN='Y')              
   /* AND TdFrRmDc = 'C' */              
      If @Row>0              
  BEGIN              
              
   Select @ErrMsg='Invalid From Rm Loc'              
     GoTo ErrHndlr              
  END              
              
/* **** Zubin 211 (Or Condition for 'TdFrRmDc' was missing) **** */              
  /********** TdFrRmLoc Then Valid Loc, LocTyp<>'P' ************/              
  /* Current Partition */              
  SELECT @Row= COUNT('x') FROM Inserted Ins WHERE TdPrtKey=@wCurrPrtn and              
   (Ins.TdFrRmLoc <> ISNULL((SELECT Del.TdFrRmLoc FROM Deleted Del              
    WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   OR              
   Ins.TdFrRmDc <> ISNULL((SELECT Del.TdFrRmDc FROM Deleted Del              
    WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   OR Ins.TdFrRmLoc ='')              
   AND NOT EXISTS (SELECT 'x' FROM Loc WHERE LocCoCd= Ins.TdCoCd AND              
    LocTyp<> 'P' AND LocCd = Ins.TdFrRmLoc AND LocValidYN = 'Y')              
   AND TdFrRmDc = 'D'              
/* **** Zubin 211 (Or Condition for 'TdFrRmDc' was missing) **** */              
      IF @Row>0              
  BEGIN              
              
   SELECT @ErrMsg='Invalid From Rm Loc'              
     GOTO ErrHndlr              
  END              
/*              
  Select @Row=Count('x') From Inserted Ins              
   Where Not Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and              
    LocTyp<> 'P' and LocCd = Ins.TdFrRmLoc)              
      If @Row>0              
  BEGIN              
              
   Select @ErrMsg='Invalid From Rm Loc'              
     GoTo ErrHndlr              
  END              
*/              
/*  #########################################  Manoj  #########################################  */              
              
  /********** TdFrRmDc  if 'TxnRm' then Valid 'Dc'*************/              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins              
   Where TdPrtKey=@wCurrPrtn and Not Exists (Select 'x' From Param where PTyp='DC'              
    and PMCd = Ins.TdFrRmDc and PScd='')               
    If @Row>0              
  BEGIN              
   Select @ErrMsg='Invalid From Rm DC'              
     GoTo ErrHndlr              
  END              
              
  /*********** TdRmCd if 'TxnRm' then Valid RmCd, RmZ='N' *********/              
  /* Current Partition */               
  Select @Row=Count('x') From Inserted Ins              
   Where TdPrtKey=@wCurrPrtn and Not Exists (Select 'x' From RmMst where RmCd=TdRmCd and RmPrtKey=TdPrtKey and RmZ='N')              
      If @Row>0              
  BEGIN              
   Select @ErrMsg='Invalid Rm Code'              
     GoTo ErrHndlr              
  END              
              
/*  ####################  Manoj # Ver: 2.0.11 Patch 01 # Date: 17/08/2005  ####################  */              
  If @wTcTyp = 'PR'              
  Begin            
   /* Current Partition */              
   Select @Row=Count('x') From Inserted Ins              
    Join Loc On LocTyp = 'XP' And LocCoCd = Ins.TdCoCd              
    And LocCd = (Case When Ins.TdFrRmDc = 'C' Then Ins.TdFrRmLoc              
      When Ins.TdFrRmDc = 'D' Then Ins.TdToRmLoc End)              
   Where TdPrtKey=@wCurrPrtn and (Ins.TdRmCd <> ISNULL((SELECT Del.TdRmCd FROM Deleted Del              
    WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   OR              
   Ins.TdFrRmDc <> ISNULL((SELECT Del.TdFrRmDc FROM Deleted Del              
    WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')      
   OR              
   (Case When Ins.TdFrRmDc = 'C' Then Ins.TdFrRmLoc When Ins.TdFrRmDc = 'D' Then Ins.TdToRmLoc End)              
    <> ISNULL((SELECT Del.TdFrRmDc FROM Deleted Del WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo               
    and Ins.TdCoCd = Del.TdCoCd And              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), ''))              
   And Not Exists (Select 'x' From RmMst where RmCd=TdRmCd and RmZ='N' And RmValidYN = 'Y')              
       If @Row>0              
   BEGIN              
    Select @ErrMsg='Rm Code Not Defined / InValid'              
      GoTo ErrHndlr              
   END              
  End              
/*  #########################################  Manoj  #########################################  */              
              
/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */               
  /* Current Partition */              
Select @Row=Count('x') From Inserted Ins              
   Where TdPrtKey=@wCurrPrtn and (Not Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and              
    LocTyp<> 'P' and LocCd = Ins.TdToRmLoc And LocValidYn='Y'              
    and (@wTcTyp Not In('Rec','Cnv','Bs') Or LocTyp= 'Xc')))              
    /* AND TdToRmDc = 'C'*/              
      If @Row>0              
  BEGIN              
   Select @ErrMsg='Invalid To Rm Loc'              
     GoTo ErrHndlr              
  END              
/* **** Zubin 211 (Or Condition for 'TdToRmLoc' was missing) **** */              
  /****** TdToRmLoc If 'TxnRm' Then Valid Loc, LocTyp<>'P' Else ''              
   If 'Rec', 'Cnv', 'Bs' Then LocTyp='Xc' ********/              
  /* Current Partition */              
  SELECT @Row= COUNT('x') FROM Inserted Ins WHERE Ins.TdPrtKey=@wCurrPrtn and              
   ((              
   (Ins.TdToRmLoc <> ISNULL((SELECT Del.TdToRmLoc FROM Deleted Del              
    WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   OR              
   Ins.TdToRmDc <> ISNULL((SELECT Del.TdToRmDc FROM Deleted Del              
    WHERE Ins.TdPrtKey=Del.TdPrtKey and Ins.TdIdNo=Del.TdIdNo and Ins.TdCoCd = Del.TdCoCd AND              
    Ins.TdTc = Del.TdTc AND Ins.TdYy = Del.TdYy AND Ins.TdChr = Del.TdChr AND              
    Ins.TdNo = Del.TdNo AND Ins.TdSr = Del.TdSr AND Ins.TdSrNo = Del.TdSrNo), '')              
   )              
   AND (NOT EXISTS (SELECT 'x' FROM Loc WHERE LocCoCd= Ins.TdCoCd AND              
    LocTyp<> 'P' AND LocCd = Ins.TdToRmLoc AND LocValidYN = 'Y'              
    AND (@wTcTyp NOT IN('Rec','Cnv','Bs') OR LocTyp= 'Xc'))))              
   Or Ins.TdToRmLoc = '')              
   AND TdToRmDc = 'D'              
/* **** Zubin 211 (Or Condition for 'TdToRmLoc' was missing) **** */              
      IF @Row>0              
  BEGIN              
   SELECT @ErrMsg='Invalid To Rm Loc'              
     GOTO ErrHndlr              
  END              
/*              
  Select @Row=Count('x') From Inserted Ins              
   Where (Not Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and              
    LocTyp<> 'P' and LocCd = Ins.TdToRmLoc              
    and (@wTcTyp Not In('Rec','Cnv','Bs') Or LocTyp= 'Xc')))              
      If @Row>0              
  BEGIN              
   Select @ErrMsg='Invalid To Rm Loc'              
     GoTo ErrHndlr              
  END              
*/              
/*  #########################################  Manoj  #########################################  */              
              
  /* Current Partition */              
  select @row= count('x') from inserted Ins where Ins.TdPrtKey=@wCurrPrtn and /*TdSrNo<>0 and */              
    Ins.TdFrRmLoc = Ins.TdToRmLoc and (Ins.TdFrRmLoc <> '' or              
    Ins.TdToRmLoc <> '')              
    if @row>0                begin              
      select @errmsg= 'To Rm Loc and From Rm Loc cannot be same'              
      goto ErrHndlr              
    end              
              
  /****** if 'TxnRm' then TdFrRmLoc or TdToRmLoc should not be of LocTyp= 'W' **********/              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins              
   Where TdPrtKey=@wCurrPrtn and Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and              
     LocTyp= 'W' and LocCd = Ins.TdFrRmLoc)              
           or Exists (Select 'x' From Loc where LocCoCd= Ins.TdCoCd and LocTyp= 'W' and LocCd = Ins.TdToRmLoc)              
    If @Row>0              
  begin              
   Select @ErrMsg= 'From Or To Rm Loc Should Not Be ''W'' '              
   GoTo ErrHndlr              
  end              
              
  /******* All Rj, Sp, Prd related fields If @wEntTyp='TxnRm' then '' *********/    
--Prev              
/*              
  Select @Row= Count('x') From Inserted Ins where              
   TdRjDc<> '' or TdRjQty<>0 or TdRjPtQty<> 0 or TdRjCd<> ''              
        or TdWrk<> '' or TdAck<>'' or TdPrdYN<> '' or TdByLoc<> ''              
   or TdByWrk<> '' or TdDustWt<> 0              
      If @Row> 0              
  begin              
   Select @ErrMsg= 'Rej, Prd Related Fields Should Be Empty'              
     GoTo ErrHndlr              
  end */              
  /* Current Partition */              
  Select @Row= Count('x') From Inserted Ins where Ins.TdPrtKey=@wCurrPrtn and              
   TdRjDc<> '' or TdRjQty<>0 or TdRjPtQty<> 0 or TdRjCd<> ''              
        or TdWrk<> '' or TdAck<>'' or TdPrdYN<> '' or TdByLoc<> ''              
   or TdByWrk<> ''              
      If @Row> 0              
  begin              
   Select @ErrMsg= 'Rej, Prd Related Fields Should Be Empty'              
     GoTo ErrHndlr              
  end /* Zubin 212 */              
              
  if (@wTcTyp= 'PR' and @wTc<> 'PR') Or (@wTcTyp<> 'PR' and @wTcTyp<> 'MV')              
  Begin              
  if @wTc <>'DT'
  begin
   /* Current Partition */              
  /* Manali 3.6.0 - Company level check removed (DiaJewel )*/      
   Select @Row= Count('x') From Inserted Ins where Ins.TdPrtKey=@wCurrPrtn and TdLotNo<> '' and              
    Exists (Select 'x' from Head where HCd= @wHCd and HCoCd= TdCoCd and HLotNoYN= 'Y') and             
 /*Not ((Select PValue from Param where PTyp='MWOPT' and PMCd='MULCOTRF' and PSCd='')='Y' and @wTcTyp= 'DT') and */             
    Not Exists (Select 'x' from SYyMm where SPrtKey=TdPrtKey /*and SCoCd= TdCoCd */ and SLotNo= TdLotNo)              
       If @Row> 0              
   begin              
    Select @ErrMsg= 'Invalid Lot No./Lot No. Does Not Exist'              
      GoTo ErrHndlr              
   end   End              
   end
/* Zubin 212 */           
      
 /***** Manali 3.8.0 - TdRtByQW *****/      
   select @Row= Count('x') from Inserted Ins where Ins.TdPrtKey=@wCurrPRtn and @wTc='PR'       
  and Not Exists(Select * from param Where Ptyp='LABQW' and PMCd=Ins.TdRtByQW)      
   If @Row> 0              
   begin              
    Select @ErrMsg= 'Invalid Rm Qw Option'              
    GoTo ErrHndlr              
   end              
        
   select @Row= Count('x') from Inserted Ins where Ins.TdPrtKey=@wCurrPRtn and @wTc='PR'       
  and Ins.TdRtByQW='Q' and TdRmCtg<>'X'      
   If @Row> 0              
   begin              
    Select @ErrMsg= '''Q'' Allowed in Rate By QW Option Only For Accessories'              
    GoTo ErrHndlr              
   end              
         
 END              
              
              
              
 /***** End of performing fields Valids for wEntTyp='TxnRm' ********/              
 /***************************************************************/              
              
              
              
            
 /*** UPDATES ***/              
              
              
 /*** Update SYyMm from TdFrRmLoc ***/              
/* Zubin 212 (Lot No included in all SYyMm Inserts and Updates) */              
 if @mode in ('C','D')              
 begin              
  /* Current Partition */      
              
  update SYyMm set              
  SRmCrQty= SRmCrQty- (select isnull(sum(Del.TdRmQty), 0) from Deleted Del              
     where Del.TdFrRmDc='C' and Del.TdPrtKey=SPrtKey and Del.TdCoCd= SCoCd and Del.TdRmCd= SRmCd              
   and Del.TdLotNo= SLotNo and Del.TDRmSz=SRmSz and Del.TdRmStkRt=SRmStkRt and Del.TdFrRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))= SYyMm),              
  SRmCrWt= SRmCrWt-(select isnull(sum(Del.TdRmWt),0) from Deleted Del              
   where Del.TdFrRmDc='C' and Del.TdPrtKey=SPrtKey and Del.TdCoCd= SCoCd and Del.TdRmCd= SRmCd              
     and Del.TdLotNo= SLotNo and Del.TDRmSz= SRmSz and Del.TdRmStkRt= SRmStkRt and Del.TdFrRmLoc=SLoc              
     and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmDrQty= SRmDrQty-(select isnull(sum(Del.TdRmQty),0) from Deleted Del              
    where Del.TdFrRmDc='D' and Del.TdPrtKEy=SPrtKey and Del.TdCoCd= SCoCd and Del.TdRmCd=SRmCd              
      and Del.TdLotNo= SLotNo and Del.TDRmSz=SRmSz and Del.TdRmStkRt=SRmStkRt and Del.TdFrRmLoc=SLoc              
      and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmDrWt= SRmDrWt-(select isnull(sum(Del.TdRmWt),0) from Deleted Del              
      where Del.TdFrRmDc='D' and Del.TdPrtKey=SPrtKey and Del.TdCoCd= SCoCd and Del.TdRmCd=SRmCd              
      and Del.TdLotNo= SLotNo and Del.TDRmSz=SRmSz and Del.TdRmStkRt=SRmStkRt and Del.TdFrRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm)              
  from Deleted       
   where Deleted.TdPrtKey=SPrtKey and Deleted.TdCoCd= SCoCd and Deleted.TdRmCd= SRmCd and Deleted.TdLotNo= SLotNo              
   and Deleted.TDRmSz= SRmSz and Deleted.TdRmStkRt= SRmStkRt and Deleted.TdFrRmLoc= SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm              
   and (Deleted.TdFrRmDc='D'  or Deleted.TdFrRmDc='C') and      
   ((@Mode='C' and Exists(Select 'x' From Inserted ins where ins.TdCoCd =Deleted.TdCoCd and ins.TdTc=Deleted.TdTc and ins.TdYy=Deleted.TdYy and      
         ins.TdChr=Deleted.TdChr and ins.TdNo=Deleted.TdNo and ins.TdSr=Deleted.TdSr and ins.TdSrNo=Deleted.TdSrNo and          
      (ins.TdPrtKey<>Deleted.TdPrtKey Or  ins.TdCoCd<>Deleted.TdCoCd Or ins.TdRmCd<>Deleted.TdRmCd Or ins.TdLotNo<>Deleted.TdLotNo      
        Or  ins.TDRmSz<>Deleted.TDRmSz or  ins.TdRmStkRt<>Deleted.TdRmStkRt Or ins.TdFrRmLoc<>Deleted.TdFrRmLoc Or       
         Ins.TdRmWt<>Deleted.TdRmWt Or Ins.TdRmQty<>Deleted.TdRmQty Or  Ins.TdFrRmDC<>Deleted.TdFrRmDC Or    
         convert(int,convert(varchar(6),ins.TdDt,112))<>convert(int,convert(varchar(6),Deleted.TdDt,112))))) Or @Mode='D')      
      
       
 end              
      
       
              
              
 if @mode in ('A','C')              
 begin              
  /* Current Partition */              
  insert into SYyMm(SPrtKey,SCoCd,SRmCd,SLotNo,SRmSz,SRmStkRt,SLoc,SYyMm,SRmDrqty,SRmDrWt,SRmCrQty,SRmCrWt)              
   select distinct TdPrtKey, TdCoCd, TdRmCd,TdLotNo,TdRmSz,TdRmStkRt,TdFrRmLoc,convert(int,convert(varchar(6),TdDt,112)),0,0,0,0              
   from inserted       
   where not exists(select 'x' from  SYyMm where SPrtKey=TdPrtKey and SCoCd= TdCoCd and SRmCd=TdRmCd and SLotNo= TdLotNo              
   and SRmSZ=TdRmSz and SRmStkRt=TdRmStkRt and SLoc=TdFrRmLoc and              
   SYyMm= convert(int,convert(varchar(6),TdDt,112))) and              
   ((@wEntTyp= 'TxnBag' and TdSrNo<> 0) or (@wEntTyp= 'TxnRm' and TdSrNo= 0))              
              
  /* Current Partition */               
  update SYyMm set              
  SRmCrQty=SRmCrQty+(select isnull(sum(Ins.TdRmQty),0) from Inserted Ins       
   where Ins.TdFrRmDc='C' and Ins.TdPrtKey=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd=SRmCd and Ins.TdLotNo=SLotNo              
   and Ins.TDRmSz=SRmSz and Ins.TdRmStkRt=SRmStkRt and Ins.TdFrRmLoc=SLoc              
  and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmCrWt=SRmCrWt+(select isnull(sum(Ins.TdRmWt),0) from Inserted Ins       
   where Ins.TdFrRmDc='C' and Ins.TdPrtKey=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd=SRmCd and Ins.TdLotNo=SLotNo              
   and Ins.TDRmSz=SRmSz and Ins.TdRmStkRt=SRmStkRt and Ins.TdFrRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmDrQty=SRmDrQty+(select isnull(sum(Ins.TdRmQty),0) from Inserted Ins       
   where Ins.TdFrRmDc='D'  and Ins.TdPrtKey=SPrtKEy and Ins.TdCoCd= SCoCd and Ins.TdRmCd=SRmCd and Ins.TdLotNo=SLotNo              
   and Ins.TDRmSz=SRmSz and Ins.TdRmStkRt=SRmStkRt and Ins.TdFrRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmDrWt=SRmDrWt+(select isnull(sum(Ins.TdRmWt),0) from Inserted Ins       
   where Ins.TdFrRmDc='D'  and Ins.TdPRtKey=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd=SRmCd and Ins.TdLotNo=SLotNo              
   and Ins.TDRmSz=SRmSz and Ins.TdRmStkRt=SRmStkRt and Ins.TdFrRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm)              
  from Inserted       
   where Inserted.TdPrtKey=SPrtKey and Inserted.TdCoCd= SCoCd and Inserted.TdRmCd= SRmCd and Inserted.TdLotNo=SLotNo              
   and Inserted.TDRmSz= SRmSz and Inserted.TdRmStkRt= SRmStkRt              
   and Inserted.TdFrRmLoc= SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm              
   and (Inserted.TdFrRmDc='D' or Inserted.TdFrRmDc='C')  and      
   ((@Mode='C' and Exists(Select 'x' From Deleted Del where Inserted.TdCoCd =Del.TdCoCd and Inserted.TdTc=Del.TdTc and Inserted.TdYy=Del.TdYy and      
         Inserted.TdChr=Del.TdChr and Inserted.TdNo=Del.TdNo and Inserted.TdSr=Del.TdSr and Inserted.TdSrNo=Del.TdSrNo and          
      (Inserted.TdPrtKey<>Del.TdPrtKey Or  Inserted.TdCoCd<>Del.TdCoCd Or Inserted.TdRmCd<>Del.TdRmCd Or Inserted.TdLotNo<>Del.TdLotNo      
        Or  Inserted.TDRmSz<>Del.TDRmSz or  Inserted.TdRmStkRt<>Del.TdRmStkRt Or Inserted.TdFrRmLoc<>Del.TdFrRmLoc Or       
        Inserted.TdRmWt<>Del.TdRmWt Or Inserted.TdRmQty<>Del.TdRmQty Or Inserted.TdFrRmDC<>Del.TdFrRmDC Or      
         convert(int,convert(varchar(6),Inserted.TdDt,112))<>convert(int,convert(varchar(6),Del.TdDt,112))))) Or @Mode='A')             
 end              
              
