   and Del.TDRmSz=SRmSz and Del.TdRmStkRt=SRmStkRt and Del.TdToRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmDrWt=SRmDrWt-(select isnull(sum(Del.TdRmWt),0) from Deleted Del       
   where Del.TdToRmDc='D' and Del.TdPrtKey=SPrtKey and Del.TdCoCd= SCoCd and Del.TdRmCd=SRmCd and Del.TdLotNo=SLotNo              
   and Del.TDRmSz=SRmSz and Del.TdRmStkRt=SRmStkRt and Del.TdToRmLoc=SLoc              
