   where Ins.TdToRmDc='D' and Ins.TdPrtKey=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd=SRmCd and Ins.TdLotNo=SLotNo              
   and Ins.TDRmSz=SRmSz and Ins.TdRmStkRt=SRmStkRt and Ins.TdToRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm),              
  SRmDrWt=SRmDrWt+(select isnull(sum(Ins.TdRmWt),0) from Inserted Ins       
   where Ins.TdToRmDc='D' and Ins.TdPrtKEy=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd=SRmCd and Ins.TdLotNo=SLotNo              
   and Ins.TDRmSz=SRmSz and Ins.TdRmStkRt=SRmStkRt and Ins.TdToRmLoc=SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm)              
  from Inserted       
   where Inserted.TdPrtKey=SPrtKey and Inserted.TdCoCd= SCoCd and Inserted.TdRmCd=SRmCd and Inserted.TdLotNo=SLotNo              
   and Inserted.TDRmSz=SRmSz and Inserted.TdRmStkRt=SRmStkRt and Inserted.TdToRmLoc= SLoc              
   and convert(int,convert(varchar(6),TdDt,112))=SYyMm              
   and (Inserted.TdToRmDc='D' or Inserted.TdToRmDc='C')  and      
 ((@Mode='C' and Exists(Select 'x' From Deleted Del where Inserted.TdCoCd =Del.TdCoCd and Inserted.TdTc=Del.TdTc and Inserted.TdYy=Del.TdYy and      
         Inserted.TdChr=Del.TdChr and Inserted.TdNo=Del.TdNo and Inserted.TdSr=Del.TdSr and Inserted.TdSrNo=Del.TdSrNo and          
      (Inserted.TdPrtKey<>Del.TdPrtKey Or  Inserted.TdCoCd<>Del.TdCoCd Or Inserted.TdRmCd<>Del.TdRmCd Or Inserted.TdLotNo<>Del.TdLotNo      
        Or  Inserted.TDRmSz<>Del.TDRmSz or  Inserted.TdRmStkRt<>Del.TdRmStkRt Or Inserted.TdToRmLoc<>Del.TdToRmLoc Or       
          Inserted.TdRmWt<>Del.TdRmWt Or Inserted.TdRmQty<>Del.TdRmQty Or  Inserted.TdToRmDC<>Del.TdToRmDC Or    
         convert(int,convert(varchar(6),Inserted.TdDt,112))<>convert(int,convert(varchar(6),Del.TdDt,112))))) Or @Mode='A')                   
       
 end              
              
 /* urmi NegStk Start*/              
 IF @wEntTyp in ('TxnRm', 'TxnBag')              
 BEGIN              
 /* While adding or changing Chk for Issuing Location */              
      if @mode in ('A','C')              
/*  ####################  Manoj # Ver: 2.0.11 Patch 01 # Date: 17/08/2005  ####################  */              
      begin              
/*  Select @Row=Count('x') From Inserted Ins join Txn on TCoCd= Ins.TdCoCd and              
         TTc= Ins.TdTc and TYy= ins.TdYy and              
         TChr= Ins.TdChr and TNo= Ins.TdNo              
  Where Exists (Select 'X' From Head where HCoCd= Ins.TdCoCd and HCd= @wHCd and              
        HNegStkYn= 'N')              
  and Exists (Select 'X' from Param where PTyp= 'SEOPWD' and PMCD='SEOPWD'              
   and TSeoPwd<> PValue1)              
  and Exists (Select 'X' From Loc where LocCoCd= Ins.TdCoCd and LocTyp = 'S'              
   and LocCd = (case when Ins.TdFrRmDC = 'C' then Ins.TdFrRmLoc              
                         when Ins.TdFrRmDC = 'D' then Ins.TdToRmLoc              
          else '' end) )              
              
  and ( (Select CAST(SUM(SRmDrWt)-SUM(SRmCrWt) As Decimal(10,3)) from SYyMm              
--  and ( (Select SUM(SRmDrWt)-SUM(SRmCrWt) from SYyMm              
    where Ins.TdCoCd= SCoCd and Ins.TdRmCd= SRmCd and              
     Ins.TDRmSz= SRmSz and              
     (case when Ins.TdFrRmDC = 'C' then Ins.TdFrRmLoc              
     when Ins.TdFrRmDC = 'D' then Ins.TdToRmLoc              
     else '' end )= SLoc              
       )--- Ins.TdRmWt              
      ) < 0              
*/              
  /* Checking When AvgStkRt = 'Y' Or Stock By StkRt = 'N' */              
/* Zubin 212 (LotNo added) */              
  if @wTc = 'DT'
  begin 
  /* Zubin 212 */              
  /* Lot No shld be valid from SYyMm for CoCd */              
  /* Current Partition */              
  /* Manali 3.6.0 - Company level check removed (DiaJewel )*/      
  Select @Row= Count('x') From Inserted Ins where TdPrtKey=@wCurrPrtn and TdLotNo<> '' and              
   Not(TdFrRmDc= 'C' and TdFrRmLoc= 'W') and Not(TdFrRmDc= 'D' and TdToRmLoc= 'W') and              
   /*Not ((Select PValue from Param where PTyp='MWOPT' and PMCd='MULCOTRF' and PSCd='')='Y' and @wTcTyp= 'DT') and */            
   Not Exists (Select 'x' from SYyMm where SPrtKey=TdPrtKey /*and SCoCd= TdCoCd*/ and SLotNo= TdLotNo)              
  If @Row> 0              
  begin              
   Select @ErrMsg= 'Invalid Lot No./Lot No. Does Not Exist'              
     GoTo ErrHndlr              
  end              
  /* Zubin 212 */              
  end
  /* ****** Sachin 2.14.0 [RmMst Join added For RmCtg Check] ****** */              
  /* *** Jay 2.14 *** (SEO Change) *** [UsrAccess Check added] */              
  /* Current Partition */              
  Select @Row=Count('x')               
     From Inserted Ins               
      Join Txn on TPrtKey=Ins.TdPrtKey and TIdNo=Ins.TdTIdNo and TCoCd= Ins.TdCoCd and TTc= Ins.TdTc and TYy= ins.TdYy and              
        TChr= Ins.TdChr and TNo= Ins.TdNo               
      Join Head On HCoCd=TCoCd And HCd= @wHCd And HNegStkYn= 'N'              
      Join RmMst On RmPrtKey=Ins.TdPrtKey and RmCd=Ins.TdRmCd And               
        (Case When hNegStkRmCtg = '' Then ','+RmCtg+','               
        Else (Select ','+PDesc225+',' From Param               
            Where PTyp='GLDAS' And PMCd=hNegStkRmCtg) End) Like '%,'+RmCtg+',%'              
  Where Exists (Select 'X' From Head where HCoCd= Ins.TdCoCd and HCd= @wHCd and              
        HNegStkYn= 'N')              
  and not Exists (select 'x' from Param Join UsrAccess on UaUsrCd = PMCd where PTyp= 'USR' and               
    PMCd= Ins.ModUsr and UaMnuCd = Ins.TdTc and UaSeoYn= 'Y' and PValue= TSeoPwd)               
  and not Exists (Select 'x' from Param where PTyp= 'SEOPWD' and PMCD= 'SEOPWD' and TSeoPwd= PValue1)               
  and Exists (Select 'X' From Loc where LocCoCd= Ins.TdCoCd and LocTyp = 'S'              
   and LocCd = (case when Ins.TdFrRmDC = 'C' then Ins.TdFrRmLoc              
                         when Ins.TdFrRmDC = 'D' then Ins.TdToRmLoc              
          else '' end) )              
  and ((Select CAST(SUM(SRmDrWt)-SUM(SRmCrWt) As Decimal(10,3)) from SYyMm              
    where Ins.TdPrtKEy=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd= SRmCd and Ins.TdLotNo= SLotNo and              
     Ins.TDRmSz= SRmSz and              
     (case when Ins.TdFrRmDC = 'C' then Ins.TdFrRmLoc              
 when Ins.TdFrRmDC = 'D' then Ins.TdToRmLoc              
     else '' end )= SLoc              
       )/*- Ins.TdRmWt */              
      ) < 0              
  And (Exists (Select 'X' From Head where HCoCd= Ins.TdCoCd and HCd= @wHCd and              
       HAvgSRtYN = 'Y')              
       Or              
       Exists (Select 'X' from Param Join RmMst On PTyp = 'RMSCTG' AND RmPrtKey=Ins.TdPrtKey and RmCd = Ins.TdRmCd And              
   PMCD = RMCTG And PSCd = RMSCTG where PValue1 = 'N'))              
  If @Row> 0              
  begin              
   Select @ErrMsg= 'Only Authorized Users can enter Negative Stock For This Rm Ctg'              
     GoTo ErrHndlr              
       end              
              
  /* Checking When AvgStkRt = 'N' And Stock By StkRt = 'Y' */              
  /* Zubin 212 (LotNo added) */              
  /* *** Jay 2.14 *** (SEO Change) *** [UsrAccess Check added] */              
  /* Current Partition */              
  Select @Row=Count('x') From Inserted Ins               
    join Txn on TPrtKey=Ins.TdPrtKey and TIdNo=Ins.TdTIdNo and TCoCd= Ins.TdCoCd and              
       TTc= Ins.TdTc and TYy= ins.TdYy and TChr= Ins.TdChr and TNo= Ins.TdNo              
      Join Head On HCoCd=TCoCd And HCd= @wHCd And HNegStkYn= 'N'              
      Join RmMst On RmPrtKey=Ins.TdPrtKey and RmCd=Ins.TdRmCd And               
        (Case When hNegStkRmCtg = '' Then ','+RmCtg+','               
    Else (Select ','+PDesc225+',' From Param               
            Where PTyp='GLDAS' And PMCd=hNegStkRmCtg) End) Like '%,'+RmCtg+',%'              
  Where Exists (Select 'X' From Head where HCoCd= Ins.TdCoCd and HCd= @wHCd and              
        HNegStkYn= 'N')              
  and not Exists (select 'x' from Param Join UsrAccess Ua on Ua.UaUsrCd = PMCd where PTyp= 'USR' and               
    PMCd= ins.ModUsr and Ua.UaMnuCd = ins.TdTc and Ua.UaSeoYn= 'Y' and PValue= TSeoPwd)               
  and not Exists (Select 'x' from Param where PTyp= 'SEOPWD' and PMCD= 'SEOPWD' and TSeoPwd= PValue1)               
  and Exists (Select 'X' From Loc where LocCoCd= Ins.TdCoCd and LocTyp = 'S'              
   and LocCd = (case when Ins.TdFrRmDC = 'C' then Ins.TdFrRmLoc              
                         when Ins.TdFrRmDC = 'D' then Ins.TdToRmLoc              
          else '' end) )              
              
  and ( (Select CAST(SUM(SRmDrWt)-SUM(SRmCrWt) As Decimal(10,3)) from SYyMm              
    where Ins.TdPrtKey=SPrtKey and Ins.TdCoCd= SCoCd and Ins.TdRmCd= SRmCd and Ins.TdLotNo= SLotNo and              
     Ins.TDRmSz= SRmSz and Ins.TdRmStkRt =SRmStkRt and              
     (case when Ins.TdFrRmDC = 'C' then Ins.TdFrRmLoc              
        when Ins.TdFrRmDC = 'D' then Ins.TdToRmLoc              
      else '' end )= SLoc              
     )/*- Ins.TdRmWt */              
      ) < 0              
  And Exists (Select 'X' From Head where HCoCd= Ins.TdCoCd and HCd= @wHCd and              
       HAvgSRtYN = 'N')              
  And Exists (Select 'X' from Param Join RmMst On PTyp = 'RMSCTG' AND RmPrtKey=Ins.TdPrtKey and RmCd = Ins.TdRmCd And              
   PMCD = RMCTG And PSCd = RMSCTG where PValue1 = 'Y')              
  If @Row> 0              
  begin              
   Select @ErrMsg= 'Only Authorized Users can enter Negative Stock For This Rm Ctg'              
     GoTo ErrHndlr              
       end              
              
              
      end               
 /* While deleting Chk for Receiving Location */              
      if @mode in ('D')              
      begin              
/*  Select @Row=Count('x') From Deleted Del join Txn on TCoCd= Del.TdCoCd and              
         TTc= Del.TdTc and TYy= Del.TdYy and              
         TChr= Del.TdChr and TNo= Del.TdNo              
  Where Exists (Select 'X' From Head where HCoCd= Del.TdCoCd and HCd= @wHCd and              
        HNegStkYn= 'N')              
  and Exists (Select 'X' from Param where PTyp= 'SEOPWD' and PMCD='SEOPWD'              
   and TSeoPwd<> PValue1)              
  and Exists (Select 'X' From Loc where LocCoCd= Del.TdCoCd and LocTyp = 'S'              
   and LocCd = (case when Del.TdFrRmDC = 'D' then Del.TdFrRmLoc              
                          when Del.TdFrRmDC = 'C' then Del.TdToRmLoc              
 else '' end) )              
             
  and ( (Select CAST(SUM(SRmDrWt)-SUM(SRmCrWt) As Decimal(10,3)) from SYyMm              
--  and ( (Select SUM(SRmDrWt)-SUM(SRmCrWt) from SYyMm              
    where Del.TdCoCd= SCoCd and Del.TdRmCd= SRmCd and              
     Del.TDRmSz= SRmSz and              
     (case when Del.TdFrRmDC = 'D' then Del.TdFrRmLoc              
     when Del.TdFrRmDC = 'C' then Del.TdToRmLoc              
     else '' end )= SLoc              
       ) --- Del.TdRmWt              
      ) < 0              
              
  If @Row> 0              
  begin              
   Select @ErrMsg= 'Only Authorized Users can enter Negative Stock'              
     GoTo ErrHndlr              
  end              
*/              
  /* Checking When AvgStkRt = 'Y' Or Stock By StkRt = 'N' */              
/* Zubin 212 (LotNo added) */              
  /* *** Jay 2.14 *** (SEO Change) *** [UsrAccess Check added] */              
  /* Current Partition */              
  Select @Row=Count('x') From Deleted Del join Txn on TPrtKey=Del.TdPrtKEy               
       and TIdNo=Del.TdTIdNo and TCoCd= Del.TdCoCd and              
       TTc= Del.TdTc and TYy= Del.TdYy and              
       TChr= Del.TdChr and TNo= Del.TdNo              
      Join Head On HCoCd=TCoCd And HCd= @wHCd And HNegStkYn= 'N'              
      Join RmMst On RmPrtKEy=Del.TdPrtKey and RmCd=Del.TdRmCd And               
        (Case When hNegStkRmCtg = '' Then ','+RmCtg+','               
         Else (Select ','+PDesc225+',' From Param               
            Where PTyp='GLDAS' And PMCd=hNegStkRmCtg) End) Like '%,'+RmCtg+',%'              
  Where Exists (Select 'X' From Head where HCoCd= Del.TdCoCd and HCd= @wHCd and              
        HNegStkYn= 'N')              
  and not Exists (select 'x' from Param Join UsrAccess on UaUsrCd = PMCd where PTyp= 'USR' and               
    PMCd= Del.ModUsr and UaMnuCd = Del.TdTc and UaSeoYn= 'Y' and PValue= TSeoPwd)               
  and not Exists (Select 'x' from Param where PTyp= 'SEOPWD' and PMCD= 'SEOPWD' and TSeoPwd= PValue1)               
  and Exists (Select 'X' From Loc where LocCoCd= Del.TdCoCd and LocTyp = 'S'              
   and LocCd = (case when Del.TdFrRmDC = 'D' then Del.TdFrRmLoc              
                          when Del.TdFrRmDC = 'C' then Del.TdToRmLoc              
          else '' end) )              
  and ( (Select CAST(SUM(SRmDrWt)-SUM(SRmCrWt) As Decimal(10,3)) from SYyMm              
    where Del.TdPrtKey=SPrtKey and Del.TdCoCd= SCoCd and Del.TdRmCd= SRmCd and Del.TdLotNo= SLotNo and              
     Del.TDRmSz= SRmSz and              
     (case when Del.TdFrRmDC = 'D' then Del.TdFrRmLoc              
     when Del.TdFrRmDC = 'C' then Del.TdToRmLoc              
     else '' end )= SLoc              
       ) /*- Del.TdRmWt */              
      ) < 0              
  And (Exists (Select 'X' From Head where HCoCd= Del.TdCoCd and HCd= @wHCd and              
       HAvgSRtYN = 'Y')              
    Or              
       Exists (Select 'X' from Param Join RmMst On PTyp = 'RMSCTG' AND RmPrtKEy=Del.TdPrtKEy and RmCd = Del.TdRmCd And              
   PMCD = RMCTG And PSCd = RMSCTG where PValue1 = 'N'))              
  If @Row> 0              
  begin              
   Select @ErrMsg= 'Only Authorized Users can enter Negative Stock For This Rm Ctg'              
     GoTo ErrHndlr              
  end              
              
 /* Checking When AvgStkRt = 'Y' Or Stock By StkRt = 'N' */              
 /* Zubin 212 (LotNo added) */              
  /* *** Jay 2.14 *** (SEO Change) *** [UsrAccess Check added] */              
  /* Current Partition */              
  Select @Row=Count('x') From Deleted Del join Txn on TPrtKey=Del.TdPrtKey and TIdNo=Del.TdTIdNo              
       and TCoCd= Del.TdCoCd and TTc= Del.TdTc and TYy= Del.TdYy and              
       TChr= Del.TdChr and TNo= Del.TdNo              
      Join Head On HCoCd=TCoCd And HCd= @wHCd And HNegStkYn= 'N'              
      Join RmMst On RmPrtKEy=Del.TdPrtKey and RmCd=Del.TdRmCd And               
        (Case When hNegStkRmCtg = '' Then ','+RmCtg+','               
          Else (Select ','+PDesc225+',' From Param             
            Where PTyp='GLDAS' And PMCd=hNegStkRmCtg) End) Like '%,'+RmCtg+',%'              
  Where Exists (Select 'X' From Head where HCoCd= Del.TdCoCd and HCd= @wHCd and              
        HNegStkYn= 'N')              
  and not Exists (select 'x' from Param Join UsrAccess on UaUsrCd = PMCd where PTyp= 'USR' and               
    PMCd= Del.ModUsr and UaMnuCd = Del.TdTc and UaSeoYn= 'Y' and PValue= TSeoPwd)               
  and not Exists (Select 'x' from Param where PTyp= 'SEOPWD' and PMCD= 'SEOPWD' and TSeoPwd= PValue1)               
  and Exists (Select 'X' From Loc where LocCoCd= Del.TdCoCd and LocTyp = 'S'              
   and LocCd = (case when Del.TdFrRmDC = 'D' then Del.TdFrRmLoc              
                          when Del.TdFrRmDC = 'C' then Del.TdToRmLoc              
          else '' end) )              
              
  and ((Select CAST(SUM(SRmDrWt)-SUM(SRmCrWt) As Decimal(10,3)) from SYyMm              
    where Del.TdPrtKey=SPRtKey and Del.TdCoCd= SCoCd and Del.TdRmCd= SRmCd and Del.TdLotNo= SLotNo and              
     Del.TDRmSz = SRmSz and Del.TdRmStkRt = SRmStkRt and              
     (case when Del.TdFrRmDC = 'D' then Del.TdFrRmLoc              
     when Del.TdFrRmDC = 'C' then Del.TdToRmLoc              
     else '' end )= SLoc              
       ) /*- Del.TdRmWt */              
      ) < 0              
  And Exists (Select 'X' From Head where HCoCd= Del.TdCoCd and HCd= @wHCd and              
       HAvgSRtYN = 'N')              
  And Exists (Select 'X' from Param Join RmMst On PTyp = 'RMSCTG' AND RmPrtKey=Del.TdPrtKey and RmCd = Del.TdRmCd And              
       PMCD = RMCTG And PSCd = RMSCTG where PValue1 = 'Y')              
  If @Row> 0              
  begin              
   Select @ErrMsg= 'Only Authorized Users can enter Negative Stock For This Rm Ctg'              
     GoTo ErrHndlr              
  End              
      End  /*  #########################################  Manoj  #########################################  */              
 END              
 END              
 /**** urmi NegStk end ****/              
              
 If @wEntTyp = 'TxnBag' And @wTcTyp= 'BM'               
 Begin              
  If @Mode in ('A', 'C')              
  Begin              
   /****** (Jen 2.13 CT) changed the where clause for considering Component Bags ******/              
   /* ****** Sachin 2.13.0 - [28-06-2006] - Flute Bag Close On Merge  ****** */              
   /* This check has been put at end as there are certain checks which fail when bag is closed               
      and are placed above this update ***** */              
   /* Current Partition */              
   Update Bag               
    Set BCls = 'Y',              
                      BClsDt= (Select TDt From Txn Where TPrtKey=ins.TdPrtKey               
          and TIdNo=ins.TdTIdNo and TCoCd= ins.TdCoCd And TTc = ins.TdTc               
          And TYy = ins.TdYy And TChr= ins.TdChr And TNo= ins.TdNo)               
   From inserted ins              
   Where BPrtKey=ins.TdPrtKey and BIdNo=ins.TdBIdNo and BCoCd= ins.TdCoCd And BYy= ins.TdBYy And BChr= ins.TdBChr               
    And BNo= ins.TdBNo And ins.TdSrNo= 0               
    And Convert( Decimal (16, 1), BQty) = Convert( Decimal (16, 1), 0)               
    And Convert( Decimal (16, 3), BGrWt) = Convert( Decimal (16, 3), 0)               
    And BPtQty = 0               
    And (Select PValue From Param Where PTyp= 'BCHR' And PMCd= ins.TdBChr And PSCd= '') in ('C', 'F')               
    /*  (Bef 2.13 CT)              
      And (Select PValue From Param Where PTyp= 'BCHR' And PMCd= Del.TdBChr And PSCd= '' )= 'Y'              
         (Bef 2.13 CT) */              
   /* ****** Sachin 2.13.0 - [28-06-2006] - Flute Bag Close On Merge  ****** */               
  End              
 End                
Return              
ErrHndlr:              
 BEGIN              
  Select @ErrMsg='|'+@ErrMsg              
  RaisError(@ErrMsg,16,1)              
  Rollback Transaction              
 END 

GOGO
/****************** Ud27 ********************************************************************************************************/
ALTER TRIGGER [dbo].[BgRecoDet_INUPDL] ON [dbo].[BgRecoDet] 
       FOR INSERT,UPDATE,DELETE  NOT FOR REPLICATION
AS  
BEGIN  
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	DECLARE @ReplAgt BIT  

	IF @@ROWCOUNT=0   RETURN  
  
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'BgRecoDet' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	If  (@ReplAgt<>1)
	begin

		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
			select @ROW =Count('x')  From inserted where  
			Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ BdCoCd +',%') 
				or (SysId='CRM' and SysDb='WEB'))
			if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 

		if @mode in ('D')
		Begin 
			select @ROW =Count('x')  From Deleted where  
			Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ BdCoCd+',%')
				or (SysId='CRM' and SysDb='WEB'))
			if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End
 
	Set DateFormat DMY
 	/******** Key Cannot Be Changed (i.e. BdTc, BdYy, BdChr, BdNo, BdLoc, BdDt, BdSr cannot be changed) ********/
 	if @mode = 'C'
 	Begin
 		select @Row=Count('x') from deleted del where not exists
			(Select 'x' from inserted ins where
				ins.BdCoCd=del.BdCoCd and ins.BdTc= del.BdTc and ins.BdYy= del.BdYy
				and ins.BdChr= del.BdChr and ins.BdNo= del.BdNo and ins.BdSr=del.Bdsr)
 		If @Row > 0
	 	begin
			Select @ErrMsg='Cannot Change BgRecoDet Key'
			GoTo ErrHndlr
		end
	End
 	if @mode = 'D'
 	Begin
		/*** Cannot Delete a Reconciled Voucher ***/
 		select @Row=Count('x') from deleted del Join BgRecoMst On
				BmCoCd = del.BdCoCd And BmTc=del.BdTc And BmYy=del.BdYy
				And BmChr=del.BdChr And BmNo=del.BdNo And BmRecoYN = 'Y'
 		If @Row > 0
	 	begin
			Select @ErrMsg='Cannot Delete as Voucher is Reconciled'
			GoTo ErrHndlr
		end
	End
	if @mode in ('A','C')
	BEGIN
		/****** OrderNo should exist in OrdMst table ******/
		/* Current Partition bgrecomst bgrecodet */
		select @row= count('x') from inserted where 
			not exists (select 'x' from BgRecoMst where BmCoCd= BdCoCd and BmTc= BdTc
			and BmYy= BdYy and BmChr= BdChr and BmNo= BdNo)
		if @row> 0
		begin
			select @errmsg= 'Voucher Number Not Defined In Bag Reco Master'
			goto ErrHndlr
		end

		/*** Bag Reco CoCd should be a valid Company code ***/
		select @row=count('x') from inserted where
			BdCoCd Not In (Select HCoCd From Head Where HCoCd <>'ZZZ')
		if @row>0
		begin
			select @errmsg='Company Code is either Blank or not a Valid Company Code'
			goto ErrHndlr
		end
		/*** Bag CoCd should be a valid Company code ***/
		select @row=count('x') from inserted where
			BdBagCoCd Not In (Select HCoCd From Head Where HCoCd <>'ZZZ')
		if @row>0
		begin
			select @errmsg='Bag Company Code is either Blank or not a Valid Company Code'
			goto ErrHndlr
		end
		
		/*** Bag Reco Tc should be Valid ***/
		select @row=count('x') from inserted where (BdTc = '') Or (BdTc not in
		(Select PMCd From Param Where Ptyp='TC' And PValue='RC'))
		if @row>0
		begin
			select @errmsg='Tc Entered is Blank Or Invalid'
			goto ErrHndlr
		end
		/*** Bag Reco Yy should be Valid ***/
		select @row=count('x') from inserted where BdYy='' Or BdYy not in
		(Select PMCd From Param Where Ptyp='YY')
		if @row>0
		begin
			select @errmsg='Year is either Blank Or Not a Valid Yy'
			goto ErrHndlr
		end
		/*** Only a valid Chr Can be entered***/
		select @row=count('x') from inserted where BdChr='' Or BdChr Not In
		(Select vPSCd From vParam Where vPTyp='CHR' And vPCoCd=BdCoCd)
		if @row>0
		begin
			select @errmsg='Bag Reco Chr is either Blank Or Not a Valid Bag Reco Chr'
			goto ErrHndlr
		end
		/*** Only a valid Bag No Can be entered***/
		select @row=count('x') from inserted where
		BdBYy+BdBChr+Cast(BdBno as Varchar) Not In
			(Select BYy+BChr+Cast(BNo as Varchar) From Bag
				Where BCoCd=BdBagCoCd )
		if @row>0
		begin
			select @errmsg='Bag Number is Not a Valid Bag Number'
			goto ErrHndlr
		end
		/*** Only a valid Bag DmCd Can be entered***/
		select @row=count('x') from inserted where BdDmCd = '' Or BdDmCd Not In
		(Select BOdDmCd From Bag Where BCoCd=BdBagCoCd And BdBYy=BYy And BdBChr=BChr
			And BdBNo=BNo )
		if @row>0
		begin
			select @errmsg='Bag Design Code is either Blank Or Not Valid'
			goto ErrHndlr
		end
		/*** Only a valid Bag Gross Wt Can be entered***/
		select @row=count('x') from inserted where Round(BdGrWt, 3) Not In
		(Select Round(BGrWt, 3) From Bag Where BCoCd=BdBagCoCd And BdBYy=BYy And
			BdBChr=BChr And BdBNo=BNo )
		if @row>0
		begin
			select @errmsg='Bag Gross Wt is either Blank Or Not Valid'
			goto ErrHndlr
		end
		/*** Bag OthLoc should be Valid ***/
		select @row=count('x') from inserted where BdOthLocBg not in
		(Select PMCd From Param Where Ptyp='YN')
		if @row>0
		begin
			select @errmsg='Other Loc Bg should be either Y or N'
			goto ErrHndlr
		end
	End
return
ErrHndlr:
begin
	select @errmsg='|'+@errmsg
	raiserror(@errmsg,16,1)
	rollback transaction
	end
End

GOGO

ALTER TRIGGER [dbo].[BgRecoMst_INUPDL] ON [dbo].[BgRecoMst] 
       FOR INSERT,UPDATE,DELETE  NOT FOR REPLICATION
AS  
BEGIN  
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	DECLARE @ReplAgt BIT  
  
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'BgRecoMst' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
	case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	begin
	
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
			select @ROW =Count('x')  From inserted where  
			Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ BmCoCd +',%') 
				or (SysId='CRM' and SysDb='WEB'))
			if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
			select @ROW =Count('x')  From Deleted where  
			Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ BmCoCd +',%')
				or (SysId='CRM' and SysDb='WEB'))
			if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		end
	End 

	Set DateFormat DMY
 	if @mode = 'C'
 	Begin
		/******** Key Cannot Be Changed (i.e. BmCoCd, BmTc, BmYy, BmChr, BmNo cannot be changed) ********/
 		select @Row=Count('x') from deleted del where not exists
			(Select 'x' from inserted ins where
				ins.BmCoCd=del.BmCoCd and ins.BmTc= del.BmTc and ins.BmYy= del.BmYy
				and ins.BmChr= del.BmChr and ins.BmNo= del.BmNo)
 		If @Row > 0
	 	begin
			Select @ErrMsg='Cannot Change BgRecoMst Key'
			GoTo ErrHndlr
		end
		/*** Bag Reco Date cannot be changed ***/
		select @row=count('x') from deleted del where
			Not Exists (select 'x' from inserted ins where ins.BmCoCd= del.BmCoCd and ins.BmTc= del.BmTc and
					ins.BmYy= del.BmYy and ins.BmChr= del.BmChr and ins.BmNo= del.BmNo and ins.BmDt= del.BmDt)
			And Exists (Select 'x' from BgRecoDet Where BdCoCd= del.BmCoCd and BdTc= del.BmTc and
					BdYy= del.BmYy and BdChr= del.BmChr and BdNo= del.BmNo)
		if @row>0
		begin
			select @errmsg='Voucher Date Cannot Be Changed, While Child Record Exists.'
			goto ErrHndlr
		end
		/*** Bag Co Code cannot be changed ***/
		select @row=count('x') from deleted del where
			Not Exists (select 'x' from inserted ins where ins.BmCoCd= del.BmCoCd and ins.BmTc= del.BmTc and
					ins.BmYy= del.BmYy and ins.BmChr= del.BmChr and ins.BmNo= del.BmNo and 
					ins.BmBagCoCdFr= del.BmBagCoCdFr and ins.BmBagCoCdTo= del.BmBagCoCdTo and 
					ins.BmBagCoCdSel= del.BmBagCoCdSel)
			And Exists (Select 'x' from BgRecoDet Where BdCoCd= del.BmCoCd and BdTc= del.BmTc and
					BdYy= del.BmYy and BdChr= del.BmChr and BdNo= del.BmNo)
		if @row>0
		begin
			select @errmsg='Bag Company Code From, To or Sel Cannot Be Changed, While Child Record Exists.'
			goto ErrHndlr
		end
		
		/*** Bag Co Cd cannot be changed ***/
		
		/*** Bag Reco Location cannot be changed ***/
		select @row=count('x') from deleted del where
			Not Exists (select 'x' from inserted ins where ins.BmCoCd= del.BmCoCd and ins.BmTc= del.BmTc and
					ins.BmYy= del.BmYy and ins.BmChr= del.BmChr and ins.BmNo= del.BmNo and 
					ins.BmBagLocFr= del.BmBagLocFr and ins.BmBagLocTo= del.BmBagLocTo and 
					ins.BmBagLocSel= del.BmBagLocSel)
			And Exists (Select 'x' from BgRecoDet Where BdCoCd= del.BmCoCd and BdTc= del.BmTc and
					BdYy= del.BmYy and BdChr= del.BmChr and BdNo= del.BmNo)
		if @row>0
		begin
			select @errmsg='Voucher Location Cannot Be Changed, While Child Record Exists.'
			goto ErrHndlr
		end
		
		/*** Bag Reco Location cannot be changed ***/
		
		select @row=count('x') from deleted del where
			Not Exists (select 'x' from inserted ins where ins.BmCoCd= del.BmCoCd and ins.BmTc= del.BmTc and
					ins.BmYy= del.BmYy and ins.BmChr= del.BmChr and ins.BmNo= del.BmNo and ins.BmCalcActQtyYN= del.BmCalcActQtyYN)
			And Exists (Select 'x' from BgRecoDet Where BdCoCd= del.BmCoCd and BdTc= del.BmTc and
					BdYy= del.BmYy and BdChr= del.BmChr and BdNo= del.BmNo)
		if @row>0
		begin
			select @errmsg='Calculate Reported Qty Option Cannot Be Changed, While Child Record Exists.'
			goto ErrHndlr
		end
	End
	
 	if @mode = 'D'
 	Begin
		/*** Cannot Delete if Details Exists ***/
 		select @Row=Count('x') from deleted del Where 
			Exists (Select 'x' From BgRecoDet Where
				BdCoCd=BmCoCd And BdTc=BmTc And BdYy=BmYy And BdChr=BmChr And BdNo=BmNo)
 		If @Row > 0
	 	begin
			Select @ErrMsg='Cannot Delete Voucher as Details Exist'
			GoTo ErrHndlr
		end
	End
	if @mode in ('C','D')
	BEGIN
		/*** Cannot Delete Voucher if it is Reconciled ***/
 		select @Row=Count('x') from deleted del Where BmRecoYn='Y'
 		If @Row > 0
	 	begin
			Select @ErrMsg='Cannot Update / Delete a Reconciled Voucher'
			GoTo ErrHndlr
		end
	END
	if @mode in ('A','C')
	BEGIN
		/*** Bag Reco CoCd should be a valid Company code ***/
		select @row=count('x') from inserted where
			BmCoCd Not In (Select HCoCd From Head Where HCoCd <>'ZZZ')
		if @row>0
		begin
			select @errmsg='Company Code is either Blank or not a Valid Company Code'
			goto ErrHndlr
		end

		/*** Bag Reco Tc should be Valid ***/
		select @row=count('x') from inserted where (BmTc = '') Or (BmTc not in
		(Select PMCd From Param Where Ptyp='TC' And PValue='RC'))
		if @row>0
		begin
			select @errmsg='Tc Entered is Blank Or Invalid'
			goto ErrHndlr
		end
		/*** Bag Reco Yy should be Valid ***/
		select @row=count('x') from inserted where BmYy='' Or BmYy not in
		(Select PMCd From Param Where Ptyp='YY')
		if @row>0
		begin
			select @errmsg='Year is either Blank Or Not a Valid Yy'
			goto ErrHndlr
		end
		/*** Only a valid Chr Can be entered***/
		select @row=count('x') from inserted where BmChr='' Or BmChr Not In
		(Select vPSCd From vParam Where vPTyp='CHR' And vPCoCd=BmCoCd)
		if @row>0
		begin
			select @errmsg='Bag Reco Chr is either Blank Or Not a Valid Bag Reco Chr'
			goto ErrHndlr
		end
		/*** Only a valid Process Location Can be Entered 
		select @row=count('x') from inserted where BmLoc = '' Or BmLoc not in
		(Select LocCd from Loc where LocTyp='P' And LocCoCd=BmCoCd And LocValidYN='Y')
		if @row>0
		begin
			select @errmsg='Location Selected is either Blank Or Not a Valid Process Location'
			goto ErrHndlr
		end
		***/
		/*** Bag RecoYn should be Valid ***/
		select @row=count('x') From Inserted Where BmRecoYN Not In
		(Select PMCd From Param Where Ptyp='YN')
		if @row>0
		begin
			select @errmsg='BagRecoYN should be either Y or N'
			goto ErrHndlr
		end

		/*** Reco Voucher Location and Date should be Unique ***/
		/*select @row=Count('x') From Inserted Ins Where 
			Exists (Select 'x' From BgRecoMst Bg Where Ins.BmCoCd=Bg.BmCoCd And Ins.BmTc=Bg.BmTc
				And Ins.BmYy=Bg.BmYy And Ins.BmLoc=Bg.BmLoc And Ins.BmDt=Bg.BmDt
				And (Ins.BmChr <>Bg.BmChr Or Ins.BmNo<>Bg.BmNo ) )
		If @row>0
		Begin
			Select @errmsg='Bag Reco Date and Location already exists '
			GoTo ErrHndlr
		End*/

		/*** Bag BmCalcActQtyYN should be Valid ***/
		select @row=count('x') From Inserted Where BmCalcActQtyYN Not In
		(Select PMCd From Param Where Ptyp='YN')
		if @row>0
		begin
			select @errmsg='Calculate Reported Qty should be either Y or N'
			goto ErrHndlr
		end
	END
return
ErrHndlr:
begin
	select @errmsg='|'+@errmsg
	raiserror(@errmsg,16,1)
	rollback transaction
		end
end

GOGO
/************************* DJ12 trigger ******************************************************************************************/
If exists (Select 'a' from Sys.Triggers where upper(name) = 'TXNDRWRK_INUPDL')
begin
	drop trigger TxndRwrk_inupdl 
end

GOGO

CREATE TRIGGER [dbo].[TxndRwrk_INUPDL] ON [dbo].[TxndRwrk] 
   FOR INSERT,UPDATE,DELETE  
AS  
BEGIN
	/* Trigger Version 3.02.0 (Speed Optimization) */  
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	Declare @wTcTyp Varchar(3)
	Declare @wEntTyp Varchar(8)
	Declare @wHCd Varchar(8)
	DECLARE @ReplAgt BIT  
	DECLARE @wCurrPrtn VarChar(1)
	
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'TxndRwrk' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	Select @wHCd= 'ZSELF'
	Select @wCurrPrtn='C'
		
	/*** Storing Tc Type In The Variable @wTcTyp ***/
	if @mode in ('A','C')
	Begin
		select @wTcTyp=max(PValue) from inserted join Param on PTyp= 'TC' and PMCd= TrwTc and PSCd=''
	end
	if @mode in ('D')
	Begin
		select @wTcTyp=max(PValue) from deleted join Param on PTyp= 'TC' and PMCd= TrwTc and PSCd=''
	end

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='C'
	begin
		Select @row=count('x') From Inserted Where TrwPrtKey<>@wCurrPrtn
		If @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end

		Select @row=count('x') From Deleted del
					 Where Exists(Select 'x' From Inserted ins Where ins.TrwCoCd=del.TrwCoCd and
									ins.TrwTc=Del.TrwTc and ins.TrwYy=del.TrwYy and ins.TrwChr=del.TrwChr 
									and ins.TrwNo=del.TrwNo and ins.TrwSr=del.TrwSr and ins.TrwSrNo=del.TrwSrNo 
									and ins.TrwPrtKey<>del.TrwPrtKey) 
		If @row> 0 
		begin
			select @errmsg= 'Cannot Edit Partition Key Field'
			goto ErrHndlr
		end
	End

	if @mode='A'
	Begin
		Select @row=count('x') From Inserted Where TrwPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 

	If @Mode='D' 
	Begin 
		select @row= count('x') from deleted del where del.TrwPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */

	If  (@ReplAgt<>1)
	begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From inserted where TrwPrtKey=@wCurrPrtn and  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TrwCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 

		/* Current Partition */
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where TrwPrtKey=@wCurrPrtn and 
			Exists (select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ TrwCoCd +',%')
				or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End 
	/******** Only One TcTyp records can be Inserted at a time ********/
	/* Partition Key Not Required */
	select @Row= Count(distinct(PValue)) from inserted Join param On
		PTyp= 'TC' and PMCd= TrwTc and PSCd= ''
	If @Row > 1
	BEGIN
		Select @ErrMsg= 'Transactions of only One TcType can be Acted On'
	  	GoTo ErrHndlr
	END

	/******** Only One TcTyp records can be Deleted at a time *********/
	/* Partition Key Not Required */	
	select @Row= Count(distinct(PValue)) from deleted Join param on
		PTyp='TC' and PMcd= TrwTc and PSCd= ''
	If @Row > 1
	BEGIN
		Select @ErrMsg='Transactions of only One TcType can be Acted On'
		GoTo ErrHndlr
	END
	
	/*** Storing Entry Type In The Variable @wEntTyp ***/
	select @wEntTyp= PValue1 from Param  where PTyp= 'TCTYP' and PMCd=@wTcTyp and PSCd=''
	
	if @mode in ('A','C')
	Begin
		/********** EntTyp Should Be 'FgBag' or 'FgRm' (Check In Param) ********/
		/* Current Partition */
		select @row=count('x') from inserted 
			where TrwPrtKey=@wCurrPrtn and TrwTc <> 'DT' 
		if @row> 0
		Begin
			Select @ErrMsg='Transactions of only ''DT'' Types permitted'
			GoTo ErrHndlr
		end
		
		/*****4.1.2********/	
		Select @Row=Count('x') From Inserted ins where 
			(Select hHolChkYN From Head where HCd='ZSELF' and HCoCd=TrwCoCd)='Y' and
			(@Mode='A' or (@Mode='C' and  ins.TrwDt<>IsNull((Select TrwDt From Deleted del where 
									ins.TrwPrtKey=del.TrwPrtKey and ins.TrwIdNo=del.TrwIdNo 
									and ins.TrwCoCd= del.TrwCoCd and ins.TrwTc= del.TrwTc and ins.TrwYy= del.TrwYy 
										and ins.TrwChr= del.TrwChr and ins.TrwNo= del.TrwNo 
										and ins.TrwSr=del.TrwSr and ins.TrwSrNo=del.TrwSrNo),ins.TrwDt))) and  
							 exists(Select 'x' From DtTbl Where DtTag='HOL' and TrwDt=DtDt and DtHolYN='Y')
		If @Row> 0
		begin  
			select @errmsg= 'Cannot Add Voucher On Holidays.'  
			goto ErrHndlr  
		end  
				

		/******  TrwCoCd = HCoCd   *******/
		/* Current Partition */
		select @row= count('x') from inserted where TrwPrtKey=@wCurrPrtn and not exists (select 'x' from Head where HCoCd= TrwCoCd and HCd= @wHCd)
		if @row> 0
		begin
			select @errMsg= 'Company Code Not Valid'
			goto ErrHndlr
		end

		/******  TrwYy  =  PMCd ('YY')  ******/
		/* Current Partition */
		select @row= count('x') from inserted where TrwPrtKey=@wCurrPrtn and
			     not exists (select 'x' from Param where PTyp='YY' and PMCd= TrwYy)
		if @row> 0
		begin
			select @errmsg= 'Voucher Year Not Defined'
			goto ErrHndlr
		end

		/******  TrwChr  =  PSCd ('CHR', TrwTc)  ******/
		/* Current Partition */
		select @row= count('x') from inserted where TrwPrtKey=@wCurrPrtn and
			     not exists (select 'x' from vParam where vPCoCd= TrwCoCd and
					vPTyp='CHR' and vPMCd= TrwTc and vPSCd= TrwChr)
		if @row> 0
		begin
			select @errmsg= 'Voucher Character Not Defined'
			goto ErrHndlr
		end

		/******  TrwNo  <>  0  ******/
		/* Current Partition */
		select @row= count('x') from inserted where TrwPrtKey=@wCurrPrtn and TrwNo= 0
		if @row> 0
		begin
			select @errmsg= 'Voucher Number Cannot Be Zero'
			goto ErrHndlr
		end

		/****** Voucher Date Cannot Be Blank ******/
		/* Current Partition */
		select @Row= Count('x') from Inserted where TrwPrtKey=@wCurrPrtn and TrwDt in ('01/01/1980', '01/01/1900')
		If @Row > 0
		begin
			Select @ErrMsg= 'Date Cannot Be Blank'
			GoTo ErrHndlr
		end

		
		/******  TrwByLoc Valid Loc, LocTyp = 'P'   ********/
		Select @Row= Count('x') From Inserted Ins 
			Where Not Exists (Select 'x' From Loc where LocCoCd = TrwCoCd and 
				LocTyp = 'P' and LocCd = TrwByLoc) 
  	  	If @Row> 0 
		begin
			Select @ErrMsg= 'Process Loc Not Defined'
		  	GoTo ErrHndlr
		end

		/******  TrwRwrk valid PMCd=ByLoc   ******/
		select @row= count('x') from inserted where TrwPrtKey=@wCurrPrtn and
			     not exists (select 'x' from Param where PTyp='RWRK' and PMCd=TrwByLoc and PSCd = TrwRwrkCd)
		if @row> 0
		begin
			select @errmsg= 'Rework Code Not Defined'
			goto ErrHndlr
		end

		/******  TrwByWrk  =  vPMCd ('WORK')  ******/
		/* Current Partition */
		select @row= count('x') from inserted where TrwPrtKey=@wCurrPrtn and
			     not exists (select 'x' from vParam where vPCoCd= TrwCoCd and
					vPTyp='WORK' and vPMCd= TrwByWrk)
		if @row> 0
		begin
			select @errmsg= 'Worker Code Not Defined'
			goto ErrHndlr
		end
	End

	If @Mode = 'C'
	Begin
		/*******Cannot Change Key values ********/
		/* Current Partition */
		select @Row= Count('x') from Deleted Del where Del.TrwPrtKey=@wCurrPrtn and
			 Not Exists (Select 'x' from Inserted Ins where Ins.TrwIdNo=Del.TrwIdNo and
					Ins.TrwPrtKey=Del.TrwPrtKey and Ins.TrwCoCd=Del.TrwCoCd and Ins.TrwTc=Del.TrwTc and Ins.TrwYy=Del.TrwYy
					and Ins.TrwChr= Del.TrwChr and Ins.TrwNo=Del.TrwNo and ins.TrwSr=del.TrwSr and ins.TrwSrNo=del.TrwSrNo)
		If @Row> 0
		BEGIN
			Select @ErrMsg= 'Cannot Change Voucher No'
			GoTo ErrHndlr
		END

	End

/**	if @mode in ('D')
	Begin
			
	End  **/
Return
ErrHndlr:
	Begin
		Select @ErrMsg='|'+@ErrMsg
		RaisError(@ErrMsg,16,1)
		Rollback Transaction
	End
END

GOGO

/*********************************************************************************************************************************/
/* Indigo 1 */
ALTER TRIGGER [dbo].[RmRt_INUPDL] ON [dbo].[RmRt] 
         FOR INSERT,UPDATE,DELETE NOT FOR REPLICATION
AS
BEGIN
	/* Trigger Version 3.8.0 */
 	DECLARE @ROW INT
 	DECLARE @mode char(1)
 	DECLARE @errmsg varchar(255)
	DECLARE @SYS VARCHAR(5)
	DECLARE @ReplAgt BIT  
	DECLARE @wSelfCd VARCHAR(8)
	DECLARE @wCurrPrtn VARCHAR(1)

 	IF @@ROWCOUNT=0
	  	RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'RmRt')
		RETURN

	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '') 

	select @mode=case (select count('x') from inserted) when 0 then 'D'
       		           else
   			  case (select count('x') from deleted) when 0 then 'A' else 'C' end
       		           end

	set @wSelfCd = 'ZSELF'	
	Set @wCurrPrtn = 'C'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode ='A' and @ReplAgt<>1
	begin
		Select @row=count('x') From Inserted Where RrPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Records of Previous Partition'
			goto ErrHndlr
		end
	End

	if @mode ='C' and @ReplAgt<>1
	begin
		Select @row=count('x') From Inserted Where RrPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	end 

	if @mode ='D' and @ReplAgt<>1
	begin
		Select @row=count('x') From Deleted Where RrPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records of Previous Partition'
			goto ErrHndlr
		end
	end 

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */

	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

 	/******** Records Of Only One Typ Can Be Inserted At A Time ********/
	select @Row= Count(distinct(RrTcTyp)) from inserted
	If @Row > 1
	Begin
		Select @ErrMsg= 'Records Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/******** Records Of Only One Typ Can Be Deleted At A Time ********/
	select @Row= Count(distinct(RrTcTyp)) from deleted
	If @Row > 1
	Begin
		Select @ErrMsg= 'Records Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/******** RM Rate TcType Not Defined ********/
	select @row= count('x') from inserted where
  		not exists (select 'x' from Param where PTyp= 'RRTCTYP' and PMCd= RrTcTyp)
 	if @row> 0
 	Begin
  		select @errmsg= 'Tc Type Not Defined'
  		goto ErrHndlr
 	end

	/******  If RrTcTyp = 'INL'	then  RrCtg  =  Blank	else  RrCtg  =  PMCd ('RMCTG')  ******/
/* Zubin 212 ('MUP' added) */
	/***Crm*212*Geeta*****/
	/* ****** Sachin 3.3.0 (24-06-08) - [14. Cost Markup in Invoicing] ****** */
	/* bhavna added CHN */
 	select @row= count('x') from inserted where RrTcTyp Not In ('INL', 'MUP', 'FRT', 'IML','WXT','WCT','CHN') and
  		not exists (select 'x' from Param where PTyp= 'RMCTG' and PMCd= RrCtg)
 	if @row> 0
 	Begin
  		select @errmsg= 'Raw Material Category Not Defined'
  		goto ErrHndlr
 	end

	select @row= count('x') from inserted where RrTcTyp IN ('INL','IML') and RrCtg<> ''
 	if @row>0
 	Begin
  		select @errmsg= 'Raw Material Category Should Be Blank'
  		goto ErrHndlr
 	end
 	
	
	/****** If TcStr records does not exist for an RrTcTyp & RrCtg combination then do not allow the user to add such a record ******/
	select @row= count('x') from inserted where not exists(Select 'x' from TcStr 
		where TsTbl= 'RmRt' and TsTyp= RrTcTyp and TsSTyp= RrCtg )
 	if @row>0
 	Begin
  		select @errmsg= 'TcType and RmCtg Combination Not Defined In Tc Structure'
  		goto ErrHndlr
 	end

	/* *** Jay 3.1.3 [CRP] */
	select @row= count('x') from inserted where RrTcTyp= 'CRP' and
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB')
	if @row>0
 	Begin 
		select @errmsg= 'Cannot Insert /Update /Delete For CRM' 
		goto ErrHndlr 
	end 
	/* *** Jay 3.1.3 [CRP] */

	/*bhavna removed check for CHN*/
	/******  RrSCtg  =  Blank  or  PSCd ('RMCTG', RrCtg)  ******/
	select @row= count('x') from inserted where RrSCtg <> '' and RrTcTyp <> 'CHN' and 
  		not exists (select 'x' from Param where
       		PTyp= 'RMSCTG' and PMCd= RrCtg and PSCd= RrSCtg)
 	if @row>0
 	Begin
  		select @errmsg= 'Raw Material Sub Category Not Defined'
  		goto ErrHndlr
 	end

	/*bhavna removed check for CHN*/
	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrSCtg') = 'N' 	then 	RrSCtg  =  Not Blank  ******/
	select @row= count('x') from inserted where RrSCtg= '' and RrTcTyp <> 'CHN' and
  		(Select TsBlank from TcStr where TsTbl= 'RmRt' and TsTyp= RrTcTyp 
			and TsSTyp=RrCtg and TsIdName= 'RrSCtg') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Raw Material Sub Category Cannot Be Blank'
  		goto ErrHndlr
 	end

	/******  If RrTcTyp= 'PTR' then if the 'RATEBY' option of the RmSCtg in Param is 'P' then insert not allowed ******/
	select @row= count('x') from inserted where RrTcTyp= 'PTR' and 
  		exists (select 'x' from Param where 
       		PTyp= 'RMSCTG' and PMCd= RrCtg and PSCd= RrSCtg and PValue= 'P')
 	if @row> 0
 	Begin
  		select @errmsg= 'Cannot Enter This Record As RateBy Option For This Rm SubCtg Is Already Pointer'
  		goto ErrHndlr
 	end

	/*************Geeta**Emr206********05/04/04***************/	
	/******  If RrTcTyp= 'PTR'  and if a record exists for RrTcTyp='BS' for the same
			Custome,RmCtg,RmSCtg then insert not allowed  visa versa******/
	select @row= count('x') from inserted ins where RrTcTyp in ('PTR','BS') and 
  		exists (select 'x' from RmRt Rr where 
       		Rr.RrTcTyp = case when ins.RrTcTyp='PTR' then 'BS' else 'PTR' end and Rr.RrCmCtg='C' and Rr.RrCmCd=ins.RrCmCd and 
		Rr.RrCmCurCd='' and Rr.RrCtg=ins.RrCtg and
		Rr.RrSctg=ins.RrSctg and Rr.RrSTWGrp='' and  Rr.RrCd='' and Rr.RrDmCtg='' and Rr.RrDmCd='' and 
		Rr.RrLsCtg=''  and  Rr.RrLabMCd='' and  Rr.RrFrLn='' and Rr.RrToLn='')
 	if @row> 0
 	Begin
  		select @errmsg= 'Both (BS/PTR) charts cannot be defined for the same customer ,RmCtg,RmSCtg'
  		goto ErrHndlr
 	end

	/******  If RrTcTyp= 'BS' then if the 'RATEBY' option of the RmSCtg in Param is 'BS' then insert not allowed ******/
	select @row= count('x') from inserted where RrTcTyp= 'BS' and 
  		exists (select 'x' from Param where 
       		PTyp= 'RMSCTG' and PMCd= RrCtg and PSCd= RrSCtg and PValue= 'BS')
 	if @row> 0
 	Begin
  		select @errmsg= 'Cannot Enter This Record As RateBy Option For This Rm SubCtg Is Already BS'
  		goto ErrHndlr
 	end
	
	/******  'BS'or 'PTR' Chart cannot be defined fot 'ZSELF' and 'ZValue'  then  ******/
	/* *** JAY 3.1.3 [CRP] */
	select @row= count('x') from inserted where RrTcTyp in ('BS','PTR','CRP') and RrCmCd in('ZSelf','ZValue')
  	if @row> 0
 	Begin
  		select @errmsg= 'BS/PTR/CRP Chart Cannot be defined for ''ZSelf''/''ZValue'' '
  		goto ErrHndlr
 	end
	/* *** JAY 3.1.3 [CRP] */
	/*************************Geeta*************************************/

/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */
	/******  RrCd  =  Blank  or  valid RmCd from RmMst (RmCtg= RrCtg, RmSCtg= RrSCtg)  ******/
	select @row= count('x') from inserted Ins where Ins.RrCd<> '' and Ins.RrPrtKey=@wCurrPrtn and
  		not exists (select 'x' from RmMst where RmPrtKey=Ins.RrPrtKey and
       		RmCtg= Ins.RrCtg and RmSCtg= Ins.RrSCtg and RmCd= Ins.RrCd and RmZ= 'N' And
			(RmValidYN = 'Y' Or @Mode = 'C'))
 	if @row> 0
 	Begin
  		select @errmsg= 'Raw Material Code Not Defined / Invalid'
  		goto ErrHndlr
 	end   

/* (Bef 2.06)
	select @row= count('x') from inserted where RrCd<> '' and
  		not exists (select 'x' from RmMst where
       		RmCtg= RrCtg and RmSCtg= RrSCtg and RmCd= RrCd and RmZ= 'N')
 	if @row> 0
 	Begin
  		select @errmsg= 'Raw Material Code Not Defined'
  		goto ErrHndlr
 	end
*/
/*  #########################################  Manoj  #########################################  */

	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrCd') = 'N' 	then 	RrCd  =  Not Blank  ******/
 	select @row= count('x') from inserted where RrCd= '' and
 		 (Select TsBlank from TcStr where TsTbl= 'RmRt' and TsTyp= RrTcTyp 
		and TsSTyp= RrCtg and TsIdName= 'RrCd') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Raw Material Code Cannot Be Blank'
