  		IsNull((Select PValue from Param where PTyp= 'RMSCTG' and
                        	PMCd= RrCtg and PSCd= RrSCtg), '') <> 'BS' and
		(Select count('x') from RmRt Rt where Rt.RrTcTyp= ins.RrTcTyp and
   		Rt.RrCmCtg= ins.RrCmCtg and Rt.RrCmCd= ins.RrCmCd and 
		Rt.RrCmCurCd= ins.RrCmCurCd and Rt.RrCtg= ins.RrCtg and
   		Rt.RrSCtg= ins.RrSCtg and Rt.RrSTWGrp= ins.RrSTWGrp and 
		Rt.RrCd= ins.RrCd and Rt.RrDmCtg= ins.RrDmCtg and 
		Rt.RrLsCtg= ins.RrLsCtg and Rt.RrLabMCd= ins.RrLabMCd
   		and  (    (Rt.RrFrLn<= ins.RrFrLn and
      			 Rt.RrToLn>= ins.RrFrLn)
		    or  	(Rt.RrFrLn<= ins.RrToLn and
		      	 Rt.RrToLn>= ins.RrToLn)
    		    or  	(ins.RrFrLn<= Rt.RrFrLn and
			 ins.RrToLn>= Rt.RrToLn)
		 )
  		) > 1   */


	/**********************Geeta***Emr206**05/04/04****** If 'BS' Record exists for the same 
				Combination then don't check the Size Range******/
	/******  The Size Range should be unique  (i.e. it shouldn't overlap other size 
		ranges for the same RrTcTyp, RrCmCd, RrCmCurCd, RrDmCd, RrCtg, RrSCtg, RrCd, 
		RrDmCtg, RrLabMCd combination)  ******/
	/**********Geeta*********Emr207*********Range Size Check not reqd for Both Sides Wt-'BSW'*********/ 
	/* *** JAY 3.01 [NAS] *** */
	/*bhavna removed check for CHN*/
	select @row= count('x') from inserted ins where  ins.RrTcTyp not in ('BSW', 'NAS', 'CHN') and
  		IsNull((Select PValue from Param where PTyp= 'RMSCTG' and
                        	PMCd= RrCtg and PSCd= RrSCtg), '') <> 'BS' and
		not exists (Select * from RmRt Rr where Rr.RrTcTyp= 'BS' and
   		Rr.RrCmCtg=ins.RrCmCtg and Rr.RrCmCd= ins.RrCmCd and 
		Rr.RrCmCurCd='' and Rr.RrCtg= ins.RrCtg and
   		Rr.RrSCtg= ins.RrSCtg and Rr.RrSTWGrp= '' and 
		Rr.RrCd= '' and Rr.RrDmCtg= '' and Rr.RrDmCd=ins.RrDmCd and 
		Rr.RrLsCtg= '' and Rr.RrLabMCd= '')
		and
  		(Select count('x') from RmRt Rt where Rt.RrTcTyp= ins.RrTcTyp and
   		Rt.RrCmCtg= ins.RrCmCtg and Rt.RrCmCd= ins.RrCmCd and 
		Rt.RrCmCurCd= ins.RrCmCurCd and Rt.RrCtg= ins.RrCtg and
   		Rt.RrSCtg= ins.RrSCtg and Rt.RrSTWGrp= ins.RrSTWGrp and 
		Rt.RrCd= ins.RrCd and Rt.RrDmCtg= ins.RrDmCtg and Rt.RrDmCd=ins.RrDmCd and 
		Rt.RrLsCtg= ins.RrLsCtg and Rt.RrLabMCd= ins.RrLabMCd
   		and  (    (Rt.RrFrLn<= ins.RrFrLn and
      			 Rt.RrToLn>= ins.RrFrLn)
		    or  	(Rt.RrFrLn<= ins.RrToLn and
		      	 Rt.RrToLn>= ins.RrToLn)
    		    or  	(ins.RrFrLn<= Rt.RrFrLn and
			 ins.RrToLn>= Rt.RrToLn)
		 )
  		) > 1   
	if @row> 0
 	begin
  		select @errmsg= 'Size Range Already Defined'
  		goto ErrHndlr
 	end 


/****************************Geeta***Emr206********** 22/04/04**************/ 
IF @mode = 'D'
	begin	
		/************** Deletion not allowed if rec exists in RmRt  RrTcTyp='RM'**************/
		select @row=count('x') from deleted  del where RrTcTyp='BS'  and  
		exists(select * from RmRt Rr where Rr.RrTcTyp='RM' and 
			Rr.RrCmCtg= del.RrCmCtg and Rr.RrCmCd=del.RrCmCd and Rr.RrCtg=del.RrCtg and 
			Rr.RrSCtg= del.RrSCtg  and Rr.RrDmCtg=del.RrDmCtg and Rr.RrLabMCd=del.RrLabMCd 
			and Rr.RrLsCtg=del.RrLsCtg and Rr.RrRngSz=del.RrRngSz and 
			Rr.RrSTWGrp=del.RrSTWGrp and Rr.RrXWtPer=del.RrXWtPer and ((RrFrLn>rrToLn) or
	  		(Select count('x') from RmRt Rt where Rt.RrTcTyp= Rr.RrTcTyp and
	   		Rt.RrCmCtg= Rr.RrCmCtg and Rt.RrCmCd= Rr.RrCmCd and 
			Rt.RrCmCurCd= Rr.RrCmCurCd and Rt.RrCtg= Rr.RrCtg and
	   		Rt.RrSCtg= Rr.RrSCtg and Rt.RrSTWGrp= Rr.RrSTWGrp and 
			Rt.RrCd= Rr.RrCd and Rt.RrDmCtg= Rr.RrDmCtg and Rt.RrDmCd=Rr.RrDmCd and 
			Rt.RrLsCtg= Rr.RrLsCtg and Rt.RrLabMCd= Rr.RrLabMCd
	   		and  ( (Rt.RrFrLn<= Rr.RrFrLn and
	      			Rt.RrToLn>= Rr.RrFrLn)
			    or  	(Rt.RrFrLn<= Rr.RrToLn and
			      	Rt.RrToLn>= Rr.RrToLn)
	    		    or  	(Rr.RrFrLn<= Rt.RrFrLn and
				Rr.RrToLn>= Rt.RrToLn)
			 )
	  		) > 1 ) ) 
		if @row > 0
	 	begin
	  		select @errmsg= 'Cannot delete, Child records exist in RmRt '
	  		goto ErrHndlr
	 	end    
	 	
		/************** Deletion not allowed if rec exists in RmRtHist  RrTcTyp='RM'**************/
		select @row=count('x') from deleted  del where RrTcTyp='BS'  and  
		exists(select * from RmRtHist Rh where Rh.RhTcTyp='RM' and 
			Rh.RhCmCtg= del.RrCmCtg and Rh.RhCmCd=del.RrCmCd and Rh.RhCtg=del.RrCtg and 
			Rh.RhSCtg= del.RrSCtg  and  Rh.RhDmCtg=del.RrDmCtg and Rh.RhLabMCd=del.RrLabMCd and 
			Rh.RhLsCtg=del.RrLsCtg and Rh.RhRngSz=del.RrRngSz and Rh.RhSTWGrp=del.RrSTWGrp 
			and Rh.RhXWtPer=del.RrXWtPer and ((RhFrLn>RhToLn) or
	  		(Select count('x') from RmRtHist Rth where Rth.RhTcTyp= Rh.RhTcTyp and Rth.RhYyyymm= Rh.RhYyyyMm and
	   		Rth.RhCmCtg= Rh.RhCmCtg and Rth.RhCmCd= Rh.RhCmCd and 
			Rth.RhCmCurCd= Rh.RhCmCurCd and Rth.RhCtg= Rh.RhCtg and
	   		Rth.RhSCtg= Rh.RhSCtg and Rth.RhSTWGrp= Rh.RhSTWGrp and 
			Rth.RhCd= Rh.RhCd and Rth.RhDmCtg= Rh.RhDmCtg and 
			Rth.RhLsCtg= Rh.RhLsCtg and Rth.RhLabMCd= Rh.RhLabMCd
	   		and  ( (Rth.RhFrLn<= Rh.RhFrLn and
	      			Rth.RhToLn>= Rh.RhFrLn)
			    or  	(Rth.RhFrLn<= Rh.RhToLn and
			      	Rth.RhToLn>= Rh.RhToLn)
	    		    or  	(Rh.RhFrLn<= Rth.RhFrLn and
				Rh.RhToLn>= Rth.RhToLn)
			 )
	  		) > 1 ))
		if @row > 0
	 	begin
	  		select @errmsg= 'Cannot delete, Child records exist in RmRtHist '
	  		goto ErrHndlr
	 	end 
	 	
	 	/************** Deletion not allowed if rec exists in LabRt  RrTcTyp='CHN'**************
	 		select @row=count('x') from deleted  del where RrTcTyp='CHN'  and  
		exists(select * from LabRt Lr where Lr.LrMCd = 'CHN' and Lr.LrSCd = 'CHN' and 
			Lr.LrCmCtg = del.RrCmCtg and Lr.LrCmCd = del.RrCmCd )
		if @row > 0
	 	begin
	  		select @errmsg= 'Cannot delete, Child records exist in LabRt '
	  		goto ErrHndlr
	 	end  ***/  
	end



	if @SYS= 'XEMR' 
	BEGIN

		/******  RrCmCtg  =  valid PMCd('CMCTG')  ******/
		select @row= count('x') from inserted where RrCmCtg not in ('C', 'P', 'S', 'T')
	 	if @row> 0
	 	Begin
	  		select @errmsg= 'Customer Catagory Should Be Either ''C'', ''P'', ''S'' or ''T'' '
	  		goto ErrHndlr
	 	end

		/******  RrCmCurCd  = if RrCmCd= 'ZSELF' then valid xPMCd from xParam  (where 
							xPTyp= 'CURNCY'  and xPSCd= '') 
				     Else if RrCmCd<> 'ZSELF' then Valid CmCurCd from CustMst (Where 
					CmCtg= RrCmCtg and CmCd= RrCmCd) *****/	
		Select @row= count('x') from inserted where RrTcTyp= 'RM' and 
				(     	(RrCmCd= 'ZSELF' and 
						not Exists(select 'x' from Param where 
						PTyp= 'CURNCY' and PMCd= RrCmCurCd) 
				      	)
				      	Or 
				      	(RrCmCd <> 'ZSELF' and 
						Not exists (select 'x' from CustMst where CmCtg= RrCmCtg 
						and CmCd= RrCmCd and CmCurCd= RrCmCurCd)
					)
				)
	 	if @row> 0
 		Begin
  			select @errmsg= 'Currency Code Not Defined'
	  		goto ErrHndlr
 		end
	
		/******  The Size Range should be unique  (i.e. it shouldn't overlap other size ranges for the same RrTcTyp, RrCmCd, RrCtg, RrSCtg, RrCd, 
			RrDmCtg, RrLabMCd combination)  ******/
/***		select @row= count('x') from inserted ins where 
  			IsNull((Select PValue from Param where PTyp= 'RMSCTG' and 
                	        	PMCd= RrCtg and PSCd= RrSCtg), '') <> 'BS' and 
	  		(Select count('x') from RmRt Rt where Rt.RrTcTyp= ins.RrTcTyp and 
   			Rt.RrCmCtg= ins.RrCmCtg and Rt.RrCmCd= ins.RrCmCd and Rt.RrCmCurCd= ins.RrCmCurCd and 
			Rt.RrCtg= ins.RrCtg and Rt.RrSCtg= ins.RrSCtg and Rt.RrSTWGrp= ins.RrSTWGrp and 
			Rt.RrCd= ins.RrCd and Rt.RrDmCtg= ins.RrDmCtg and Rt.RrLsCtg= ins.RrLsCtg and 
			Rt.RrLabMCd= ins.RrLabMCd 
   			and  (    (Rt.RrFrLn<= ins.RrFrLn and
	      			 Rt.RrToLn>= ins.RrFrLn)
			    or  	(Rt.RrFrLn<= ins.RrToLn and
			      	 Rt.RrToLn>= ins.RrToLn)
	    		    or  	(ins.RrFrLn<= Rt.RrFrLn and
				 ins.RrToLn>= Rt.RrToLn)
			 )
	  		) > 1
		if @row> 0
	 	Begin
  			select @errmsg= 'Size Range Already Defined'
  			goto ErrHndlr
	 	end
***/
	END



return
ErrHndlr:
	begin
  		select @errmsg='|'+@errmsg
  		raiserror(@errmsg,16,1)
  		rollback transaction
 	end
end

GOGO


/********************* Cost Rate Editable and Rework as Module *****************************************/
ALTER TRIGGER [dbo].[Head_INUPDL] ON [dbo].[Head]
    FOR INSERT,UPDATE,DELETE NOT FOR REPLICATION
AS
BEGIN
	/* *** Trigger Version 3.11.0 *** */
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @wSelfCd VARCHAR(8)
	DECLARE @wSelfCoCd varchar(3)
	DECLARE @ReplAgt BIT
	
	set @wSelfCoCd= 'ZZZ'
	set @wSelfCd = 'ZSELF'	

	IF @@ROWCOUNT=0
		RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'Head')
		RETURN

	select @mode=case (select count('x') from inserted) when 0 then 'D'
			else
			case (select count('x') from deleted) when 0 then 'A' else 'C' end
			end 

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ HCoCd +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ HCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	

	If @mode in ('A' , 'C')
	Begin
	/* Zubin 211 (hFluteBagYN= ins.hFluteBagYN and HDTPrdPtr= ins.HDTPrdPtr added) */ 
		/*** introduced hLooseInv (Jen 2.12 Patch 3)***/
		/*** introduced HConsolidatedInv, HAutomateReturns (Jen 2.13)***/
		/****** Sachin 2.13.0 - introduced HQWModYN And HModAvlYN ******/ 
		/****** Sachin 2.14.0 - introduced HImpComLoc ******/ 
		/* Zubin 213 (HMultiCurYn added) */ 
		/* *** JAY 2.13(CT) *** (hCompBagsYn ADDED)*/
		/* *** Jay 2.14(LclInv) *** [HLclInvYn]*/
		/* *** Jay 3.01 *** [FgTag Module] */
		/*** (Jen 3.1.0_1 added HInInvGrsWtEqActual) ***/
		/*** Jay 3.1.0_1 [HValidDsgSetCd] ***/ 
		/****** Jen (3.1.2) added hBestUse ******/
		/****** Manali 3.03 added HPdModYN */
		/****** Sachin 3.3.0 (30-06-08) - [hChkVldRmLnYN added for 28. Valid RmSz Master] */
		/*** Jay 3.3(FG) [hFgIOYn] ***/
		/***** Manali 3.4.1 - 22/10/08 - Design Catalogue Module [added HDsgCatYN] *****/
		/* **** Manali 3.5.0 -  hCustomizeRmCtgExp, HMaxDsgViewRec added */
		/* **** Manali 3.6.0 - HOrdExcelRepYn added */
		/* **** Manali 3.9.1 - RfId Module ****/
		/* **** Manali 3.10.0 - Multi Price Quotation Module */
        /* 4.1.4 */
		Update Head 
		Set hCmFixPrc= ins.hCmFixPrc, hCmGldAs= ins.hCmGldAs, hCmLabAs=ins.hCmLabAs, 
			hCmIWtEqOrd = ins.hCmIWtEqOrd, hCmIWtFrOrd= ins.hCmIWtFrOrd, 
			hCmIGldRtEqOrd= ins.hCmIGldRtEqOrd, hCmDiaRtFA= ins.hCmDiaRtFA, 
			hCmCsRtFA= ins.hCmCsRtFA, HPtrYn= ins.HPtrYn, 
			hPPCYN= ins.hPPCYN, HPDCSfx= ins.HPDCSfx,
			HRndOrdSalPrc= ins.HRndOrdSalPrc, HShowPrdRmDets= ins.HShowPrdRmDets, 
			HCtbMod= ins.HCtbMod, hFluteBagYN= ins.hFluteBagYN, 
			HDTPrdPtr= ins.HDTPrdPtr, HSlvModYN = ins.HSlvModYN, HPdModYN = ins.HPdModYN,
			hLooseInv= ins.hLooseInv, hConsolidatedInv= ins.hConsolidatedInv, 
			HAutomateReturns= ins.HAutomateReturns, HQWModYN = Ins.HQWModYN, 
			HModAvlYN = Ins.HModAvlYN, HMultiCurYn= Ins.HMultiCurYn, hCompBagsYn= Ins.hCompBagsYn,
			HImpComLoc = Ins.HImpComLoc, HInRepMetLsRmCd= Ins.HInRepMetLsRmCd, HLclInvYn= Ins.HLclInvYn,
			HFgTagMod = Ins.HFgTagMod, HCustomiseOrd= Ins.HCustomiseOrd, HAutoCustmMtch= Ins.HAutoCustmMtch, 
			HInInvGrsWtEqActual= Ins.HInInvGrsWtEqActual, HValidDsgSetCd = Ins.HValidDsgSetCd, 
			hBestUse= Ins.hBestUse, hChkVldRmLnYN= Ins.hChkVldRmLnYN , HExcelImpInOrdYN=Ins.HExcelImpInOrdYN,
			HTravelExlYN=Ins.HTravelExlYN,hFgIOYn= Ins.hFgIOYn, HDsgCatYN= Ins.HDsgCatYN, 
			hCustomizeRmCtgExp=Ins.hCustomizeRmCtgExp, HMaxDsgViewRec=ins.HMaxDsgViewRec, HOrdExcelRepYn=Ins.HOrdExcelRepYn,
			HRfIdMod=ins.HRfIdMod, HMultiPrcQtMod=ins.HMultiPrcQtMod, hRtfrRtChrtYN=ins.hRtfrRtChrtYN,
			hTolQtyPctDC=ins.hTolQtyPctDC, hTolWtPctDC=ins.hTolWtPctDC, HCstRtEdtYn = ins.HCstRtEdtYn,
			hRwrkModYn = ins.hRwrkModYn    
		From Inserted ins where ins.HCoCd= @wSelfCoCd and Head.HCd= ins.HCd 
			And Head.HCoCd<> ins.HCoCd 
			And (IsNull((Select ''','+ SdCoCd + ',''' From SysDb Where SysId='EMR'),',' + Head.HCoCd + ',')) Like
					'%,' + Head.HCoCd + ',%'  
	/* Zubin 211 (hFluteBagYN= ins.hFluteBagYN added) */ 

/*      urmi 2.04-3 maintain HPtrYn same for other cocds as that of 'ZZZ'*/
/**  	Update the HPtrYn for other  Compny Codes when changed for 'ZZZ'    **/
/*		select @row=count('x') from inserted ins where ins.HCoCd= @wSelfCoCd and
			Exists(Select 'x' from Deleted del where 
				ins.HCoCd= del.HCoCd and ins.HCd= del.HCd and ins.hPtrYN<> del.hPtrYN)
		if @row> 0 
		begin
			Update Head set HPtrYn = (select H1.hPtrYn from inserted H1 where H1.HCoCd= @wSelfCoCd)
			where HCoCd<> @wSelfCoCd			
		end
*/
	End

	if @mode in ('A','C')
	Begin
		/****** Sachin 3.3.0 - Cannot Update the Check Integrity Field ******/
		Select @row=count('x') from inserted ins Where 
			Not Exists(Select 'x' From Deleted del Where del.HChkIntgty=ins.HChkIntgty)
		if @row>0 
		begin
			select @errmsg= ' Cannot Update Check Integrity Field...'
			goto ErrHndlr
		end

		/****** The HCd field in Head will always have the value 'ZSELF' ******/
		select @row=count('x') from inserted where HCd<> 'ZSELF' 
		if @row>0 
		begin
			select @errmsg= ' In Head Master Head Code Should Always Be ''ZSELF'' '
			goto ErrHndlr
		end

		/****** HCoCd = Not Blank ******/ 
		select @row=count('x') from inserted where HCoCd= ''
		if @row>0 
		begin
			select @errmsg= 'Company Code Cannot Be Blank'
			goto ErrHndlr
		end

		/****** HName = Not Blank ******/		
		select @row=count('x') from inserted where HName= ''
		if @row>0 
		begin
			select @errmsg= 'Company Name Cannot Be Blank'
			goto ErrHndlr
		end

		/*
		******  HBnkInstr  =  Not Blank ******
		select @row=count('x') from inserted where HBnkInstr= '' 
		if @row>0 
		Begin
			select @errmsg= 'Bank Instructions Cannot Be Blank'
			goto ErrHndlr
		end
		*/

		/****** HTotAs = PMCd('INVTOTAS') ******/	
		select @row= count('x') from inserted where 
			not exists (select 'x' from Param where 
				    PTyp='INVTOTAS' and PMCd= HTotAs)
		if @row>0 
		begin
			select @errmsg=' ''Invoice Total As'' Option Not Defined'
			goto ErrHndlr
		end

		/****** HCmGldAs = PMCd('GLDAS') ******/	
		/*** (Jen 2.14) ***/ 
		select @row= count('x') from inserted where hCmGldAs<> '' and 
			not exists (select 'x' from Param where PTyp='GLDAS' and PMCd= hCmGldAs)

		/* select @row= count('x') from inserted where hCmGldAs<> '' and 
			not exists (select 'x' from Param where PTyp='GLDAS' and PMCd= hCmGldAs 
			and not (',' + PDesc225 + ',' like '%,G,%' Or ',' + PDesc225 + ',' like '%,P,%' Or ',' + PDesc225 + ',' like '%,S,%') 
		) */
		/*** (Jen 2.14) ***/ 

		/*** (Bef 2.14) 
		select @row= count('x') from inserted where 
				not exists (select 'x' from Param where PTyp='GLDAS' and PMCd= hCmGldAs)
		(Bef 2.14) ***/
		if @row> 0 
		begin
			select @errmsg= 'Gold As Value Not Defined'
			goto ErrHndlr
		end



		/* ****** Manali 3.9.1 - Rate Round Off Option For Order ****** */
		select @row= count('x') from inserted Ins where HOrdRtRndOffRmCtg <> '' 
			and	not exists (select 'x' from Param where PTyp='CPYRT' and PMCd= HOrdRtRndOffRmCtg)
		if @row> 0 
		begin
			select @errmsg= 'RmCtg Combination For Order Rate Round Off Not Defined'
			goto ErrHndlr
		end

		/* ****** Manali 3.9.1 - Rate Round Off Option For Order ****** */
		select @row= count('x') from inserted Ins where HOrdRtRndOffRmCtg <> '' 
			and	exists (select 'x' from Param where PTyp='CPYRT' and PMCd= HOrdRtRndOffRmCtg
			  and (','+PDesc225+',' LIKE '%,G,%' or ','+PDesc225+',' LIKE '%,P,%'  
              or ','+PDesc225+',' LIKE '%,S,%' or ','+PDesc225+',' LIKE '%,L,%' ))			
		if @row> 0 
		begin
			select @errmsg= '''G'', ''P'', ''S'', ''L'' Not Allowed in RmCtg Combination For Order Rate Round Off'
			goto ErrHndlr
		end
		
		/* ****** Manali 3.9.1 - RfId Module in Emr - Y/N ****** */
		select @row= count('x') from inserted where 
				not exists (select 'x' from Param where PTyp= 'YN' and PMCd= HRfIdMod)
