  select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and OmLine<>'' and  
   not exists (select 'x' from vParam where vPCoCd= OmCoCd and vPTyp= 'LINE' and vPMCd= OmLine and vPMCd<> 'ZZZ')  
  if @row> 0     
  begin  
   select @errmsg= 'Line Not Defined/ Line Cannot Be ''ZZZ'' '  
   goto ErrHndlr  
  end  
  
  /******  OmWDiaAvlblDt And OmHDiaAvlblDt <>  '01/01/1980'  or  '01/01/1900'  (The dates '01/01/1980'  and  '01/01/1900'  are considered as blank) ******/  
  /* Current Partition */  
  select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and (OmWDiaAvlblDt in('01/01/1980', '01/01/1900') or   
   OmHDiaAvlblDt in('01/01/1980', '01/01/1900'))  
  if @row> 0   
  begin  
   select @errmsg= 'Wax/ Hand Set Diamond Availability Date Cannot Be Blank'  
   goto ErrHndlr  
  end  
  
  /* ****** Manali 3.03 02/07/08 - OmLkUpRmRt ****** */  
  Select @row= count('x') from inserted Ins where Ins.OmLkUpRmRt <> '' and   
   Ins.OmLkUpRmRt <> IsNull((Select Del.OmLkUpRmRt From Deleted Del Where   
    Ins.OmIdNo=Del.OmIdNo and Ins.OmCoCd = Del.OmCoCd And Ins.OmTc = Del.OmTc And Ins.OmYy = Del.OmYy And  
    Ins.OmChr = Del.OmChr And Ins.OmNo = Del.OmNo And Ins.OmPrtKey=Del.OmPrtKey), '') and       not exists(Select 'x' from CustMst where CmCtg='P' and CmCd=Ins.OmLkUpRmRt and CmValidYN='Y')  
  If @row > 0   
  Begin   
   Select @errmsg= 'Invalid Rm Rate Look Up Customer'  
   goto ErrHndlr  
  End  
  /* ****** Manali 3.03 02/07/08 - OmLkUpRmRt ****** */  
  
  /* ****** Manali 3.03 02/07/08 - OmLkUpLabRt ****** */  
  Select @row= count('x') from inserted Ins where Ins.OmLkUpLabRt <> '' and   
   Ins.OmLkUpLabRt <> IsNull((Select Del.OmLkUpLabRt From Deleted Del Where   
    Ins.OmIdNo=Del.OmIdNo and Ins.OmCoCd = Del.OmCoCd And Ins.OmTc = Del.OmTc And Ins.OmYy = Del.OmYy And  
    Ins.OmChr = Del.OmChr And Ins.OmNo = Del.OmNo And Ins.OmPrtKey=Del.OmPrtKey), '') and       not exists(Select 'x' from CustMst where CmCtg='P' and CmCd=Ins.OmLkUpLabRt and CmValidYN='Y')  
  If @row > 0   
  Begin   
   Select @errmsg= 'Invalid Labour Rate Look Up Customer'  
   goto ErrHndlr  
  End  
  /* ****** Manali 3.03 02/07/08 - OmLkUpLabRt ****** */  
  
  /* ****** Manali 3.03 02/07/08 - OmLkUpMetLs ****** */  
  Select @row= count('x') from inserted Ins where Ins.OmLkUpMetLs <> '' and   
   Ins.OmLkUpMetLs <> IsNull((Select Del.OmLkUpMetLs From Deleted Del Where   
    Ins.OmIdNo=Del.OmIdNo and Ins.OmCoCd = Del.OmCoCd And Ins.OmTc = Del.OmTc And Ins.OmYy = Del.OmYy And  
    Ins.OmChr = Del.OmChr And Ins.OmNo = Del.OmNo And Ins.OmPrtKey=Del.OmPrtKey), '') and       not exists(Select 'x' from CustMst where CmCtg='P' and CmCd=Ins.OmLkUpMetLs and CmValidYN='Y')  
  If @row > 0   
  Begin   
   Select @errmsg= 'Invalid Metal Loss Look Up Customer'  
  goto ErrHndlr  
  End  
  /* ****** Manali 3.03 02/07/08 - OmLkUpMetLs ****** */    
  
  /* *** Manali 3.03 - 02/07/08 - OmLkUpRmRt, OmLkUpLabRt, OmLkUpMetLs cannot edit when dsg rec exists **** */  
  select @row= count('x') from inserted ins where ins.OmPrtKey=@wCurrPrtn and  
   not exists (select 'x' from deleted del where ins.OmPrtKey=del.OmPrtKey and ins.OmIdNo=del.OmIdNo   
    and ins.OmTc= del.OmTc and ins.OmYy= del.OmYy and ins.OmChr= del.OmChr and ins.OmNo= del.OmNo   
    and (ins.OmLkUpRmRt = del.OmLkUpRmRt Or ins.OmLkUpLabRt= del.OmLkUpLabRt Or ins.OmLkUpMetLs = del.OmLkUpMetLs))  
   and exists(Select 'x' from OrdDsg where OdPrtKey=OmPrtKey and OdOmIdNo=OmIdNo and OdCoCd= OmCoCd   
    and OdTc= OmTc and OdYy= OmYy and OdChr= OmChr and OdNo= OmNo)    
  if @row> 0   
  begin  
   Select @ErrMsg= 'Cannot Change Rm Rate/Lab Rate/Metal Loss Lookup Customer When Designs Exist'  
   goto ErrHndlr  
  end  
  /* *** Manali 3.03 - 02/07/08 - OmLkUpRmRt, OmLkUpLabRt, OmLkUpMetLs cannot edit when dsg rec exists **** */  
  
  
  /*** (Jen 2.13) ***/  
  /* Current Partition */  
  select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and  
    exists (select 'x' from Param where PTyp= 'TC' and PMCd= OmTc and PSCd= '' and PValue not in ('SO'))   
   and (OmReYy<> '' Or OmReChr<> '' Or OmReNo<> 0)   
  if @row> 0  
  begin  
   select @errmsg= 'Return Memo Voucher Can Be Specified Only For Sales Orders'   
   goto ErrHndlr   
  end  
  
  /* Current Partition */  
  select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and (OmReYy<> '' Or OmReChr<> '' Or OmReNo<> 0) and   
   not exists (select 'x' from RetMem where ReCoCd= OmCoCd and ReYy= OmReYy and ReChr= OmReChr   
     and ReNo= OmReNo)   
  if @row> 0   
  begin  
   select @errmsg= 'Return Memo Voucher Not Defined'  
   goto ErrHndlr  
  end  
  
  /* Current Partition */  
  select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and (OmReYy<> '' Or OmReChr<> '' Or OmReNo<> 0) and   
   not exists (select 'x' from RetMem where ReCoCd= OmCoCd and ReYy= OmReYy and ReChr= OmReChr   
     and ReNo= OmReNo and OmCmCurCd= (Select CmCurCd from CustMst where CmCtg= 'C'   
     and CmCd= ReCmCd))   
  if @row> 0   
  begin  
   select @errmsg= 'Return Memo Voucher Currency Not Matching With Order Currency'  
   goto ErrHndlr  
  end  
  
  /*** A Return Memo Voucher Cannot Be Used Only In One Order Voucher ***/  
  /* Current Partition */  
  select @row= count('x') from inserted ins where OmPrtKey=@wCurrPrtn and (OmReYy<> '' Or OmReChr<> '' Or OmReNo<> 0) and   
   exists (select 'x' from OrdMst Om where Om.OmCoCd= ins.OmCoCd and Om.OmReYy= ins.OmReYy   
    and Om.OmReChr= ins.OmReChr and Om.OmReNo= ins.OmReNo   
    and (ins.OmIdNo<>Om.OmIdNo and ins.OmCoCd <> Om.OmCoCd or ins.OmTc<> Om.OmTc or ins.OmYy<> Om.OmYy   
     or ins.OmChr<> Om.OmChr or ins.OmNo<> Om.OmNo) )   
  if @row> 0   
  begin  
   select @errmsg= 'Return Memo Voucher Already Used In Another Order'  
   goto ErrHndlr  
  end  
  /*** (Jen 2.13) ***/  
  
  
/*  ###  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ###  */  
  /******  OmHCtCd  =  Blank or CmCd from CustMst (CmCtg= 'T')  ******/  
  /* Current Partition */   
  select @row= count('x') from Inserted Ins Where OmPrtKey=@wCurrPrtn and Ins.OmHCtCd <> '' And  
   Ins.OmHCtCd <> IsNull((Select Del.OmHCtCd From Deleted Del Where Ins.OmIdNo=Del.OmIdNo and  
    Ins.OmCoCd = Del.OmCoCd And Ins.OmTc = Del.OmTc And Ins.OmYy = Del.OmYy And   
    Ins.OmChr = Del.OmChr And Ins.OmNo = Del.OmNo and Ins.OmPrtKey=Del.OmPrtKey), '')  And   
   Not Exists (select 'x' from CustMst where CmCtg= 'T' And CmCd= Ins.OmHCtCd And CmValidYN = 'Y')   
  if @row> 0  
  begin  
   select @errmsg= 'Contractor Code Not Defined / Invalid'  
   goto ErrHndlr  
  end  
  
  /******  OmLockYN =  valid  PMCd ('YN')  ******/  
  /* Current Partition */  
  select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and  
   Not Exists (select 'x' from Param where PTyp= 'YN' and PmCd= OmLockYN)   
  if @row> 0  
  begin  
   select @errmsg= 'Order/PDC/Quotation Lock (Y/N) Not Defined'  
   goto ErrHndlr  
  end  
