*/  
 /****** If OmChr=’WEB’ then OmCrmYy= Valid (PTyp=’YY’)******/  
  /* Current Partition */  
  select @row= count('x') from Inserted where OmPrtKey=@wCurrPrtn and (OmChr='WEB' or OmCrmYy<>'') and   
   Not Exists(Select 'x' From Param where PTyp='YY' and PMCd=OmCrmYy)  
  if @row> 0  
  begin  
   select @errmsg= 'Yy Not Defined'  
   goto ErrHndlr  
  end  
  
 /****** If OmChr=’WEB’ then OmCrmChr= Valid (cPTyp=’CRMChr’)******/  
  /* Current Partition */  
  select @row= count('x') from Inserted where OmPrtKey=@wCurrPrtn and (OmChr='WEB' or OmCrmChr<>'') and    
   Not Exists(Select 'x' From cParam where cPTyp='CRMCHR' and cPMCd=OmCrmChr)  
  if @row> 0  
  begin  
   select @errmsg= 'Crm Chr Not Defined'  
   goto ErrHndlr  
  end  
   
 /****** If OmChr=’WEB’ then OmCrmChr= Valid (cPTyp=’CRMChr’)******/  
  /* Current Partition */  
  select @row= count('x') from Inserted where OmPrtKey=@wCurrPrtn and OmChr='WEB' and OmCrmNo=0  
  if @row> 0  
  begin  
   select @errmsg= 'Crm Voucher No Cannot be Zero '  
   goto ErrHndlr  
  end  
 /****** On Insert of  OmChr=’WEB’     
  If    cPMCd=OmCrmChr  where cPTyp=’WEBCHR’ and cPValue=’Y’ (Usr Running Sr =’Y’)  then   
  Check OmCrmYy+OmCrmChr+OmCrmNo is Unique  
   If   cPTyp=’CRMCHR’ and cPValue=’N’ (cParam) then   
     Check OmTc+OmCrmYy+OmCrmChr+OmCmCd+OmCrmNo is Unique  
 ******/  
  
 /* Crm Voucher No uniqueness is on complete partition */   
 select @row= count('x') from Inserted ins where OmPrtKey=@wCurrPrtn and OmChr='WEB' and   
  (Select Count('x') From OrdMst Om Join cParam on cPTyp='CRMCHR' and cPMCd=OmCrmChr   and cPSCd=''  
   where  Om.OmCmCd=(Case when cPValue='Y' Then Om.OmCmCd Else Ins.OmCmCd End)  and   
    ins.OmTc=Om.OmTc and ins.OmCrmYy=Om.OmCrmYy  
    and ins.OmCrmChr=Om.OmCrmChr and ins.OmCrmNo=Om.OmCrmNo)>1  
  if @row> 0  
  begin  
   select @errmsg= 'Crm Voucher No. already exists'  
   goto ErrHndlr  
  end  
  
 /****** if OmTcTyp='MF' then OmChr='WEB' ******/  
  /* Current Partition */  
  select @row= count('x') from inserted ins where OmPrtKey=@wCurrPrtn and OmChr<>'WEB' and    
   (select PValue  from Param where PTyp='TC' and PMCd=OmTc and PSCd='')='MF'   
  if @row> 0  
  begin  
   select @errmsg= 'My Favourite is Applicable for Crm i.e OmChr=''WEB'''  
   goto ErrHndlr  
  end  
  
 /****** One 'MF'Permitted per CrmYy/CrmChr******/  
  /* Current Partition */  
  select @row= count('x') from inserted ins where OmPrtKey=@wCurrPrtn and  
   (select PValue  from Param where PTyp='TC' and PMCd=OmTc and PSCd='')='MF' and   
   (Select count('x') From OrdMst Om where Om.OmTc=ins.OmTc and Om.OmCrmYY=ins.omCrmYy and   
     Om.OmCrmChr=ins.OmCrmChr and Om.OmCmCd=ins.OmCmCd)>1  
  if @row> 0  
  begin  
   select @errmsg= 'Only one My Favourite Permitted for Crm Chr and Yy Combination for a Customer'  
   goto ErrHndlr  
  end  
  
 /******  OmPODt, OmPONO cannot be blank for OmTcTyp='SO' and OmChr='WEB' **Crm**212**30/12/05 ******/    
  /* Current Partition */  
  Select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and (OmPONo='' or OmPoDt='01/01/80') and  
   OmChr='WEB' and (select PValue  from Param where PTyp='TC' and PMCd=OmTc and PSCd='') ='SO'  
  If @row> 0   
  Begin  
   Select @errmsg= 'PoNo,PoDt Cannot Be Blank for Web Orders'  
   Goto ErrHndlr  
  End  
  
 /* CRM Check included in EMR in 2.14.0 Next */  
 /****** Unique PO Number will go on the complete partition ******/    
  Select @row= Count('x') From Inserted Ins   
    Where OmPrtKey=@wCurrPrtn and (Select Count('x') From OrdMst Om Where Om.OmCmCd=Ins.OmCmCd and Om.OmTc=Ins.OmTc and   
     Om.OmPoNo=ins.OmPoNo)> 1   
    And Exists (Select 'x' From SysDb Where SysId='CRM')   
    If @row> 0   
    Begin  
      Select @ErrMsg= 'Po No Should Be Unique for a Customer'  
      Goto ErrHndlr  
    End  
 /* CRM Check included in EMR in 2.14.0 Next */  
/*** Jay 3.3(FG) ***/  
  If exists (Select 'x' from Inserted   
   where exists (Select 'x' from Param where PTyp= 'TC' and PValue= 'FG' and PMCd= OmTc) )  
  Begin  
   /*** Jay 3.3(FG)***/  
   /********** If Tc in 'fin', 'fot' then OmFrDmLoc, omFrRmDc, OmTODmLoc, OmToDmDc should be blank *************/  
   /* Current Partition */  
   Select @Row= Count('x') From Inserted Ins Where OmPrtKEy=@wCurrPrtn and  
    (OmFrDmLoc= '' or OmFrDmDc= '' or OmToDmLoc= '' or OmToDmDc= '')  
     If @Row> 0  
   begin  
    Select @ErrMsg= 'From/To Dm Loc, From/To Dm DC Should Not Be Blank'  
      GoTo ErrHndlr  
   end  
  
   /*** Jay 3.3(FG) -Current Partition ***/  
   select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and    
    not (select count('x') from Param where PTyp='DC' and (PMCd=OmFrDmDc or PMCd=OmToDmDc) and PSCd='') =2    
   if @row> 0    
   Begin    
    select @errmsg= 'Invalid OmFrDmDc or OmToDmDc'  
    goto ErrHndlr    
   end     
  
   /* Current Partition */  
   select @row= count('x') from inserted Ins where OmPRtKey=@wCurrPrtn and   
     Ins.OmFrDmLoc = Ins.OmToDmLoc and (Ins.OmFrDmLoc <> '' or  
     Ins.OmToDmLoc <> '')  
     if @row>0  
     begin  
       select @errmsg= 'To Loc and From Loc cannot be same'  
       goto ErrHndlr  
     end  
  
   /*** Jay 3.3(FG) - Current Partition ***/  
   select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and    
   exists (select 'x' from Loc where LocCoCd= OmCocd and LocTyp in ('F','XS')  
      and LocCd=OmFrDmLoc and LocCd=OmToDmLoc and LocPrntYn= 'N'  And LocValidYN='Y')   
   if @row> 0    
   Begin    
    select @errmsg= 'Invalid Sales Location Code/ Not Defined'    
    goto ErrHndlr    
   end       
   /****** OmFrDmLoc & OmToDmLoc both should not be of LocTyp= 'F'/'XS' **********/  
   /* Current Partition */  
   Select @Row=Count('x') From Inserted Ins Where OmPrtKey=@wCurrPrtn and    
     (Exists (Select 'x' From Loc where LocCoCd= Ins.OmCoCd and LocTyp= 'F' and LocCd = Ins.OmFrDmLoc)  
    and Exists (Select 'x' From Loc where LocCoCd= Ins.OmCoCd and LocTyp= 'F' and LocCd = Ins.OmToDmLoc))  
    or (Exists (Select 'x' From Loc where LocCoCd= Ins.OmCoCd and LocTyp= 'XS' and LocCd = Ins.OmFrDmLoc)  
    and Exists (Select 'x' From Loc where LocCoCd= Ins.OmCoCd and LocTyp= 'XS' and LocCd = Ins.OmToDmLoc))  
     If @Row>0  
   begin  
    Select @ErrMsg= 'Both From & To Locs Should Not Be the Same Location Type ''F'' Or ''XS'' '  
    GoTo ErrHndlr  
   end  
  
   /****** InFrRmLoc or InToRmLoc Should Have LocTyp= 'XS' ********/  
   /* Current Partition */  
   /*** Jay 3.3(FG) ***/  
   Select @Row= Count('x') From Inserted Ins where OmPrtKey=@wCurrPrtn   
    and Not Exists (Select 'x' From Loc where LocCoCd = OmCoCd   
     and LocTyp= 'XS' and (LocCd= OmFrDmLoc or LocCd = OmToDmLoc))  
     If @Row> 0  
   begin  
    Select @ErrMsg= 'Atleast One DM Loc Must Be Of Type ''XS'' '  
      GoTo ErrHndlr  
   end  
  
   /****** InFrRmLoc or IrToRmLoc Should Have LocTyp= 'F' ********/  
   /* Current Partition */  
   /*** Jay 3.3(FG) ***/  
   Select @Row= Count('x') From Inserted Ins where OmPrtKey=@wCurrPrtn   
    and Not Exists (Select 'x' From Loc where LocCoCd = OmCoCd   
     and LocTyp= 'F' and (LocCd= OmFrDmLoc or LocCd = OmToDmLoc))  
       If @Row>0  
   begin  
    Select @ErrMsg= 'Atleast One DM Loc Must Be Of Type ''F'' '  
      GoTo ErrHndlr  
   end  
  
   /****** RM Wt/ Qty Can Be Issued From Locations Of Type 'F' Only in fot********/  
   /* Current Partition */  
   /*** Jay 3.3(FG) ***/  
   Select @Row= Count('x') From Inserted Ins where OmPrtKey=@wCurrPrtn and  
    OmTc= 'FOT' and Not Exists (Select 'x' From Loc where LocCoCd = OmCoCd and   
     LocTyp= 'F' and ((LocCd= OmFrDmLoc and OmFrDmDc= 'C') or   
        (LocCd= OmToDmLoc and OmToDmDc= 'C')                ))  
       If @Row> 0  
   begin  
    Select @ErrMsg= 'Qty Can Be Issued From Locations Of Type ''F'' Only'  
      GoTo ErrHndlr  
   end  
   /****** RM Wt/ Qty Can Be Issued From Locations Of Type 'XS' Only in FIN ********/  
   /* Current Partition */  
   /*** Jay 3.3(FG) ***/  
   Select @Row= Count('x') From Inserted Ins where OmPrtKey=@wCurrPrtn and  
    OmTc= 'FIN' and Not Exists (Select 'x' From Loc where LocCoCd = OmCoCd and   
     LocTyp= 'XS' and ((LocCd= OmFrDmLoc and OmFrDmDc= 'C') or   
        (LocCd= OmToDmLoc and OmToDmDc= 'C')                ))  
       If @Row> 0  
   begin  
    Select @ErrMsg= 'Qty Can Be Issued From Locations Of Type ''XS'' Only'  
      GoTo ErrHndlr  
   end    
  End     
  /*** Jay 3.3(FG) ***/  
  
  /* Manali Trading Module */  
  If exists (Select 'x' from Inserted   
   where exists (Select 'x' from Param where PTyp= 'TC' and PValue= 'JT' and PMCd= OmTc) )  
  Begin  
   /* Current Partition */   
   Select @Row= Count('x') From Inserted Ins Where OmPrtKEy=@wCurrPrtn and (OmFrDmLoc= '' or OmToDmLoc= '')  
    and exists(Select 'x' from TcMst Where TmCoCd=OmCoCd and TmTc=OmTc and TmLocTypFr<>'' and TmLocTypTo<>'')  
     If @Row> 0  
   begin  
    Select @ErrMsg= 'From/To Dm Loc Should Not Be Blank'  
      GoTo ErrHndlr  
   end  
  
   select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and    
    not exists(Select 'x' from TcMst Where TmCoCd=OmCoCd and TmTc=OmTc   
       and TmFrDmDc=OmFrDmDc and TmToDmDc=OmToDmDc)   
   if @row> 0    
   Begin    
    select @errmsg= 'Invalid OmFrDmDc or OmToDmDc'  
    goto ErrHndlr    
   end     
  
   /* Current Partition */  
   select @row= count('x') from inserted Ins where OmPRtKey=@wCurrPrtn and   
     Ins.OmFrDmLoc = Ins.OmToDmLoc and (Ins.OmFrDmLoc <> '' or  
     Ins.OmToDmLoc <> '')  
     if @row>0  
     begin  
       select @errmsg= 'To Loc and From Loc cannot be same'  
       goto ErrHndlr  
     end  
  
   /*** Jay 3.3(FG) - Current Partition ***/  
   select @row= count('x') from inserted Join TcMst On TmCoCd=OmCoCd and TmTc=OmTc and TmLocTypFr<>''  
    where OmPrtKey=@wCurrPrtn and  
    not exists (select 'x' from Loc where LocCoCd= OmCoCd and LocTyp =TmLocTypFr  
       and LocCd=OmFrDmLoc and LocPrntYn= 'N'  And LocValidYN='Y')   
   if @row> 0    
   Begin    
    select @errmsg= 'Invalid From Design Location Code/ Not Defined'    
    goto ErrHndlr    
   end     
  
  
   select @row= count('x') from inserted Join TcMst On TmCoCd=OmCoCd and TmTc=OmTc and TmLocTypTo<>''  
    where OmPrtKey=@wCurrPrtn and  
    not exists (select 'x' from Loc where LocCoCd= OmCoCd and LocTyp =TmLocTypTo  
       and LocCd=OmToDmLoc and LocPrntYn= 'N'  And LocValidYN='Y')   
   if @row> 0    
   Begin    
    select @errmsg= 'Invalid To Design Location Code/ Not Defined'    
    goto ErrHndlr    
   end  
  
   If exists (Select 'x' from Inserted Where OmTc='JCN' )  
   Begin   
    Select @Row= Count('x') From Inserted Ins Where OmPrtKEy=@wCurrPrtn and  
     (OmFrRmLoc= '' or OmFrRmDc= '' or OmToRmLoc= '' or OmToRmDc= '')  
      If @Row> 0  
    begin  
     Select @ErrMsg= 'From/To Rm Loc, From/To Rm DC Should Not Be Blank'  
       GoTo ErrHndlr  
    end  
  
    select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and    
     not (select count('x') from Param where PTyp='DC' and (PMCd=OmFrRmDc or PMCd=OmToRmDc) and PSCd='') =2    
    if @row> 0    
    Begin    
     select @errmsg= 'Invalid OmFrRmDc or OmToRmDc'  
     goto ErrHndlr    
    end     
  
    select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and not(OmFrRmDc='C' and OmToRmDc='D')   
    if @row> 0    
    Begin    
     select @errmsg= 'Invalid OmFrRmDc or OmToRmDc'  
     goto ErrHndlr    
    end     
  
  
    select @row= count('x') from inserted Ins where OmPRtKey=@wCurrPrtn and   
      Ins.OmFrRmLoc = Ins.OmToRmLoc and (Ins.OmFrRmLoc <> '' or Ins.OmToRmLoc <> '')  
      if @row>0  
      begin  
        select @errmsg= 'To Rm Loc and From Rm Loc cannot be same'  
        goto ErrHndlr  
      end  
  
    select @row= count('x') from inserted where OmPrtKey=@wCurrPrtn and OmFrRmLoc<>'FG'  
    if @row> 0    
    Begin    
     select @errmsg= 'From Rm Location Should Be ''FG'''    
     goto ErrHndlr    
    end     
  
  
    select @row= count('x') from Inserted where OmPrtKey=@wCurrPrtn and OmToRmLoc<>'XD'  
    if @row> 0    
    Begin    
     select @errmsg= 'To Rm Location Should Be ''XD'''    
     goto ErrHndlr    
    end     
   End     
     
   If Not exists (Select 'x' from Inserted Where OmTc='JCN' )  
   Begin   
    Select @Row= Count('x') From Inserted Ins Where OmPrtKEy=@wCurrPrtn and  
     Not(OmFrRmLoc= '' And OmFrRmDc= '' And OmToRmLoc= '' And OmToRmDc= '')  
      If @Row> 0  
    begin  
     Select @ErrMsg= 'From/To Rm Loc, From/To Rm DC Should Be Blank'  
       GoTo ErrHndlr  
    end  
   End  
  End     
  /* Manali Trading Module */    
  
 /*** Geeta ***/  
 End  
 if @mode = 'D'   
 Begin  
  /****** Cannot Delete If Record Exists In OrdDsg Table ******/  
  /* Sessionproperty commented by Geeta in ver 2.14.0 */  
  /* Current Partition only */  
  select @row= count('x') from deleted, OrdDsg where OmPrtKey=@wCurrPrtn and OmIdNo=OdOmIdNo and OmCoCd= OdCoCd  
   and OmTc= OdTc and OmYy= OdYy and OmChr= OdChr and OmNo= OdNo and OmPrtKey=OdPrtKey /* and  
   (Not (OmAckYN='Y' and OmCoCd='WEB' and @wSysDb='WEB' and SessionProperty('replication_agent')= 1)  )  */  
  if @row> 0   
  begin  
   select @errmsg= 'Cannot Delete Order As Order Design Records Exist'  
   goto ErrHndlr  
  end  
  
  /*** (Jen 2.13) ***/  
  /****** Whenever the OrdMst record where OmReNo> 0 is deleted, delete records from the OrdDsg table ******/  
  /* Delete OrdDsg From deleted, OrdDsg where OmReNo> 0 and OmCoCd = OdCoCd   
   and OmTc = OdTc and OmYy = OdYy and OmChr = OdChr and OmNo = OdNo    
  */  
  /*** (Jen 2.13) ***/  
  
  /****** Whenever the OrdMst record is deleted, delete records from the OrdTgt table ******/  
  Delete OrdTgt From deleted, OrdTgt where OmCoCd = OtCoCd   
   and OmTc = OtTc and OmYy = OtYy and OmChr = OtChr and OmNo = OtNo    
  
  /****** Whenever the OrdMst record is deleted, delete records from the OrdScop table ******/  
  Delete OrdScop From deleted, OrdScop where OsCoCd= OmCoCd   
   and OsTc= OmTc and OsYy= OmYy and OsChr= OmChr and OsNo= OmNo   
  
  /****** Manali Trading Module ******/  
  Delete InvHd From Deleted, InvHd Where   
   Exists(Select 'x' from Param Where PTyp='TC' and PMCd=OmTc and PValue='JT')   
   and InCoCd=OmCoCd and InTc=OmTc and InYY=OmYY and InChr=OmChr and InNo=OmNo  
  
  /*******Geeta****Crm***2.12****15/12/06***************************************************/  
  /*****************If OmSubmitted =’Y’ then cannot Delete  ******/  
  /* Current Partition */  
  select @row= count('x') from deleted where OmPrtKey=@wCurrPrtn and (OmSubmitYN in ('Y','') and OmCrmNo<>0)  
    and not (OmCoCd='WEB' and OmAckYN ='Y')  
  if @row> 0  
  begin  
   select @errmsg= 'Cannot Delete a Submitted Order'  
   goto ErrHndlr  
  end  
  
 End  
  
return  
ErrHndlr:  
 begin  
  select @errmsg='|'+@errmsg  
  raiserror(@errmsg,16,1)  
  rollback transaction   
 end  
end  

GOGO

ALTER TRIGGER [dbo].[RmRt_INUPDL] ON [dbo].[RmRt] 
         FOR INSERT,UPDATE,DELETE NOT FOR REPLICATION
AS
BEGIN
	/* Trigger Version 3.8.0 */
 	DECLARE @ROW INT
 	DECLARE @mode char(1)
 	DECLARE @errmsg varchar(255)
	DECLARE @SYS VARCHAR(5)
	DECLARE @ReplAgt BIT  
	DECLARE @wSelfCd VARCHAR(8)
	DECLARE @wCurrPrtn VARCHAR(1)

 	IF @@ROWCOUNT=0
	  	RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'RmRt')
		RETURN

	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '') 

	select @mode=case (select count('x') from inserted) when 0 then 'D'
       		           else
   			  case (select count('x') from deleted) when 0 then 'A' else 'C' end
       		           end

	set @wSelfCd = 'ZSELF'	
	Set @wCurrPrtn = 'C'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode ='A' and @ReplAgt<>1
	begin
		Select @row=count('x') From Inserted Where RrPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Records of Previous Partition'
			goto ErrHndlr
		end
	End

	if @mode ='C' and @ReplAgt<>1
	begin
		Select @row=count('x') From Inserted Where RrPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	end 

	if @mode ='D' and @ReplAgt<>1
	begin
		Select @row=count('x') From Deleted Where RrPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records of Previous Partition'
			goto ErrHndlr
		end
	end 

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */

	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete if Crm database /Emr database with sdMst='N' ****/
		if @mode in ('A','C','D')
		Begin 
		If   exists ( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  or  
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB' ) 
			Begin 
				select @errmsg= 'Cannot Insert /Update /Delete ' 
				goto ErrHndlr 
			end 
		End 
	End

 	/******** Records Of Only One Typ Can Be Inserted At A Time ********/
	select @Row= Count(distinct(RrTcTyp)) from inserted
	If @Row > 1
	Begin
		Select @ErrMsg= 'Records Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/******** Records Of Only One Typ Can Be Deleted At A Time ********/
	select @Row= Count(distinct(RrTcTyp)) from deleted
	If @Row > 1
	Begin
		Select @ErrMsg= 'Records Of Only One Type Can Be Acted On'
		GoTo ErrHndlr
	End

	/******** RM Rate TcType Not Defined ********/
	select @row= count('x') from inserted where
  		not exists (select 'x' from Param where PTyp= 'RRTCTYP' and PMCd= RrTcTyp)
 	if @row> 0
 	Begin
  		select @errmsg= 'Tc Type Not Defined'
  		goto ErrHndlr
 	end

	/******  If RrTcTyp = 'INL'	then  RrCtg  =  Blank	else  RrCtg  =  PMCd ('RMCTG')  ******/
/* Zubin 212 ('MUP' added) */
	/***Crm*212*Geeta*****/
	/* ****** Sachin 3.3.0 (24-06-08) - [14. Cost Markup in Invoicing] ****** */
	/* bhavna added CHN */
 	select @row= count('x') from inserted where RrTcTyp Not In ('INL', 'MUP', 'FRT', 'IML','WXT','WCT','CHN') and
  		not exists (select 'x' from Param where PTyp= 'RMCTG' and PMCd= RrCtg)
 	if @row> 0
 	Begin
  		select @errmsg= 'Raw Material Category Not Defined'
  		goto ErrHndlr
 	end

	select @row= count('x') from inserted where RrTcTyp IN ('INL','IML') and RrCtg<> ''
 	if @row>0
 	Begin
  		select @errmsg= 'Raw Material Category Should Be Blank'
  		goto ErrHndlr
 	end
 	
	
	/****** If TcStr records does not exist for an RrTcTyp & RrCtg combination then do not allow the user to add such a record ******/
	select @row= count('x') from inserted where not exists(Select 'x' from TcStr 
		where TsTbl= 'RmRt' and TsTyp= RrTcTyp and TsSTyp= RrCtg )
 	if @row>0
 	Begin
  		select @errmsg= 'TcType and RmCtg Combination Not Defined In Tc Structure'
  		goto ErrHndlr
 	end

	/* *** Jay 3.1.3 [CRP] */
	select @row= count('x') from inserted where RrTcTyp= 'CRP' and
		exists ( select 'x' From SysDb where SysId='CRM' and SysDb ='WEB')
	if @row>0
 	Begin 
		select @errmsg= 'Cannot Insert /Update /Delete For CRM' 
		goto ErrHndlr 
	end 
	/* *** Jay 3.1.3 [CRP] */

	/*bhavna removed check for CHN*/
	/******  RrSCtg  =  Blank  or  PSCd ('RMCTG', RrCtg)  ******/
	select @row= count('x') from inserted where RrSCtg <> '' and RrTcTyp <> 'CHN' and 
  		not exists (select 'x' from Param where
       		PTyp= 'RMSCTG' and PMCd= RrCtg and PSCd= RrSCtg)
 	if @row>0
 	Begin
  		select @errmsg= 'Raw Material Sub Category Not Defined'
  		goto ErrHndlr
 	end

	/*bhavna removed check for CHN*/
	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrSCtg') = 'N' 	then 	RrSCtg  =  Not Blank  ******/
	select @row= count('x') from inserted where RrSCtg= '' and RrTcTyp <> 'CHN' and
  		(Select TsBlank from TcStr where TsTbl= 'RmRt' and TsTyp= RrTcTyp 
			and TsSTyp=RrCtg and TsIdName= 'RrSCtg') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Raw Material Sub Category Cannot Be Blank'
  		goto ErrHndlr
 	end

	/******  If RrTcTyp= 'PTR' then if the 'RATEBY' option of the RmSCtg in Param is 'P' then insert not allowed ******/
	select @row= count('x') from inserted where RrTcTyp= 'PTR' and 
  		exists (select 'x' from Param where 
       		PTyp= 'RMSCTG' and PMCd= RrCtg and PSCd= RrSCtg and PValue= 'P')
 	if @row> 0
 	Begin
  		select @errmsg= 'Cannot Enter This Record As RateBy Option For This Rm SubCtg Is Already Pointer'
  		goto ErrHndlr
 	end

	/*************Geeta**Emr206********05/04/04***************/	
	/******  If RrTcTyp= 'PTR'  and if a record exists for RrTcTyp='BS' for the same
			Custome,RmCtg,RmSCtg then insert not allowed  visa versa******/
	select @row= count('x') from inserted ins where RrTcTyp in ('PTR','BS') and 
  		exists (select 'x' from RmRt Rr where 
       		Rr.RrTcTyp = case when ins.RrTcTyp='PTR' then 'BS' else 'PTR' end and Rr.RrCmCtg='C' and Rr.RrCmCd=ins.RrCmCd and 
		Rr.RrCmCurCd='' and Rr.RrCtg=ins.RrCtg and
		Rr.RrSctg=ins.RrSctg and Rr.RrSTWGrp='' and  Rr.RrCd='' and Rr.RrDmCtg='' and Rr.RrDmCd='' and 
		Rr.RrLsCtg=''  and  Rr.RrLabMCd='' and  Rr.RrFrLn='' and Rr.RrToLn='')
 	if @row> 0
 	Begin
  		select @errmsg= 'Both (BS/PTR) charts cannot be defined for the same customer ,RmCtg,RmSCtg'
  		goto ErrHndlr
 	end

	/******  If RrTcTyp= 'BS' then if the 'RATEBY' option of the RmSCtg in Param is 'BS' then insert not allowed ******/
	select @row= count('x') from inserted where RrTcTyp= 'BS' and 
  		exists (select 'x' from Param where 
       		PTyp= 'RMSCTG' and PMCd= RrCtg and PSCd= RrSCtg and PValue= 'BS')
 	if @row> 0
 	Begin
  		select @errmsg= 'Cannot Enter This Record As RateBy Option For This Rm SubCtg Is Already BS'
  		goto ErrHndlr
 	end
	
	/******  'BS'or 'PTR' Chart cannot be defined fot 'ZSELF' and 'ZValue'  then  ******/
	/* *** JAY 3.1.3 [CRP] */
	select @row= count('x') from inserted where RrTcTyp in ('BS','PTR','CRP') and RrCmCd in('ZSelf','ZValue')
  	if @row> 0
 	Begin
  		select @errmsg= 'BS/PTR/CRP Chart Cannot be defined for ''ZSelf''/''ZValue'' '
  		goto ErrHndlr
 	end
	/* *** JAY 3.1.3 [CRP] */
	/*************************Geeta*************************************/

/*  ######################  Manoj #### Ver: 2.0.6 #### Date: 21/01/2004  ######################  */
	/******  RrCd  =  Blank  or  valid RmCd from RmMst (RmCtg= RrCtg, RmSCtg= RrSCtg)  ******/
	select @row= count('x') from inserted Ins where Ins.RrCd<> '' and Ins.RrPrtKey=@wCurrPrtn and
  		not exists (select 'x' from RmMst where RmPrtKey=Ins.RrPrtKey and
       		RmCtg= Ins.RrCtg and RmSCtg= Ins.RrSCtg and RmCd= Ins.RrCd and RmZ= 'N' And
			(RmValidYN = 'Y' Or @Mode = 'C'))
 	if @row> 0
 	Begin
  		select @errmsg= 'Raw Material Code Not Defined / Invalid'
  		goto ErrHndlr
 	end   

/* (Bef 2.06)
	select @row= count('x') from inserted where RrCd<> '' and
  		not exists (select 'x' from RmMst where
       		RmCtg= RrCtg and RmSCtg= RrSCtg and RmCd= RrCd and RmZ= 'N')
 	if @row> 0
 	Begin
  		select @errmsg= 'Raw Material Code Not Defined'
  		goto ErrHndlr
 	end
*/
/*  #########################################  Manoj  #########################################  */

	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrCd') = 'N' 	then 	RrCd  =  Not Blank  ******/
 	select @row= count('x') from inserted where RrCd= '' and
 		 (Select TsBlank from TcStr where TsTbl= 'RmRt' and TsTyp= RrTcTyp 
		and TsSTyp= RrCtg and TsIdName= 'RrCd') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Raw Material Code Cannot Be Blank'
  		goto ErrHndlr
 	end

	/******  RrCmCtg  =  valid PMCd('CMCTG')  ******/
	/* *** JAY 3.1.3 [CRP] */
	/* **** Manali Trading Module - CmCtg ='C' added below **** */
	select @row= count('x') from inserted where @SYS= '' and RrTcTyp <> 'CRP' and RrCmCtg not in ('C', 'P', 'T', 'S')
 	if @row> 0
 	Begin
  		select @errmsg= 'Customer Catagory Should Be Either ''C'', ''P'', ''T'' Or ''S'' '
  		goto ErrHndlr
 	end
	/* *** JAY 3.1.3 [CRP] */

	/* *** JAY 3.1.3 [CRP] */
	/**Bhavna added chain***/
	select @row= count('x') from inserted where @SYS= '' and RrTcTyp in ('CRP','CHN') and RrCmCtg not in ('C', 'S')
 	if @row> 0
 	Begin
  		select @errmsg= 'Customer Catagory Should Be Either ''C'' or ''S'' '
  		goto ErrHndlr
 	end
	/* *** JAY 3.1.3 [CRP] */

	/******  If RrCmCtg  =  'T' then RrTcTyp= 'LMG' or 'LMP' ******/
	/* Manali 3.03 - 17/06/08 - 'LML' added */
	select @row= count('x') from inserted where RrCmCtg= 'T' 
		and RrTcTyp not in('LMG', 'LMP', 'LMS', 'LML', 'LS')
 	if @row> 0
 	Begin
  		select @errmsg= 'Customer Catagory Cannot Be ''T'' When TcType Is Not ''LMG'', ''LMP'', ''LMS'', ''LML'' or ''LS'' '
  		goto ErrHndlr
 	end

	/* ****** Sachin 2.12 - 07/12/05 - Dsg Code Depth in Tolerance ****** */	
	/* Manali 3.03 - 17/06/08 - 'L' added */
	select @row= count('x') from inserted Ins where Ins.RrPrtKey=@wCurrPrtn and Ins.RrTcTyp In ('QTT','WTT') 
		And RrCtg Not In ('G','P','S', 'L') 
		And Ins.RrDmCd<> '' 
		And Not Exists (select 'x' from DsgMst where DmPrtKey=RrPrtKey and DmTcTyp = 'DM' And DmCd= Ins.RrDmCd and  DmSz = '')				
		And Not Exists (Select 'x' From Deleted del Where ins.RrTcTyp=del.RrTcTyp and ins.RrCmCtg=del.RrCmCtg
						and ins.RrCmCd=del.RrCmCd and ins.RrCmCurCd=del.RrCmCurCd and ins.RrCtg=del.RrCtg and ins.RrSCtg=del.RrSCtg 
						and ins.RrSTWGrp=del.RrSTWGrp and ins.RrCd=del.RrCd and ins.RrDmCtg=del.RrDmCtg and ins.RrDmCd=del.RrDmCd
						and ins.RrLsCtg=del.RrLsCtg and ins.RrLabMCd=del.RrLabMCd and ins.RrFrLn=del.RrFrLn and ins.RrToLn=del.RrToLn And ins.RrPrtKey<>del.RrPrtKey)
 	if @row> 0
 	Begin
  		select @errmsg= 'Design Code is Not Defined'
  		goto ErrHndlr
 	end   

	select @row= count('x') from inserted Ins where Ins.RrPrtKey=@wCurrPrtn 
		and ((Ins.RrTcTyp = 'WTT' And RrCtg In ('G','P','S', 'L')) Or Ins.RrTcTyp = 'IMK')
		And Ins.RrDmCd<> '' and not exists (select 'x' from DsgMst where DmPrtKey=RrPrtKey and DmTcTyp = 'DM' And
       		DmCd= Ins.RrDmCd and  DmSz = '' And DmCtg=Ins.RrDmCtg)
		And Not Exists (Select 'x' From Deleted del Where ins.RrTcTyp=del.RrTcTyp and ins.RrCmCtg=del.RrCmCtg
						and ins.RrCmCd=del.RrCmCd and ins.RrCmCurCd=del.RrCmCurCd and ins.RrCtg=del.RrCtg and ins.RrSCtg=del.RrSCtg 
						and ins.RrSTWGrp=del.RrSTWGrp and ins.RrCd=del.RrCd and ins.RrDmCtg=del.RrDmCtg and ins.RrDmCd=del.RrDmCd
						and ins.RrLsCtg=del.RrLsCtg and ins.RrLabMCd=del.RrLabMCd and ins.RrFrLn=del.RrFrLn and ins.RrToLn=del.RrToLn And ins.RrPrtKey<>del.RrPrtKey)
 	if @row> 0
 	Begin
  		select @errmsg= 'Design Code is Not Defined'
  		goto ErrHndlr
 	end   
	/* Manali 3.03 - 17/06/08 - 'L' added */
	/* ****** Sachin 2.12 - 07/12/05 - Dsg Code Depth in Tolerance ****** */

/****Geeta***Crm***212**'WMG', 'WMP'**/
/* Zubin 212 ('MUP' added) */ 
	/********************** Geeta *********Emr206  for If RM Rate TcType='QTT' ,'WTT' RrCmCtg='C'************************/
	/******** If RM Rate TcType in ('INC','STW','INL','XIA','XIO','XZA','XDM','RSZ','PTR','BS') then RrCmCtg= 'C' ********/
	/*************Geeta*****Emr207***TcTyp='BSW'******/
	/* **** Manali Trading Module - CmCtg 'S' added */
	select @row= count('x') from inserted where RrCmCtg Not In ('C', 'S')
		and RrTcTyp in ('INC', 'STW', 'INL', 'XIA', 'XIO', 'XZA', 'XDM', 'RSZ', 'PTR','QTT','WTT','BS','BSW', 
			'MUP', 'WMG', 'WMP', 'IML')
 	if @row> 0
 	Begin
  		select @errmsg= 'Price List Cust Record Cannot Be Entered For This Tc Type'
  		goto ErrHndlr
 	end

	/* **** Manali Trading Module  */
	select @row= count('x') from inserted where RrCmCtg Not In ('C')
		and RrTcTyp in ('STW', 'XIA', 'XIO', 'XZA', 'RSZ', 'QTT','WTT','BSW', 'MUP', 'WMG', 'WMP', 'IML')
 	if @row> 0
 	Begin
  		select @errmsg= 'Price List Cust Record Cannot Be Entered For This Tc Type'
  		goto ErrHndlr
 	end

	/* *** Jay 3.01 *** [NAS NOT Included]*/ 
	/******  RrCmCd  =  valid CmCd from CustMst (CmCtg= RrCmCtg)  ******/
	select @row= count('x') from inserted where RrTcTyp not in ('NAS') and 
  		not exists (select 'x' from CustMst where CmCtg= RrCmCtg and CmCd= RrCmCd)
 	if @row> 0
 	Begin
  		select @errmsg= 'Customer Code/ Price List Customer Not Defined'
  		goto ErrHndlr
 	end

	/******  If RrTcTyp  =  'STW' or 'RSZ' then RrCmCtg= 'C' and RrCmCd= 'ZSELF' ******/
	/**********Geeta*Emr207****'BSW' ********/
	select @row= count('x') from inserted where RrTcTyp in('STW', 'RSZ','BSW') and 
  		(RrCmCtg<> 'C' or RrCmCd<> 'ZSELF') 
 	if @row> 0
 	Begin
  		select @errmsg= 'Customer Code Should Be ''ZSELF'' '
  		goto ErrHndlr
 	end

	/******  RrSTWGrp  =  Blank  or  PMCd ('STWGRP')  ******/
	select @row= count('x') from inserted where RrSTWGrp<> '' and
  		not exists (select 'x' from Param where PTyp= 'STWGRP' and PMCd= RrSTWGrp)
 	if @row> 0
 	Begin
  		select @errmsg= 'Size To Weight Group Not Defined'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrSTWGrp') = 'N' 	then 	RrSTWGrp  =  Not Blank  ******/
	select @row= count('x') from inserted where RrSTWGrp= '' and
  		(Select TsBlank from TcStr where TsTbl= 'RmRt'
   		and TsTyp= RrTcTyp and TsSTyp= RrCtg and TsIdName= 'RrSTWGrp') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Size To Weight Group Cannot Be Blank'
  		goto ErrHndlr
 	end

	/******  RrDmCtg  =  Blank  or  PMCd ('DMCTG')  ******/
	select @row= count('x') from inserted where RrDmCtg<> '' and
  		not exists (select 'x' from Param where PTyp= 'DMCTG' and PMCd= RrDmCtg)
 	if @row> 0
 	Begin
  		select @errmsg= 'Design Category Not Defined'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrDmCtg') = 'N' 	then 	RrDmCtg  =  Not Blank  ******/
	select @row= count('x') from inserted where RrDmCtg= '' and
  		(Select TsBlank from TcStr where TsTbl= 'RmRt'
   		and TsTyp= RrTcTyp and TsSTyp= RrCtg and TsIdName= 'RrDmCtg') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Design Category Cannot Be Blank'
  		goto ErrHndlr
 	end

	/******  RrLsCtg  =  Blank  or  PMCd ('LSCTG')  ******/
	select @row= count('x') from inserted where RrLsCtg<> '' and 
  		not exists (select 'x' from Param where PTyp= 'LSCTG' and PMCd= RrLsCtg)
 	if @row> 0
 	Begin
  		select @errmsg= 'Loss Category Not Defined'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrLsCtg') = 'N' 	then 	RrLsCtg  =  Not Blank  ******/
	select @row= count('x') from inserted where RrLsCtg= '' and
  		(Select TsBlank from TcStr where TsTbl= 'RmRt'
   		and TsTyp= RrTcTyp and TsSTyp= RrCtg and TsIdName= 'RrLsCtg') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Loss Category Cannot Be Blank'
  		goto ErrHndlr
 	end

	/******  RrLsCtg  =  Blank  when RrTcTyp= 'LS' and RrDmCtg= ''  ******/
	select @row= count('x') from inserted where RrTcTyp= 'LS' and RrDmCtg= '' and RrLsCtg<> '' 
 	if @row> 0
 	Begin
  		select @errmsg= 'Loss Category Should Be Blank When Dsg Ctg Is Blank'
  		goto ErrHndlr
 	end

	/******  RrLabMCd  =  Blank  or  PMCd ('LABMCD')  ******/
 	select @row= count('x') from inserted where RrLabMCd<> '' and
  		not exists (select 'x' from Param where PTyp= 'LABMCD' and PMCd= RrLabMCd)
 	if @row> 0
 	Begin
  		select @errmsg= 'Labour Main Code Not Defined'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrLabMCd') = 'N' 	then 	RrLabMCd  =  Not Blank  ******/
	select @row= count('x') from inserted where RrLabMCd= '' and
  		(Select TsBlank from TcStr where TsTbl= 'RmRt'
   		and TsTyp= RrTcTyp and TsSTyp= RrCtg and TsIdName= 'RrLabMCd') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Labour Main Code Cannot Be Blank'
