 	end

	/* Zubin 212 (18/12/05) 'ZVALUE' and 'ZSELF' can be added by Usr Lvl 1 only */ 
	select @row=count('x') from Inserted Ins where RrTcTyp= 'RM' and (RrCmCd= 'ZVALUE' or RrCmCd= 'ZSELF') and 
		Not Exists (Select 'x' from Param where PTyp= 'USR' and PMCd= Ins.ModUsr and PSCd= '' and PNum= 1) 
	if @row > 0 
 	begin
  		select @errmsg= 'Cannot Add ''ZVALUE'' and ''ZSELF'' Records As User Is Not Authorised To Do So'
  		goto ErrHndlr
 	end 

	/* Previous******************
	select @row= count('x') from inserted ins  where RrToLn< RrfRLn 
		and not(RrTcTyp= 'RM' and or exists (select 'x' from RmRt Rr where 
       		Rr.RrTcTyp='BS' and Rr.RrCmCtg='C' and Rr.RrCmCd=ins.RrCmCd and 
		Rr.RrCmCurCd='' and Rr.RrCtg=ins.RrCtg and
		Rr.RrSctg=ins.RrSctg and Rr.RrSTWGrp='' and  Rr.RrCd='' and Rr.RrDmCtg='' and 
		Rr.RrLsCtg=''  and  Rr.RrLabMCd='' and  Rr.RrFrLn='' and Rr.RrToLn='')) */

	/**********************Geeta***Emr206**05/04/04***RrToLn   >=   RrfRLn  *********/
	/* *** Jay 3.01 [NAS] *** */
	select @row= count('x') from inserted ins  where RrToLn< RrfRLn  and RrTcTyp not in ('BSW','NAS')
		and not(RrTcTyp= 'RM' and (exists(Select 'x' from RmMst 
			join Param on PTyp= 'RMSCTG' and PmCd= RmCtg and PSCd= RmSCtg 
			where RmPrtKey=RrPrtKey and RmCtg= RrCtg and RmSCtg= RrSCtg and RmCd= RrCd 
			and PValue= 'BS') or exists (select 'x' from RmRt Rr where 
       		Rr.RrTcTyp='BS' and Rr.RrCmCtg=ins.RrCmCtg and Rr.RrCmCd=ins.RrCmCd and 
		Rr.RrCmCurCd='' and Rr.RrCtg=ins.RrCtg and
		Rr.RrSctg=ins.RrSctg and Rr.RrSTWGrp='' and  Rr.RrCd='' and Rr.RrDmCtg='' and Rr.RrDmCd = '' and 
		Rr.RrLsCtg=''  and  Rr.RrLabMCd='' and  Rr.RrFrLn='' and Rr.RrToLn='' )))
 	if @row> 0
 	Begin
  		select @errmsg= 'From Value Should Be <= To Value'
  		goto ErrHndlr
 	end  
	/**********************Geeta***Emr206**05/04/04************/

	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrToLn') = 'N' 	then 	RrToLn  =  Not Zero  ******/
	select @row= count('x') from inserted where RrToLn= 0 and
  		(Select TsBlank from TcStr where TsTbl= 'RmRt'
   		and TsTyp= RrTcTyp and TsSTyp= RrCtg and TsIdName='RrToLn') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'To Value Cannot Be Zero'
  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrRngSz') = 'N' 	then 	RrRngSz  =  Not Blank  ******/
	select @row= count('x') from inserted where RrRngSz= '' and
  		(Select TsBlank from TcStr where TsTbl= 'RmRt' 
   		and TsTyp= RrTcTyp and TsSTyp= RrCtg and TsIdName= 'RrRngSz') = 'N'
 	if @row> 0
