	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrCstRt') = 'N' 	then 	RrCstRt  =  Not Blank  ******/
	select @row= count('x') from inserted where RrCstRt=0 and
  		(Select TsBlank from TcStr where TsTbl='RmRt'
   		and TsTyp= RrTcTyp and TsSTyp=RrCtg and TsIdName= 'RrCstRt') = 'N'
 	if @row> 0
 	Begin
