  		goto ErrHndlr
 	end

	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrSalRt') = 'N' 	then 	RrSalRt  =  Not Blank  ******/
	select @row= count('x') from inserted where RrSalRt= 0 and
