	/******  If RrTcTyp in ('XDM', 'XIA', 'XIO','XZA')   then 	RrCstRt <> 0 or  RrSalRt <> 0  ******/
	select @row= count('x') from inserted where RrTcTyp in('XDM', 'XIA', 'XIO','XZA') and RrCstRt= 0 and RrSalRt= 0 and RrXWtPer= 0
 	if @row> 0
 	Begin
