  		select @errmsg= 'Only One OF Extra Cents, Round Off And Extra Wt Percentage Value Should Be Entered'
  		goto ErrHndlr
 	end

	/******  If RrTcTyp in ('XDM', 'XIA', 'XIO','XZA')   and  RrSalRt<> 0  then 	RrSalRt  >=  RrToLn  ******/
	select @row= count('x') from inserted where RrTcTyp in('XDM', 'XIA', 'XIO','XZA') and RrSalRt<> 0 and RrSalRt< RrToLn
 	if @row> 0
 	Begin
  		select @errmsg= 'Round Off Value Should Be Greater Than To Wt'
  		goto ErrHndlr
 	end

	/******** all recs of 'XDM', 'XIA', 'XIO','XZA' should have Blank RmSubCtgs or all of then should have valid RmSubCtgs ********/
	select @row= count('x') from inserted ins where ins.RrTcTyp in('XDM', 'XIA', 'XIO','XZA') 
		and ins.RrSCtg<> '' and exists(Select 'x' from RmRt Rr where Rr.RrTcTyp= ins.RrTcTyp and Rr.RrSCtg= '') 
	If @Row> 0
	begin
		Select @ErrMsg= 'Record With Blank Raw Material Sub Category Exists Hence Raw Material Sub Category Should Be Blank'
		GoTo ErrHndlr
	end

	/******** all recs of 'XDM', 'XIA', 'XIO','XZA' should have Blank RmSubCtgs or all of then should have valid RmSubCtgs ********/
	select @row= count('x') from inserted ins where ins.RrTcTyp in('XDM', 'XIA', 'XIO','XZA') 
		and ins.RrSCtg= '' and exists(Select 'x' from RmRt Rr where Rr.RrTcTyp= ins.RrTcTyp and Rr.RrSCtg<> '') 
	If @Row> 0
	begin
		Select @ErrMsg= 'Record With Non Blank Raw Material Sub Category Exists Hence Raw Material Sub Category Should Not Be Blank'
		GoTo ErrHndlr
	end
	/* Zubin 213 */ 
	/* Manali 3.03 - 17/06/08 - 'LML' added */
	/* Manali 3.6.1 - 'IMK' added */
	/* bhavna removed check for CHN*/
	Select @row= count('x') from inserted where RrTcTyp Not In ('WTT','QTT','RM', 'LMG', 'LMP', 'LMS', 'LML', 'IMK', 'CHN') and RrCmCurCd<> '' 
	if @row> 0
 	Begin
		select @errmsg= 'Currency Code Should Not Be Entered'
		goto ErrHndlr
