		     Curr Cd = valid curr cd from CustMst where CmCd <> 'ZSELF' */ 
	/* Manali 3.03 - 17/06/08 - 'LML' added */
	Select @row= count('x') from inserted where @SYS= '' and RrTcTyp In ('RM', 'LMG', 'LMP', 'LMS', 'LML') and 
		(     	((RrCmCd= 'ZSELF' or RrCmCd= 'ZVALUE') and 
				Not Exists(select 'x' from Param where PTyp= 'CURNCY' and PMCd= RrCmCurCd and PSCd= '') 
		      	)
		      	Or 
		      	((RrCmCd <> 'ZSELF' and RrCmCd<> 'ZVALUE') and 
				Not exists (select 'x' from CustMst where CmCtg= RrCmCtg 
					and CmCd= RrCmCd and CmCurCd= RrCmCurCd) 
			)
		)
	if @row> 0 
	begin
		select @errmsg= 'Invalid Currency Code' 
		goto ErrHndlr
	end

