*/
	/*****************Bef Emr206************************
	select @row= count('x') from inserted ins where
  		IsNull((Select PValue from Param where PTyp= 'RMSCTG' and
                        	PMCd= RrCtg and PSCd= RrSCtg), '') <> 'BS' and
		(Select count('x') from RmRt Rt where Rt.RrTcTyp= ins.RrTcTyp and
