   		and  (    (Rt.RrFrLn<= ins.RrFrLn and
      			 Rt.RrToLn>= ins.RrFrLn)
		    or  	(Rt.RrFrLn<= ins.RrToLn and
		      	 Rt.RrToLn>= ins.RrToLn)
    		    or  	(ins.RrFrLn<= Rt.RrFrLn and
			 ins.RrToLn>= Rt.RrToLn)
		 )
  		) > 1   */


	/**********************Geeta***Emr206**05/04/04****** If 'BS' Record exists for the same 
				Combination then don't check the Size Range******/
	/******  The Size Range should be unique  (i.e. it shouldn't overlap other size 
		ranges for the same RrTcTyp, RrCmCd, RrCmCurCd, RrDmCd, RrCtg, RrSCtg, RrCd, 
		RrDmCtg, RrLabMCd combination)  ******/
	/**********Geeta*********Emr207*********Range Size Check not reqd for Both Sides Wt-'BSW'*********/ 
	/* *** JAY 3.01 [NAS] *** */
	/*bhavna removed check for CHN*/
	select @row= count('x') from inserted ins where  ins.RrTcTyp not in ('BSW', 'NAS', 'CHN') and
  		IsNull((Select PValue from Param where PTyp= 'RMSCTG' and
                        	PMCd= RrCtg and PSCd= RrSCtg), '') <> 'BS' and
		not exists (Select * from RmRt Rr where Rr.RrTcTyp= 'BS' and
   		Rr.RrCmCtg=ins.RrCmCtg and Rr.RrCmCd= ins.RrCmCd and 
		Rr.RrCmCurCd='' and Rr.RrCtg= ins.RrCtg and
   		Rr.RrSCtg= ins.RrSCtg and Rr.RrSTWGrp= '' and 
		Rr.RrCd= '' and Rr.RrDmCtg= '' and Rr.RrDmCd=ins.RrDmCd and 
		Rr.RrLsCtg= '' and Rr.RrLabMCd= '')
		and
  		(Select count('x') from RmRt Rt where Rt.RrTcTyp= ins.RrTcTyp and
   		Rt.RrCmCtg= ins.RrCmCtg and Rt.RrCmCd= ins.RrCmCd and 
		Rt.RrCmCurCd= ins.RrCmCurCd and Rt.RrCtg= ins.RrCtg and
   		Rt.RrSCtg= ins.RrSCtg and Rt.RrSTWGrp= ins.RrSTWGrp and 
		Rt.RrCd= ins.RrCd and Rt.RrDmCtg= ins.RrDmCtg and Rt.RrDmCd=ins.RrDmCd and 
		Rt.RrLsCtg= ins.RrLsCtg and Rt.RrLabMCd= ins.RrLabMCd
   		and  (    (Rt.RrFrLn<= ins.RrFrLn and
      			 Rt.RrToLn>= ins.RrFrLn)
		    or  	(Rt.RrFrLn<= ins.RrToLn and
		      	 Rt.RrToLn>= ins.RrToLn)
    		    or  	(ins.RrFrLn<= Rt.RrFrLn and
			 ins.RrToLn>= Rt.RrToLn)
		 )
