			Rr.RrSCtg= del.RrSCtg  and Rr.RrDmCtg=del.RrDmCtg and Rr.RrLabMCd=del.RrLabMCd 
			and Rr.RrLsCtg=del.RrLsCtg and Rr.RrRngSz=del.RrRngSz and 
			Rr.RrSTWGrp=del.RrSTWGrp and Rr.RrXWtPer=del.RrXWtPer and ((RrFrLn>rrToLn) or
